	}

	/**
	 * Tests columnless INSERT VALUES statements infer target columns from MySQL metadata.
	 */
	public function test_columnless_insert_values_uses_mysql_metadata_columns(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_columnless_insert (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_columnless_insert (
				id bigint(20) unsigned NOT NULL,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$insert = "INSERT INTO `wptests_columnless_insert` VALUES (1, 'one'), (2, 'two')";

		$this->assertSame( 2, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_columnless_insert" ("id", "value") VALUES (1, \'one\'), (2, \'two\')',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_columnless_insert ORDER BY id' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'value' => 'one',
				),
				(object) array(
					'id'    => '2',
					'value' => 'two',
				),
			),
			$rows
		);
	}

	/**
	 * Tests INSERT IGNORE ... SELECT without INTO keeps SQLite plugin-corpus parity.
	 */
	public function test_insert_ignore_select_without_into_translates_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_ignore_select (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$driver->query( 'CREATE TABLE wptests_insert_ignore_select_source (id INTEGER NOT NULL, value TEXT NOT NULL)' );
		$driver->query( "INSERT INTO wptests_insert_ignore_select (id, value) VALUES (1, 'existing')" );
		$driver->query( "INSERT INTO wptests_insert_ignore_select_source (id, value) VALUES (1, 'duplicate'), (2, 'new')" );

		$insert = 'INSERT IGNORE wptests_insert_ignore_select (`id`, `value`)
			SELECT id, value FROM wptests_insert_ignore_select_source ORDER BY id';

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO wptests_insert_ignore_select ("id", "value") SELECT id, value FROM wptests_insert_ignore_select_source ORDER BY id ON CONFLICT DO NOTHING',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_insert_ignore_select ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'existing' ),
				array( '2', 'new' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests simple MySQL INSERT ... SET assignments are translated to PostgreSQL.
	 */
	public function test_simple_insert_set_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_set (id INTEGER PRIMARY KEY, value TEXT NOT NULL, attempts INTEGER NOT NULL)' );

		$insert = "INSERT INTO wptests_insert_set SET id = 1, value = 'one', attempts = 2";

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (1, \'one\', 2)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value, attempts FROM wptests_insert_set' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( '2', $rows[0]->attempts );

		$insert_ignore = "INSERT IGNORE wptests_insert_set SET id = 1, value = 'ignored', attempts = 3";

		$this->assertSame( 0, $driver->query( $insert_ignore ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (1, \'ignored\', 3) ON CONFLICT DO NOTHING',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT value, attempts FROM wptests_insert_set WHERE id = 1' );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( '2', $rows[0]->attempts );

		$qualified_insert = "INSERT INTO wptests_insert_set SET wptests_insert_set.id = 2, wptests_insert_set.value = 'two', wptests.wptests_insert_set.attempts = 4";

		$this->assertSame( 1, $driver->query( $qualified_insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (2, \'two\', 4)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT value, attempts FROM wptests_insert_set WHERE id = 2' );
		$this->assertSame( 'two', $rows[0]->value );
		$this->assertSame( '4', $rows[0]->attempts );
	}

	/**
	 * Tests INSERT ... SET accepts unquoted keyword column names.
	 */
	public function test_insert_set_accepts_unquoted_name_column_target(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_set_name (id INTEGER PRIMARY KEY, name TEXT NOT NULL, attempts INTEGER NOT NULL)' );

		$this->assertSame(
			1,
			$driver->query(
				"INSERT INTO wptests_insert_set_name SET id = 1, name = UPPER('alpha'), attempts = 1 + 2"
			)
		);

		$rows = $driver->query( 'SELECT id, name, attempts FROM wptests_insert_set_name' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'ALPHA', $rows[0]->name );
		$this->assertSame( '3', $rows[0]->attempts );
	}

	/**
	 * Tests MySQL INSERT priority modifiers are accepted as compatibility no-ops.
	 */
	public function test_insert_priority_modifiers_are_accepted_as_noops(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_priority (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$driver->query( 'CREATE TABLE wptests_insert_priority_source (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$driver->query( "INSERT INTO wptests_insert_priority_source (id, value) VALUES (2, 'delayed-select')" );

		$this->assertSame( 1, $driver->query( "INSERT LOW_PRIORITY INTO wptests_insert_priority (id, value) VALUES (1, 'low')" ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_priority" ("id", "value") VALUES (1, \'low\')',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$this->assertSame( 0, $driver->query( "INSERT HIGH_PRIORITY IGNORE INTO wptests_insert_priority (id, value) VALUES (1, 'ignored')" ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_priority" ("id", "value") VALUES (1, \'ignored\') ON CONFLICT DO NOTHING',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$this->assertSame(
			1,
			$driver->query(
				'INSERT DELAYED INTO wptests_insert_priority (id, value)
				SELECT id, value FROM wptests_insert_priority_source'
			)
		);
		$this->assertSame(
			'INSERT INTO wptests_insert_priority (id, value) SELECT id, value FROM wptests_insert_priority_source',
			$this->get_last_single_postgresql_sql( $driver )
		);
		$this->assertStringNotContainsString( 'DELAYED', $this->get_last_single_postgresql_sql( $driver ) );

		$this->assertSame( 1, $driver->query( "INSERT LOW_PRIORITY INTO wptests_insert_priority SET id = 3, value = 'low-set'" ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_priority" ("id", "value") VALUES (3, \'low-set\')',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_insert_priority ORDER BY id' );
		$this->assertSame( array( '1', '2', '3' ), array_column( $rows, 'id' ) );
		$this->assertSame( array( 'low', 'delayed-select', 'low-set' ), array_column( $rows, 'value' ) );
	}

	/**
	 * Tests unsupported INSERT ... SET shapes fail before backend execution.
	 */
	public function test_unsupported_insert_set_shapes_fail_closed_before_backend(): void {
		$queries = array(
			'INSERT INTO wptests_insert_set SET id = 1, id = 2',
			'INSERT INTO wptests_insert_set SET other_table.id = 1',
			'INSERT INTO wptests_insert_set SET other_db.wptests_insert_set.id = 1',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported INSERT statement.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported INSERT statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests unsupported INSERT shapes fail before backend execution.
	 */
	public function test_unsupported_insert_shapes_fail_closed_before_backend(): void {
		$queries = array(
			'INSERT INTO wptests_insert_unsupported PARTITION (p0) (id) VALUES (1)',
			'INSERT INTO wptests_insert_unsupported (id) VALUES (1) RETURNING id',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported INSERT statement.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported INSERT statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests non-strict INSERT statements append metadata-derived NOT NULL defaults.
	 */
	public function test_non_strict_insert_appends_omitted_not_null_defaults_from_mysql_metadata(): void {
		$driver = $this->create_driver();
		$driver->set_sql_mode( '' );

		$driver->query(
			'CREATE TABLE wptests_comments (
				comment_ID INTEGER PRIMARY KEY,
				comment_author TEXT NOT NULL,
				comment_author_email TEXT NOT NULL,
				comment_content TEXT NOT NULL,
				comment_parent INTEGER NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_comments (
				comment_ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				comment_author tinytext NOT NULL,
				comment_author_email varchar(100) NOT NULL DEFAULT '',
				comment_content text NOT NULL,
				comment_parent bigint(20) unsigned NOT NULL DEFAULT '0',
				PRIMARY KEY (comment_ID)
			)"
		);

		$comment_insert = 'INSERT INTO `wptests_comments` (`comment_ID`) VALUES (1)';

		$this->assertSame( 1, $driver->query( $comment_insert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_comments" ("comment_ID", "comment_author", "comment_author_email", "comment_content", "comment_parent") VALUES (1, \'\', \'\', \'\', \'0\')',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$comments = $driver->query( 'SELECT comment_author, comment_author_email, comment_content, comment_parent FROM wptests_comments WHERE comment_ID = 1' );
		$this->assertSame( '', $comments[0]->comment_author );
		$this->assertSame( '', $comments[0]->comment_author_email );
		$this->assertSame( '', $comments[0]->comment_content );
		$this->assertSame( '0', $comments[0]->comment_parent );

		$driver->query(
			'CREATE TABLE wptests_posts (
				"ID" INTEGER PRIMARY KEY,
				post_date TEXT NOT NULL,
				post_content TEXT NOT NULL,
				post_title TEXT NOT NULL,
				post_excerpt TEXT NOT NULL,
				post_status TEXT NOT NULL,
				post_parent INTEGER NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_posts (
				ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				post_date datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
				post_content longtext NOT NULL,
				post_title text NOT NULL,
				post_excerpt text NOT NULL,
				post_status varchar(20) NOT NULL DEFAULT 'publish',
				post_parent bigint(20) unsigned NOT NULL DEFAULT '0',
				PRIMARY KEY (ID)
			)"
		);

		$post_insert = "INSERT INTO `wptests_posts` (`ID`, `post_title`) VALUES (1, 'Post 1')";

		$this->assertSame( 1, $driver->query( $post_insert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_posts" ("ID", "post_title", "post_date", "post_content", "post_excerpt", "post_status", "post_parent") VALUES (1, \'Post 1\', \'0000-00-00 00:00:00\', \'\', \'\', \'publish\', \'0\')',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$posts = $driver->query( 'SELECT post_date, post_content, post_excerpt, post_status, post_parent FROM wptests_posts WHERE ID = 1' );
		$this->assertSame( '0000-00-00 00:00:00', $posts[0]->post_date );
		$this->assertSame( '', $posts[0]->post_content );
		$this->assertSame( '', $posts[0]->post_excerpt );
		$this->assertSame( 'publish', $posts[0]->post_status );
		$this->assertSame( '0', $posts[0]->post_parent );
	}

