	/**
	 * Tests REPLACE ... SET statements delete then insert known conflicts and keep MySQL row counts.
	 */
	public function test_replace_set_with_known_conflict_column_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_options (
				option_id INTEGER PRIMARY KEY,
				option_name TEXT NOT NULL UNIQUE,
				option_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_options (option_id, option_name, option_value) VALUES (1, 'siteurl', 'old')" );

		$replace = "REPLACE INTO `wptests_options` SET `option_id` = 8, `option_name` = 'siteurl', `option_value` = 'updated'";

		$this->assertSame( 2, $driver->query( $replace ) );
		$this->assert_last_postgresql_sql_statements(
			$driver,
			array(
				'DELETE FROM "wptests_options" WHERE ("option_name" = \'siteurl\')',
				'INSERT INTO "wptests_options" ("option_id", "option_name", "option_value") VALUES (8, \'siteurl\', \'updated\')',
			)
		);

		$rows = $driver->query( "SELECT option_id, option_value FROM wptests_options WHERE option_name = 'siteurl'" );
		$this->assertCount( 1, $rows );
		$this->assertSame( '8', $rows[0]->option_id );
		$this->assertSame( 'updated', $rows[0]->option_value );

		$replace = "REPLACE `wptests_options` SET `option_id` = 9, `option_name` = 'home', `option_value` = 'created'";

		$this->assertSame( 1, $driver->query( $replace ) );
		$this->assert_last_postgresql_sql_statements(
			$driver,
			array(
				'DELETE FROM "wptests_options" WHERE ("option_name" = \'home\')',
				'INSERT INTO "wptests_options" ("option_id", "option_name", "option_value") VALUES (9, \'home\', \'created\')',
			)
		);

		$rows = $driver->query( 'SELECT option_name, option_value FROM wptests_options ORDER BY option_id' );
		$this->assertCount( 2, $rows );
		$this->assertSame( 'siteurl', $rows[0]->option_name );
		$this->assertSame( 'updated', $rows[0]->option_value );
		$this->assertSame( 'home', $rows[1]->option_name );
		$this->assertSame( 'created', $rows[1]->option_value );

		$qualified_replace = "REPLACE INTO `wptests_options` SET `wptests_options`.`option_id` = 10, `wptests_options`.`option_name` = 'home', `wptests`.`wptests_options`.`option_value` = 'qualified'";

		$this->assertSame( 2, $driver->query( $qualified_replace ) );
		$this->assert_last_postgresql_sql_statements(
			$driver,
			array(
				'DELETE FROM "wptests_options" WHERE ("option_name" = \'home\')',
				'INSERT INTO "wptests_options" ("option_id", "option_name", "option_value") VALUES (10, \'home\', \'qualified\')',
			)
		);

		$rows = $driver->query( "SELECT option_id, option_value FROM wptests_options WHERE option_name = 'home'" );
		$this->assertCount( 1, $rows );
		$this->assertSame( '10', $rows[0]->option_id );
		$this->assertSame( 'qualified', $rows[0]->option_value );
	}

	/**
	 * Tests REPLACE priority modifiers are no-ops for SET and SELECT forms.
	 */
	public function test_replace_priority_modifiers_apply_to_set_and_select_forms(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_replace_priority (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_replace_priority_source (
				id INTEGER NOT NULL,
				value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_replace_priority (id, value) VALUES (1, 'old')" );
		$driver->query( "INSERT INTO wptests_replace_priority_source (id, value) VALUES (1, 'selected'), (2, 'new')" );

		$replace_set = "REPLACE LOW_PRIORITY INTO wptests_replace_priority SET id = 1, value = 'set'";

		$this->assertSame( 2, $driver->query( $replace_set ) );
		$this->assert_last_postgresql_sql_statements(
			$driver,
			array(
				'DELETE FROM "wptests_replace_priority" WHERE ("id" = 1)',
				'INSERT INTO "wptests_replace_priority" ("id", "value") VALUES (1, \'set\')',
			)
		);

		$replace_select = 'REPLACE DELAYED INTO wptests_replace_priority (id, value)
			SELECT id, value FROM wptests_replace_priority_source';

		$this->assertSame( 3, $driver->query( $replace_select ) );
		$sql = $this->assert_last_replace_select_materialized_sql( $driver, 'wptests_replace_priority' );
		$this->assertStringContainsString(
			' AS SELECT id AS "id" , value AS "value" FROM wptests_replace_priority_source',
			$sql[1]
		);
		$this->assertStringNotContainsString( 'DELAYED', implode( "\n", $sql ) );

		$rows = $driver->query( 'SELECT id, value FROM wptests_replace_priority ORDER BY id' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'value' => 'selected',
				),
				(object) array(
					'id'    => '2',
					'value' => 'new',
				),
			),
			$rows
		);
	}

