	/**
	 * Tests main database-qualified DROP TABLE removes tables and MySQL metadata.
	 */
	public function test_drop_table_accepts_main_database_qualified_table_names(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_qualified_drop_one (id int NOT NULL, PRIMARY KEY (id))' );
		$driver->query( 'CREATE TABLE wptests_qualified_drop_two (id int NOT NULL, PRIMARY KEY (id))' );
		$driver->store_mysql_schema_metadata( 'CREATE TABLE wptests_qualified_drop_one (id int NOT NULL, PRIMARY KEY (id))' );
		$driver->store_mysql_schema_metadata( 'CREATE TABLE wptests_qualified_drop_two (id int NOT NULL, PRIMARY KEY (id))' );

		$this->assertNotSame( array(), $this->get_mysql_column_metadata_rows( $driver, 'wptests_qualified_drop_one' ) );
		$this->assertNotSame( array(), $this->get_mysql_index_metadata_rows( $driver, 'wptests_qualified_drop_two' ) );

		$this->assertSame(
			0,
			$driver->query( 'DROP TABLE IF EXISTS wptests.wptests_qualified_drop_one, wptests.wptests_qualified_drop_two' )
		);
		$this->assertSame(
			array(
				array(
					'sql'    => 'DROP TABLE IF EXISTS "wptests_qualified_drop_one"',
					'params' => array(),
				),
				array(
					'sql'    => 'DROP TABLE IF EXISTS "wptests_qualified_drop_two"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertFalse( $this->sqlite_table_exists( $driver, 'main', 'wptests_qualified_drop_one' ) );
		$this->assertFalse( $this->sqlite_table_exists( $driver, 'main', 'wptests_qualified_drop_two' ) );
		$this->assertSame( array(), $this->get_mysql_column_metadata_rows( $driver, 'wptests_qualified_drop_one' ) );
		$this->assertSame( array(), $this->get_mysql_index_metadata_rows( $driver, 'wptests_qualified_drop_two' ) );
	}

	/**
	 * Tests DROP TABLE accepts MySQL RESTRICT/CASCADE suffixes as no-ops.
	 */
	public function test_drop_table_accepts_restrict_and_cascade_suffixes_as_noops(): void {
		foreach ( array( 'RESTRICT', 'CASCADE' ) as $suffix ) {
			$driver     = $this->create_driver();
			$table_name = 'wptests_drop_table_' . strtolower( $suffix );

			$driver->query( sprintf( 'CREATE TABLE %s (id int NOT NULL, PRIMARY KEY (id))', $table_name ) );
			$driver->store_mysql_schema_metadata( sprintf( 'CREATE TABLE %s (id int NOT NULL, PRIMARY KEY (id))', $table_name ) );

			$this->assertNotSame( array(), $this->get_mysql_column_metadata_rows( $driver, $table_name ) );
			$this->assertSame( 0, $driver->query( sprintf( 'DROP TABLE %s %s', $table_name, $suffix ) ) );
			$this->assertSame(
				array(
					array(
						'sql'    => sprintf( 'DROP TABLE "%s"', $table_name ),
						'params' => array(),
					),
				),
				$driver->get_last_postgresql_queries()
			);

			$this->assertFalse( $this->sqlite_table_exists( $driver, 'main', $table_name ) );
			$this->assertSame( array(), $this->get_mysql_column_metadata_rows( $driver, $table_name ) );
		}
	}

	/**
	 * Tests DROP TABLE uses the selected PostgreSQL catalog schema.
	 */
	public function test_drop_table_uses_current_postgresql_catalog_schema_after_use(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured metadata-table catalog checks.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Captured ON UPDATE trigger catalog checks.
			 *
			 * @var array[]
			 */
			private $trigger_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/drop-table queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if (
					false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE )
					|| false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE )
					|| false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE )
					|| false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE )
					|| false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE )
				) {
					throw new RuntimeException( 'Hidden schema metadata table access was not expected for catalog-backed DROP TABLE.' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					return parent::query(
						'plugin_schema' === (string) ( $params[1] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_trigger tr' ) ) {
					$this->trigger_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						'plugin_table' === (string) ( $params[1] ?? '' )
							? "SELECT 'updated_at' AS attname"
							: 'SELECT NULL AS attname WHERE 0 = 1'
					);
				}

				if (
					0 === strpos( $sql, 'DROP TRIGGER IF EXISTS ' )
					|| 0 === strpos( $sql, 'DROP FUNCTION IF EXISTS ' )
				) {
					return parent::query( 'SELECT 1' );
				}

				if ( 0 === strpos( $sql, 'DROP TABLE ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}

			/**
			 * Get captured ON UPDATE trigger catalog checks.
			 *
			 * @return array[] Trigger catalog checks.
			 */
			public function get_trigger_catalog_checks(): array {
				return $this->trigger_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertSame( 0, $driver->query( 'USE plugin_schema' ) );
		$this->assertSame( array( 'wptests', 'plugin_schema' ), $driver->get_last_postgresql_queries()[0]['params'] );

		$this->assertSame( 0, $driver->query( 'DROP TABLE plugin_table' ) );
		$hash = md5( "plugin_schema\0plugin_table\0updated_at" );
		$this->assertSame(
			array(
				array(
					'sql'    => 'DROP TRIGGER IF EXISTS "__wp_pg_on_update_' . $hash . '" ON "plugin_schema"."plugin_table"',
					'params' => array(),
				),
				array(
					'sql'    => 'DROP FUNCTION IF EXISTS "plugin_schema"."__wp_pg_on_update_fn_' . $hash . '"()',
					'params' => array(),
				),
				array(
					'sql'    => 'DROP TABLE "plugin_schema"."plugin_table"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame( 0, $driver->query( 'DROP TABLE IF EXISTS plugin_schema.plugin_table_two' ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'DROP TABLE IF EXISTS "plugin_schema"."plugin_table_two"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertCount( 2, $connection->get_trigger_catalog_checks() );
		$this->assertStringContainsString( 'pg_catalog.pg_trigger tr', $connection->get_trigger_catalog_checks()[0]['sql'] );
		$this->assertSame( array( 'plugin_schema', 'plugin_table' ), $connection->get_trigger_catalog_checks()[0]['params'] );
		$this->assertStringContainsString( 'pg_catalog.pg_trigger tr', $connection->get_trigger_catalog_checks()[1]['sql'] );
		$this->assertSame( array( 'plugin_schema', 'plugin_table_two' ), $connection->get_trigger_catalog_checks()[1]['params'] );
	}

	/**
	 * Tests unsupported standalone index DDL fails before backend execution.
	 */
	public function test_standalone_index_unsupported_syntax_does_not_reach_backend(): void {
		$queries = array(
			'CREATE INDEX idx_value ON wptests_index_fail (value) KEY_BLOCK_SIZE=bad',
			'CREATE INDEX idx_value ON wptests_index_fail (value) ALGORITHM=INSTANT',
			'CREATE INDEX idx_value ON wptests_index_fail (value) LOCK=UNKNOWN',
			'CREATE INDEX idx_value ON wptests_index_fail (value) ENGINE_ATTRIBUTE="{}"',
			'CREATE INDEX idx_value ON wptests_index_fail (value) WITH PARSER ngram',
			'CREATE FULLTEXT INDEX idx_value ON wptests_index_fail (value) COMMENT "Lookup"',
			'CREATE SPATIAL INDEX idx_value ON wptests_index_fail (value) KEY_BLOCK_SIZE=8',
			'CREATE INDEX IF NOT EXISTS "wptests_index_fail__" ON "wptests_index_fail" ("value")',
			'CREATE INDEX idx_value ON information_schema.tables (name)',
			'CREATE INDEX idx_value ON other_db.wptests_index_fail (value)',
			'DROP INDEX idx_value ON wptests_index_fail KEY_BLOCK_SIZE=8',
			'DROP INDEX idx_value ON wptests_index_fail ALGORITHM=INSTANT',
			'DROP INDEX idx_value ON wptests_index_fail LOCK=UNKNOWN',
			'DROP INDEX idx_value ON information_schema.tables',
			'DROP INDEX idx_value ON other_db.wptests_index_fail',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();
			$driver->query( 'CREATE TABLE wptests_index_fail (value varchar(255) NOT NULL)' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported standalone index DDL to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertContains(
					$e->getMessage(),
					array(
						'Unsupported CREATE INDEX statement.',
						'Unsupported DROP INDEX statement.',
						'Unsupported information_schema query.',
					),
					$query
				);
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests plain CREATE TABLE secondary KEY/INDEX definitions use the MySQL DDL translator.
	 */
	public function test_create_table_plain_secondary_indexes_use_mysql_translator(): void {
		$driver = $this->create_driver();

		$this->assertSame(
			0,
			$driver->query(
				'CREATE TABLE wptests_plain_secondary_indexes (
					id INT NOT NULL,
					slug VARCHAR(20) NOT NULL,
					value INT,
					KEY slug_lookup (slug),
					INDEX value_lookup (value)
				)'
			)
		);

		$this->assertSame(
			array(
				array(
					'sql'    => 'CREATE TABLE "wptests_plain_secondary_indexes" (
  "id" integer NOT NULL,
  "slug" varchar(20) NOT NULL,
  "value" integer
)',
					'params' => array(),
				),
				array(
					'sql'    => 'CREATE INDEX "wptests_plain_secondary_indexes__slug_lookup" ON "wptests_plain_secondary_indexes" ("slug")',
					'params' => array(),
				),
				array(
					'sql'    => 'CREATE INDEX "wptests_plain_secondary_indexes__value_lookup" ON "wptests_plain_secondary_indexes" ("value")',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$index_rows = $driver->query( 'SHOW INDEX FROM wptests_plain_secondary_indexes' );
		$this->assertSame( array( 'slug_lookup', 'value_lookup' ), array_column( $index_rows, 'Key_name' ) );

		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_plain_secondary_indexes' )[0]->{'Create Table'};
		$this->assertStringContainsString( 'KEY `slug_lookup` (`slug`)', $create_table );
		$this->assertStringContainsString( 'KEY `value_lookup` (`value`)', $create_table );
	}

