	}

	/**
	 * Tests LAST_INSERT_ID(id) upsert updates expose an existing AUTO_INCREMENT id.
	 */
	public function test_upsert_last_insert_id_assignment_exposes_existing_auto_increment_value(): void {
		$driver = $this->create_driver_with_stale_connection_insert_id();

		$this->install_identity_unique_upsert_table_with_mysql_metadata( $driver );
		$driver->get_connection()->query( "INSERT INTO wptests_identity_unique_upsert (id, slug, value) VALUES (7, 'existing', 'old')" );

		$upsert = "INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
			VALUES ('existing', 'updated')
			ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`),
			                        `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame( 7, $driver->get_insert_id() );
		$this->assertSame(
			'INSERT INTO "wptests_identity_unique_upsert" ("slug", "value") VALUES (\'existing\', \'updated\') ON CONFLICT ("slug") DO UPDATE SET "id" = "wptests_identity_unique_upsert"."id", "value" = excluded."value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, slug, value FROM wptests_identity_unique_upsert ORDER BY id' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '7', $rows[0]->id );
		$this->assertSame( 'existing', $rows[0]->slug );
		$this->assertSame( 'updated', $rows[0]->value );

		$select_upsert = "INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
			SELECT 'existing', 'selected' FROM DUAL
			ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`),
			                        `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $select_upsert ) );
		$this->assertSame( 7, $driver->get_insert_id() );
		$this->assertSame(
			'INSERT INTO "wptests_identity_unique_upsert" ("slug", "value") SELECT \'existing\', \'selected\' ON CONFLICT ("slug") DO UPDATE SET "id" = "wptests_identity_unique_upsert"."id", "value" = excluded."value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, slug, value FROM wptests_identity_unique_upsert ORDER BY id' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '7', $rows[0]->id );
		$this->assertSame( 'existing', $rows[0]->slug );
		$this->assertSame( 'selected', $rows[0]->value );

		$insert_driver = $this->create_driver();
		$this->install_identity_unique_upsert_table_with_mysql_metadata( $insert_driver );
		$insert = "INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
			VALUES ('new', 'created')
			ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`),
			                        `value` = VALUES(`value`)";

		$this->assertSame( 1, $insert_driver->query( $insert ) );
		$this->assertSame( 1, $insert_driver->get_insert_id() );
	}

	/**
	 * Tests WooCommerce-style session upserts with WordPress %i double-quoted table identifiers.
	 */
	public function test_double_quoted_table_identifier_upsert_and_select_are_translated(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_woocommerce_sessions (
				session_id INTEGER PRIMARY KEY,
				session_key TEXT NOT NULL UNIQUE,
				session_value TEXT NOT NULL,
				session_expiry INTEGER NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_woocommerce_sessions (
				session_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				session_key char(32) NOT NULL,
				session_value longtext NOT NULL,
				session_expiry bigint(20) unsigned NOT NULL,
				PRIMARY KEY (session_id),
				UNIQUE KEY session_key (session_key)
			)'
		);

		$upsert = "INSERT INTO \"wptests_woocommerce_sessions\" (`session_key`, `session_value`, `session_expiry`)
			VALUES ('session-key', 'first', 1781870576)
			ON DUPLICATE KEY UPDATE `session_value` = VALUES(`session_value`), `session_expiry` = VALUES(`session_expiry`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_woocommerce_sessions" ("session_key", "session_value", "session_expiry") VALUES (\'session-key\', \'first\', 1781870576) ON CONFLICT ("session_key") DO UPDATE SET "session_value" = excluded."session_value", "session_expiry" = excluded."session_expiry"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$duplicate_upsert = "INSERT INTO \"wptests_woocommerce_sessions\" (`session_key`, `session_value`, `session_expiry`)
			VALUES ('session-key', 'second', 1781870577)
			ON DUPLICATE KEY UPDATE `session_value` = VALUES(`session_value`), `session_expiry` = VALUES(`session_expiry`)";

		$this->assertSame( 1, $driver->query( $duplicate_upsert ) );

		$rows = $driver->query( "SELECT session_value, session_expiry FROM \"wptests_woocommerce_sessions\" WHERE session_key = 'session-key'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'second', $rows[0]->session_value );
		$this->assertSame( '1781870577', $rows[0]->session_expiry );
		$this->assertSame(
			'SELECT session_value, session_expiry FROM "wptests_woocommerce_sessions" WHERE session_key = \'session-key\'',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$count_rows = $driver->query( "SELECT COUNT(*) AS session_count FROM \"wptests_woocommerce_sessions\" WHERE session_key = 'session-key'" );

		$this->assertCount( 1, $count_rows );
		$this->assertSame( '1', $count_rows[0]->session_count );
		$this->assertSame(
			'SELECT COUNT(*) AS session_count FROM "wptests_woocommerce_sessions" WHERE session_key = \'session-key\'',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests LAST_INSERT_ID(id) duplicate updates preserve target-row references in expressions.
	 */
	public function test_upsert_last_insert_id_values_and_row_count_readback_after_duplicate_update(): void {
		$driver = $this->create_driver_with_stale_connection_insert_id();

		$driver->query(
			'CREATE TABLE wp_acid_upsert (
				id INTEGER PRIMARY KEY,
				slug TEXT NOT NULL UNIQUE,
				hits INTEGER NOT NULL DEFAULT 0,
				updated_at TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wp_acid_upsert (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				slug varchar(191) NOT NULL,
				hits int(11) NOT NULL DEFAULT 0,
				updated_at datetime NOT NULL,
				PRIMARY KEY (id),
				UNIQUE KEY slug (slug)
			)'
		);
		$driver->get_connection()->query( "INSERT INTO wp_acid_upsert (id, slug, hits, updated_at) VALUES (7, 'same', 1, '0000-00-00 00:00:00')" );

		$upsert = "INSERT INTO wp_acid_upsert (slug, hits, updated_at) VALUES ('same', 2, '2001-01-01 00:00:00')
			ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id), hits = hits + VALUES(hits), updated_at = VALUES(updated_at)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame( 7, $driver->get_insert_id() );
		$this->assertSame(
			'INSERT INTO "wp_acid_upsert" ("slug", "hits", "updated_at") VALUES (\'same\', 2, \'2001-01-01 00:00:00\') ON CONFLICT ("slug") DO UPDATE SET "id" = "wp_acid_upsert"."id", "hits" = "wp_acid_upsert"."hits" + excluded."hits", "updated_at" = excluded."updated_at"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query(
			"SELECT LAST_INSERT_ID() AS last_id, ROW_COUNT() AS row_count_value, hits, updated_at
			FROM wp_acid_upsert
			WHERE slug = 'same'"
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( '7', $rows[0]->last_id );
		$this->assertSame( '1', $rows[0]->row_count_value );
		$this->assertSame( '3', $rows[0]->hits );
		$this->assertSame( '2001-01-01 00:00:00', $rows[0]->updated_at );

		$now_upsert  = "INSERT INTO wp_acid_upsert (slug, hits, updated_at) VALUES ('same', 2, NOW())
			ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id), hits = hits + VALUES(hits), updated_at = VALUES(updated_at)";
		$translation = $this->translate_driver_query_data_with_private_method(
			$driver,
			'translate_mysql_on_duplicate_key_update_query',
			$now_upsert
		);

		$this->assertNotNull( $translation );
		$this->assertSame(
			'INSERT INTO "wp_acid_upsert" ("slug", "hits", "updated_at") VALUES (\'same\', 2, TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE \'UTC\', \'YYYY-MM-DD HH24:MI:SS\')) ON CONFLICT ("slug") DO UPDATE SET "id" = "wp_acid_upsert"."id", "hits" = "wp_acid_upsert"."hits" + excluded."hits", "updated_at" = excluded."updated_at"',
			$translation['sql']
		);
	}

