		$insert = "INSERT INTO `wptests_options` SET `option_name` = 'siteurl',
			`option_value` = 'http://example.org',
			`autoload` = 'yes'
			ON DUPLICATE KEY UPDATE `option_value` = VALUES(`option_value`),
