			'CREATE TABLE wptests_upsert_current_timestamp_defaults (
				id bigint(20) unsigned NOT NULL,
				updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
				touched_at timestamp NOT NULL DEFAULT (now()),
