		$connection = new class( array( 'pdo' => $this->create_pgsql_reporting_sqlite_pdo() ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured column catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_queries = array();

			/**
			 * Execute fixture-backed DML metadata queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHARSET_METADATA_TABLE,
					) as $metadata_table
				) {
					if ( 1 === preg_match( '/\b(?:FROM|JOIN)\s+"?' . preg_quote( $metadata_table, '/' ) . '"?/i', $sql ) ) {
						throw new RuntimeException( 'Hidden metadata table relation was not expected for PostgreSQL-backed current-schema joined UPDATE metadata.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					return parent::query(
						'plugin_schema' === (string) ( $params[1] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$this->catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					if ( 'plugin_schema' !== (string) ( $params[0] ?? '' ) ) {
						throw new RuntimeException( 'Joined UPDATE metadata should resolve against the selected PostgreSQL schema: ' . json_encode( $params ) );
					}

					if ( 3 === count( $params ) && false !== strpos( $sql, 'SELECT c.column_name' ) ) {
						return parent::query( 'SELECT ? AS column_name', array( $params[2] ) );
					}

					$column_type = in_array( strtolower( (string) ( $params[2] ?? '' ) ), array( 'id', 'post_id' ), true )
						? 'int'
						: 'text';

					return parent::query( "SELECT '{$column_type}' AS column_type" );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured column catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_queries(): array {
				return $this->catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$pdo        = $connection->get_pdo();

		$pdo->exec( "ATTACH DATABASE ':memory:' AS plugin_schema" );
		$pdo->exec( 'CREATE TABLE plugin_schema.catalog_current_schema_join_target (id INTEGER NOT NULL, status TEXT NOT NULL)' );
		$pdo->exec( 'CREATE TABLE plugin_schema.catalog_current_schema_join_source (post_id INTEGER NOT NULL, meta_key TEXT NOT NULL, meta_value TEXT NOT NULL)' );
		$pdo->exec( "INSERT INTO plugin_schema.catalog_current_schema_join_target (id, status) VALUES (1, 'draft'), (2, 'draft')" );
		$pdo->exec( "INSERT INTO plugin_schema.catalog_current_schema_join_source (post_id, meta_key, meta_value) VALUES (1, '_status', 'publish'), (2, '_other', 'private')" );

		$this->assertSame( 0, $driver->query( 'USE plugin_schema' ) );

		$update = "UPDATE catalog_current_schema_join_target AS p JOIN catalog_current_schema_join_source AS pm ON p.id = pm.post_id SET p.status = pm.meta_value WHERE pm.meta_key = '_status'";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame(
			'UPDATE "plugin_schema"."catalog_current_schema_join_target" AS "p" SET "status" = pm.meta_value FROM "plugin_schema"."catalog_current_schema_join_source" AS "pm" WHERE (p.id = pm.post_id) AND (pm.meta_key = \'_status\') AND ("p"."status" IS DISTINCT FROM (pm.meta_value))',
			$this->get_last_single_postgresql_sql( $driver )
		);
		$this->assertNotEmpty( $connection->get_catalog_queries() );

		$rows = $pdo->query( 'SELECT id, status FROM plugin_schema.catalog_current_schema_join_target ORDER BY id' )->fetchAll( PDO::FETCH_OBJ );
		$this->assertEquals(
			array(
				(object) array(
					'id'     => '1',
					'status' => 'publish',
				),
				(object) array(
					'id'     => '2',
					'status' => 'draft',
				),
			),
			$rows
		);
	}

	/**
	 * Tests derived joined UPDATE sources use the selected PostgreSQL catalog schema after USE.
	 */
	public function test_derived_joined_update_sources_use_current_postgresql_catalog_schema_after_use_without_metadata_tables(): void {
		$connection = new class( array( 'pdo' => $this->create_pgsql_reporting_sqlite_pdo() ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured column catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_queries = array();

			/**
			 * Execute fixture-backed DML metadata queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHARSET_METADATA_TABLE,
					) as $metadata_table
				) {
					if ( 1 === preg_match( '/\b(?:FROM|JOIN)\s+"?' . preg_quote( $metadata_table, '/' ) . '"?/i', $sql ) ) {
						throw new RuntimeException( 'Hidden metadata table relation was not expected for PostgreSQL-backed current-schema derived joined UPDATE metadata.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					return parent::query(
						'plugin_schema' === (string) ( $params[1] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$this->catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					if ( 'plugin_schema' !== (string) ( $params[0] ?? '' ) ) {
						throw new RuntimeException( 'Derived joined UPDATE metadata should resolve against the selected PostgreSQL schema: ' . json_encode( $params ) );
					}

					if ( 2 === count( $params ) ) {
						return parent::query(
							"SELECT 'id' AS column_name, 1 AS ordinal_position, 'int' AS column_type, 'NO' AS is_nullable, NULL AS column_default, '' AS extra
							UNION ALL SELECT 'status', 2, 'text', 'NO', NULL, ''
							UNION ALL SELECT 'post_id', 1, 'int', 'NO', NULL, ''
							UNION ALL SELECT 'meta_key', 2, 'text', 'NO', NULL, ''
							UNION ALL SELECT 'meta_value', 3, 'text', 'NO', NULL, ''"
						);
					}

					if ( 3 === count( $params ) && false !== strpos( $sql, 'SELECT c.column_name' ) ) {
						return parent::query( 'SELECT ? AS column_name', array( $params[2] ) );
					}

					$column_type = in_array( strtolower( (string) ( $params[2] ?? '' ) ), array( 'id', 'post_id' ), true )
						? 'int'
						: 'text';

					return parent::query( "SELECT '{$column_type}' AS column_type" );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured column catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_queries(): array {
				return $this->catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertSame( 0, $driver->query( 'USE plugin_schema' ) );

		$ordered_update = "UPDATE catalog_current_schema_join_target AS p
			JOIN catalog_current_schema_join_source AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE pm.meta_key = '_status'
			ORDER BY pm.meta_value ASC
			LIMIT 1";

		$ordered_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$ordered_update
		);

		$this->assertNotNull( $ordered_sql );
		$this->assertStringContainsString( 'UPDATE "plugin_schema"."catalog_current_schema_join_target" AS "p"', $ordered_sql );
		$this->assertStringContainsString( 'FROM "plugin_schema"."catalog_current_schema_join_target" AS "p" JOIN "plugin_schema"."catalog_current_schema_join_source" AS "pm" ON p.id = pm.post_id', $ordered_sql );
		$this->assertStringContainsString( 'ORDER BY pm.meta_value ASC LIMIT 1', $ordered_sql );

		$outer_update = "UPDATE catalog_current_schema_join_target AS p
			LEFT JOIN catalog_current_schema_join_source AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE p.status = 'draft'";

		$outer_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$outer_update
		);

		$this->assertNotNull( $outer_sql );
		$this->assertStringContainsString( 'UPDATE "plugin_schema"."catalog_current_schema_join_target" AS "p"', $outer_sql );
		$this->assertStringContainsString( 'FROM "plugin_schema"."catalog_current_schema_join_target" AS "p" LEFT JOIN "plugin_schema"."catalog_current_schema_join_source" AS "pm" ON p.id = pm.post_id', $outer_sql );
		$this->assertNotEmpty( $connection->get_catalog_queries() );
	}

	/**
	 * Tests joined UPDATE ORDER BY without LIMIT is preserved in a derived source.
	 */
	public function test_joined_update_order_by_without_limit_preserves_ordering(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_order (
				ctid INTEGER UNIQUE NOT NULL,
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_order_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined_order (ctid, id, status) VALUES (1, 1, 'draft'), (2, 2, 'draft'), (3, 3, 'publish')" );
		$driver->query( "INSERT INTO wptests_update_joined_order_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'private'), (2, '_status', 'scheduled'), (3, '_other', 'ignore')" );

		$update = "UPDATE wptests_update_joined_order AS p
			JOIN wptests_update_joined_order_meta AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE pm.meta_key = '_status'
			ORDER BY pm.meta_value ASC, p.id DESC";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_joined_order" AS "p" SET "status" = "mysql_update_values"."mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( "WHERE (p.id = pm.post_id) AND (pm.meta_key = '_status') ORDER BY pm.meta_value ASC, p.id DESC", $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined_order ORDER BY id' );
		$this->assertSame( 'private', $rows[0]->status );
		$this->assertSame( 'scheduled', $rows[1]->status );
		$this->assertSame( 'publish', $rows[2]->status );
	}

	/**
	 * Tests joined UPDATE expression ORDER BY clauses without LIMIT are translated.
	 */
	public function test_joined_update_expression_order_by_without_limit_is_translated(): void {
		$driver = $this->create_driver();

		$update = "UPDATE wptests_update_joined_order AS p
			JOIN wptests_update_joined_order_meta AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE pm.meta_key = '_status'
			ORDER BY LENGTH(pm.meta_value), p.id + 0 DESC";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$update
		);

		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'ORDER BY CASE WHEN ', $sql );
		$this->assertStringContainsString( 'ELSE OCTET_LENGTH(CONVERT_TO(CAST(pm.meta_value AS text), \'UTF8\')) END, p.id + 0 DESC', $sql );
	}

	/**
	 * Tests bounded joined UPDATE ORDER BY/LIMIT forms update the intended matched row slice.
	 */
	public function test_joined_update_order_by_limit_updates_ordered_slice(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_limit (
				ctid INTEGER UNIQUE NOT NULL,
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_limit_meta (
				post_id INTEGER NOT NULL,
				priority INTEGER NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_update_joined_limit (ctid, id, status) VALUES
				(1, 1, 'queued'),
				(2, 2, 'queued'),
				(3, 3, 'queued'),
				(4, 4, 'done')"
		);
		$driver->query(
			"INSERT INTO wptests_update_joined_limit_meta (post_id, priority, meta_value) VALUES
				(1, 30, 'third'),
				(2, 10, 'first'),
				(3, 20, 'second'),
				(4, 1, 'skip')"
		);

		$update = "UPDATE wptests_update_joined_limit AS p
			JOIN wptests_update_joined_limit_meta AS pm ON pm.post_id = p.id
			SET p.status = pm.meta_value
			WHERE p.status = 'queued'
			ORDER BY pm.priority ASC, p.id DESC
			LIMIT 1, 2";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( "WHERE (pm.post_id = p.id) AND (p.status = 'queued') ORDER BY pm.priority ASC, p.id DESC LIMIT 2 OFFSET 1", $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined_limit ORDER BY id' );
		$this->assertSame( 'third', $rows[0]->status );
		$this->assertSame( 'queued', $rows[1]->status );
		$this->assertSame( 'second', $rows[2]->status );
		$this->assertSame( 'done', $rows[3]->status );

		$comma_update = "UPDATE wptests_update_joined_limit AS p, wptests_update_joined_limit_meta AS pm
			SET p.status = 'limited'
			WHERE pm.post_id = p.id AND p.status = 'queued'
			LIMIT 1";

		$this->assertSame( 1, $driver->query( $comma_update ) );
		$this->assertStringContainsString( 'LIMIT 1', $this->get_last_single_postgresql_sql( $driver ) );
	}

	/**
	 * Tests MySQL inner joined UPDATE statements support derived-table sources.
	 */
	public function test_inner_join_update_with_derived_source_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_derived (
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_derived_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined_derived (id, status) VALUES (1, 'draft'), (2, 'draft')" );
		$driver->query( "INSERT INTO wptests_update_joined_derived_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'publish'), (2, '_other', 'private')" );

		$update = "UPDATE wptests_update_joined_derived AS p
			JOIN (
				SELECT post_id, meta_value
				FROM wptests_update_joined_derived_meta
				WHERE meta_key = '_status'
			) AS src ON p.id = src.post_id
			SET p.status = src.meta_value
			WHERE p.id IN (1, 2)";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame( 0, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'FROM (SELECT post_id, meta_value FROM wptests_update_joined_derived_meta WHERE meta_key = \'_status\') AS "src"', $sql );
		$this->assertStringContainsString( '(p.id = src.post_id)', $sql );
		$this->assertStringContainsString( '("p"."status" IS DISTINCT FROM (src.meta_value))', $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined_derived ORDER BY id' );
		$this->assertSame( 'publish', $rows[0]->status );
		$this->assertSame( 'draft', $rows[1]->status );
	}

	/**
	 * Tests Action Scheduler claim UPDATE uses ordered limited derived sources.
	 */
	public function test_action_scheduler_claim_update_with_ordered_limited_derived_source(): void {
		$driver = $this->create_driver();

		$driver->set_sql_mode( '' );
		$driver->query(
			"CREATE TABLE wptests_actionscheduler_actions (
				action_id INTEGER PRIMARY KEY,
				status TEXT NOT NULL,
				scheduled_date_gmt TEXT NULL default '0000-00-00 00:00:00',
				scheduled_date_local TEXT NULL default '0000-00-00 00:00:00',
				priority INTEGER NOT NULL default '10',
				attempts INTEGER NOT NULL default '0',
				last_attempt_gmt TEXT NULL default '0000-00-00 00:00:00',
				last_attempt_local TEXT NULL default '0000-00-00 00:00:00',
				claim_id INTEGER NOT NULL default '0'
			)"
		);
		$driver->query(
			"INSERT INTO wptests_actionscheduler_actions
				(action_id, status, scheduled_date_gmt, scheduled_date_local, priority, attempts, claim_id)
			VALUES
				(1, 'pending', '2025-09-03 12:00:00', '2025-09-03 12:00:00', 20, 1, 0),
				(2, 'pending', '2025-09-03 11:00:00', '2025-09-03 11:00:00', 5, 2, 0),
				(3, 'complete', '2025-09-03 10:00:00', '2025-09-03 10:00:00', 1, 0, 0),
				(4, 'pending', '2025-09-03 09:00:00', '2025-09-03 09:00:00', 1, 0, 9),
				(5, 'pending', '2025-09-04 09:00:00', '2025-09-04 09:00:00', 1, 0, 0)"
		);

		$update = "UPDATE wptests_actionscheduler_actions t1
			JOIN (
				SELECT action_id
				FROM wptests_actionscheduler_actions
				WHERE claim_id = 0 AND scheduled_date_gmt <= '2025-09-03 12:23:55' AND status = 'pending'
				ORDER BY priority ASC, attempts ASC, scheduled_date_gmt ASC, action_id ASC
				LIMIT 2
				FOR UPDATE
			) t2 ON t1.action_id = t2.action_id
			SET claim_id = 37, last_attempt_gmt = '2025-09-03 12:23:55', last_attempt_local = '2025-09-03 12:23:55'";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'ORDER BY priority ASC, attempts ASC, scheduled_date_gmt ASC, action_id ASC LIMIT 2', $sql );
		$this->assertStringNotContainsString( 'FOR UPDATE', $sql );

		$rows = $driver->query( 'SELECT action_id, claim_id, last_attempt_gmt, last_attempt_local FROM wptests_actionscheduler_actions ORDER BY action_id' );
		$this->assertSame( array( '37', '37', '0', '9', '0' ), array_column( $rows, 'claim_id' ) );
		$this->assertSame( '2025-09-03 12:23:55', $rows[0]->last_attempt_gmt );
		$this->assertSame( '2025-09-03 12:23:55', $rows[1]->last_attempt_local );
		$this->assertSame( '0000-00-00 00:00:00', $rows[2]->last_attempt_gmt );
	}

	/**
	 * Tests MySQL inner joined UPDATE ... USING statements translate to PostgreSQL predicates.
	 */
	public function test_inner_join_update_using_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_using (
				post_id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_using_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined_using (post_id, status) VALUES (1, 'draft'), (2, 'draft')" );
		$driver->query( "INSERT INTO wptests_update_joined_using_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'publish'), (2, '_other', 'private')" );

		$update = "UPDATE wptests_update_joined_using AS p INNER JOIN wptests_update_joined_using_meta AS pm USING (post_id) SET p.status = pm.meta_value WHERE pm.meta_key = '_status'";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame( 0, $driver->query( $update ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'UPDATE "wptests_update_joined_using" AS "p" SET "status" = pm.meta_value FROM "wptests_update_joined_using_meta" AS "pm" WHERE (p.post_id = pm.post_id) AND (pm.meta_key = \'_status\') AND ("p"."status" IS DISTINCT FROM (pm.meta_value))',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( 'SELECT post_id, status FROM wptests_update_joined_using ORDER BY post_id' );
		$this->assertSame( 'publish', $rows[0]->status );
		$this->assertSame( 'draft', $rows[1]->status );
	}

	/**
	 * Tests joined UPDATE can target a non-leftmost table and MySQL join modifiers.
	 */
	public function test_joined_update_non_leftmost_target_and_join_modifiers_translate_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_join_source (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_join_target (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_join_source (id, value) VALUES (1, 'one'), (2, 'two'), (3, 'three')" );
		$driver->query( "INSERT INTO wptests_update_join_target (id, value) VALUES (1, 'old'), (2, 'old'), (3, 'old')" );

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE wptests_update_join_source AS s
				JOIN wptests_update_join_target AS t ON t.id = s.id
				SET t.value = s.value
				WHERE s.id = 1'
			)
		);
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_join_target" AS "t" SET "value" = s.value FROM "wptests_update_join_source" AS "s"', $sql );
		$this->assertStringContainsString( '(t.id = s.id)', $sql );

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE LOW_PRIORITY wptests_update_join_target AS t
				CROSS JOIN wptests_update_join_source AS s
				SET t.value = s.value
				WHERE t.id = s.id AND t.id = 2'
			)
		);

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE IGNORE wptests_update_join_target AS t
				STRAIGHT_JOIN wptests_update_join_source AS s ON s.id = t.id
				SET t.value = s.value
				WHERE t.id = 3'
			)
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_update_join_target ORDER BY id' );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( 'two', $rows[1]->value );
		$this->assertSame( 'three', $rows[2]->value );
	}

	/**
	 * Tests joined UPDATE IGNORE skips rows that would violate unique constraints.
	 */
	public function test_joined_update_ignore_unique_conflict_returns_zero_and_preserves_rows(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_ignore_join_target (
				id INTEGER PRIMARY KEY,
				slug TEXT NOT NULL UNIQUE,
				note TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_ignore_join_source (
				id INTEGER PRIMARY KEY,
				new_slug TEXT NOT NULL,
				new_note TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_ignore_join_target (id, slug, note) VALUES (1, 'a', 'first'), (2, 'b', 'second')" );
		$driver->query( "INSERT INTO wptests_update_ignore_join_source (id, new_slug, new_note) VALUES (2, 'a', 'changed')" );

		$update = 'UPDATE IGNORE wptests_update_ignore_join_target AS t
			JOIN wptests_update_ignore_join_source AS s ON s.id = t.id
			SET t.slug = s.new_slug, t.note = s.new_note
			WHERE t.id = 2';

		$this->assertSame( 0, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_ignore_join_target" AS "t" SET "slug" = s.new_slug, "note" = s.new_note', $sql );
		$this->assertStringContainsString( 'FROM "wptests_update_ignore_join_source" AS "s"', $sql );

		$rows = $driver->query( 'SELECT id, slug, note FROM wptests_update_ignore_join_target ORDER BY id' );

		$this->assertSame( array( 'a', 'b' ), array_column( $rows, 'slug' ) );
		$this->assertSame( array( 'first', 'second' ), array_column( $rows, 'note' ) );
	}

	/**
	 * Tests MySQL multi-target UPDATE statements translate to PostgreSQL writable CTEs.
	 */
	public function test_multi_target_update_is_translated_to_writable_ctes(): void {
		$driver = $this->create_driver();

		$update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id AND s.id = 1';

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$update
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'WITH mysql_update_rows AS MATERIALIZED', $sql );
		$this->assertStringContainsString( 'SELECT "s".ctid AS "mysql_update_0_ctid", t.value AS "mysql_update_value_0", "t".ctid AS "mysql_update_1_ctid", s.value AS "mysql_update_value_1"', $sql );
		$this->assertStringContainsString( 'FROM "wptests_update_source" AS "s", "wptests_update_target" AS "t"', $sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id AND s.id = 1)', $sql );
		$this->assertStringContainsString( 'mysql_update_target_0 AS (UPDATE "wptests_update_source" AS "s" SET "value" = mysql_update_rows."mysql_update_value_0" FROM mysql_update_rows WHERE ("s".ctid = mysql_update_rows."mysql_update_0_ctid")', $sql );
		$this->assertStringContainsString( 'mysql_update_target_1 AS (UPDATE "wptests_update_target" AS "t" SET "value" = mysql_update_rows."mysql_update_value_1" FROM mysql_update_rows WHERE ("t".ctid = mysql_update_rows."mysql_update_1_ctid")', $sql );
		$this->assertStringContainsString( 'SELECT (SELECT COUNT(*) FROM mysql_update_target_0) + (SELECT COUNT(*) FROM mysql_update_target_1) AS affected_rows', $sql );

		$join_update = 'UPDATE wptests_update_source AS s
			JOIN wptests_update_target AS t ON t.id = s.id
			SET s.value = t.value, t.value = s.value
			WHERE s.id = 1';
		$join_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$join_update
		);

		$this->assertNotNull( $join_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) AND (s.id = 1)', $join_sql );
		$this->assertStringNotContainsString( 'ORDER BY', $join_sql );

		$ordered_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			ORDER BY t.id DESC, LENGTH(s.value)';
		$ordered_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$ordered_update
		);

		$this->assertNotNull( $ordered_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id)', $ordered_sql );
		$this->assertStringContainsString( 'ORDER BY t.id DESC, CASE WHEN ', $ordered_sql );
		$this->assertStringContainsString( 'ELSE OCTET_LENGTH(CONVERT_TO(CAST(s.value AS text), \'UTF8\')) END', $ordered_sql );

		$limited_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			ORDER BY t.id DESC, s.value ASC
			LIMIT 1, 2';
		$limited_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$limited_update
		);

		$this->assertNotNull( $limited_sql );
		$this->assertStringContainsString( 'WITH mysql_update_rows AS MATERIALIZED', $limited_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) ORDER BY t.id DESC, s.value ASC LIMIT 2 OFFSET 1', $limited_sql );

		$limit_only_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			LIMIT 2';
		$limit_only_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$limit_only_update
		);

		$this->assertNotNull( $limit_only_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) LIMIT 2', $limit_only_sql );
		$this->assertStringNotContainsString( 'ORDER BY', $limit_only_sql );

		$single_target_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value
			WHERE t.id = s.id';

		$this->assertNull(
			$this->translate_driver_query_with_private_method(
				$driver,
				'translate_mysql_multi_target_update_query',
				$single_target_update
			)
		);
	}

	/**
	 * Tests joined UPDATE statements can read from information_schema sources.
	 */
	public function test_joined_update_can_read_information_schema_sources(): void {
		$driver = $this->create_driver();
		$this->install_direct_information_schema_options_metadata( $driver );

		$update = 'UPDATE wptests_options AS o
			JOIN information_schema.tables AS it ON o.option_name = it.table_name
			SET o.option_value = it.table_type
			WHERE it.table_schema = DATABASE()
			ORDER BY it.table_name';

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$update
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'UPDATE "wptests_options" AS "o" SET "option_value" = "mysql_update_values"."mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'SELECT "o".ctid AS "mysql_update_target_ctid", "it"."TABLE_TYPE" AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'FROM "wptests_options" AS "o" JOIN (', $sql );
		$this->assertStringContainsString( ') AS "it" ON "o"."option_name" = "it"."TABLE_NAME"', $sql );
		$this->assertStringContainsString( 'WHERE "it"."TABLE_SCHEMA" = \'wptests\'', $sql );
		$this->assertStringContainsString( 'ORDER BY "it"."TABLE_NAME"', $sql );
		$this->assertStringContainsString( '"o".ctid = "mysql_update_values"."mysql_update_target_ctid"', $sql );
		$this->assertStringContainsString( '"o"."option_value" IS DISTINCT FROM ("mysql_update_values"."mysql_update_value_0")', $sql );
	}

