			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_mixed_ambiguous_filter (
				id INTEGER PRIMARY KEY
			)'
		);

		try {
			$driver->query(
				"UPDATE wptests_update_mixed_ambiguous_source AS s, wptests_update_mixed_ambiguous_target AS t
				JOIN wptests_update_mixed_ambiguous_filter AS f ON f.id = s.id
				SET status = 'updated'
				WHERE t.id = s.id
					AND t.id = f.id"
			);
			$this->fail( 'Expected unsupported UPDATE statement to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported UPDATE statement.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests MySQL LEFT JOIN UPDATE statements preserve unmatched source rows.
	 */
	public function test_left_join_update_is_translated_through_derived_ctid_source(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_left_joined (
				id INTEGER PRIMARY KEY,
				author_id INTEGER NOT NULL,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_left_joined_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_left_joined (id, author_id, status) VALUES (1, 10, 'draft'), (2, 20, 'draft'), (3, 30, 'publish')" );
		$driver->query( "INSERT INTO wptests_update_left_joined_meta (post_id, meta_key, meta_value) VALUES (10, '_status', 'scheduled'), (10, '_other', 'ignored')" );

		$update = "UPDATE wptests_update_left_joined AS p
			LEFT JOIN wptests_update_left_joined_meta AS pm
				ON pm.post_id = p.author_id AND pm.meta_key = '_status'
			SET p.status = IFNULL(pm.meta_value, 'orphan')
			WHERE p.status = 'draft'
			ORDER BY LENGTH(p.status), p.id DESC";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$update
		);

		$this->assertStringStartsWith(
			'UPDATE "wptests_update_left_joined" AS "p" SET "status" = "mysql_update_values"."mysql_update_value_0" FROM (SELECT "p".ctid AS "mysql_update_target_ctid", COALESCE(pm.meta_value, \'orphan\') AS "mysql_update_value_0"',
			$sql
		);
		$this->assertStringContainsString( "WHERE p.status = 'draft' ORDER BY CASE WHEN ", $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(p.status AS text), 'UTF8')) END, p.id DESC", $sql );
		$this->assertStringContainsString( '"p".ctid = "mysql_update_values"."mysql_update_target_ctid"', $sql );
	}

	/**
	 * Tests bounded UPDATE ORDER BY/LIMIT forms translate through PostgreSQL ctid.
	 */
	public function test_simple_update_order_by_limit_translates_to_ctid_subquery(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			'UPDATE wptests_update_limited SET `value` = 4 WHERE value > 0 LIMIT 2'
		);

		$this->assertSame(
			'UPDATE "wptests_update_limited" SET "value" = 4 WHERE (ctid IN (SELECT ctid FROM "wptests_update_limited" WHERE value > 0 LIMIT 2)) AND ("value" IS DISTINCT FROM (4))',
			$sql
		);

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			'UPDATE wptests_update_limited SET `value` = 3 LIMIT 1'
		);

		$this->assertSame(
			'UPDATE "wptests_update_limited" SET "value" = 3 WHERE (ctid IN (SELECT ctid FROM "wptests_update_limited" LIMIT 1)) AND ("value" IS DISTINCT FROM (3))',
			$sql
		);

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			'UPDATE wptests_update_limited SET `value` = 9 WHERE id > 0 ORDER BY id DESC LIMIT 1'
		);

		$this->assertSame(
			'UPDATE "wptests_update_limited" SET "value" = 9 WHERE (ctid IN (SELECT ctid FROM "wptests_update_limited" WHERE id > 0 ORDER BY id DESC LIMIT 1)) AND ("value" IS DISTINCT FROM (9))',
			$sql
		);

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			'UPDATE wptests_update_limited SET `value` = 7 WHERE id > 0 ORDER BY id DESC LIMIT 1, 2'
		);

		$this->assertSame(
			'UPDATE "wptests_update_limited" SET "value" = 7 WHERE (ctid IN (SELECT ctid FROM "wptests_update_limited" WHERE id > 0 ORDER BY id DESC LIMIT 2 OFFSET 1)) AND ("value" IS DISTINCT FROM (7))',
			$sql
		);

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			'UPDATE wptests_update_limited SET `value` = 5 WHERE id > 0 ORDER BY id DESC LIMIT 2 OFFSET 1'
		);

		$this->assertSame(
			'UPDATE "wptests_update_limited" SET "value" = 5 WHERE (ctid IN (SELECT ctid FROM "wptests_update_limited" WHERE id > 0 ORDER BY id DESC LIMIT 2 OFFSET 1)) AND ("value" IS DISTINCT FROM (5))',
			$sql
		);
	}

	/**
	 * Tests unsupported bounded UPDATE ORDER BY/LIMIT forms fail before backend execution.
	 */
	public function test_unsupported_simple_update_order_by_limit_shapes_fail_closed_before_backend(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_unsupported_limit (
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);

		foreach (
			array(
				"UPDATE wptests_update_unsupported_limit SET status = 'x' LIMIT bad",
				"UPDATE wptests_update_unsupported_limit SET status = 'x' ORDER BY id LIMIT bad",
				"UPDATE wptests_update_unsupported_limit SET status = 'x' ORDER BY id LIMIT 1, bad",
			) as $query
		) {
			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported UPDATE statement.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported UPDATE statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests bounded UPDATE ORDER BY/LIMIT/OFFSET updates the intended ordered slice.
	 */
	public function test_simple_update_order_by_limit_executes_ordered_offset_slice(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_order_limit_exec (
				ctid INTEGER UNIQUE NOT NULL,
				id INTEGER PRIMARY KEY,
				priority INTEGER NOT NULL,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_update_order_limit_exec (ctid, id, priority, status) VALUES
				(1, 1, 40, 'queued'),
				(2, 2, 20, 'queued'),
				(3, 3, 10, 'queued'),
				(4, 4, 30, 'queued')"
		);

		$update = "UPDATE wptests_update_order_limit_exec AS q
			SET q.status = 'claimed'
			WHERE q.status = 'queued'
			ORDER BY q.priority ASC, q.id ASC
			LIMIT 1, 2";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'ctid IN (SELECT "q".ctid FROM "wptests_update_order_limit_exec" AS "q"', $sql );
		$this->assertStringContainsString( 'ORDER BY q.priority ASC, q.id ASC LIMIT 2 OFFSET 1', $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_order_limit_exec ORDER BY id' );
		$this->assertSame( 'queued', $rows[0]->status );
		$this->assertSame( 'claimed', $rows[1]->status );
		$this->assertSame( 'queued', $rows[2]->status );
		$this->assertSame( 'claimed', $rows[3]->status );
	}

