	/**
	 * Tests fractional temporal runtime functions are translated with bounded MySQL precision.
	 */
	public function test_fractional_temporal_runtime_functions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT CURRENT_TIMESTAMP(6) AS current_timestamp_fsp,
				NOW(3) AS now_fsp,
				CURRENT_TIME(2) AS current_time_fsp,
				UTC_TIME(1) AS utc_time_fsp,
				LOCALTIMESTAMP(4) AS localtimestamp_fsp'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( "LEFT(TO_CHAR(CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), 26) AS current_timestamp_fsp", $sql );
		$this->assertStringContainsString( "LEFT(TO_CHAR(CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), 23) AS now_fsp", $sql );
		$this->assertStringContainsString( "LEFT(TO_CHAR(CURRENT_TIMESTAMP(2) AT TIME ZONE 'UTC', 'HH24:MI:SS.US'), 11) AS current_time_fsp", $sql );
		$this->assertStringContainsString( "LEFT(TO_CHAR(CURRENT_TIMESTAMP(1) AT TIME ZONE 'UTC', 'HH24:MI:SS.US'), 10) AS utc_time_fsp", $sql );
		$this->assertStringContainsString( "LEFT(TO_CHAR(CURRENT_TIMESTAMP(4) AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), 24) AS localtimestamp_fsp", $sql );
		$this->assertStringNotContainsString( 'CURRENT_TIMESTAMP(6) AS current_timestamp_fsp', $sql );
		$this->assertStringNotContainsString( 'NOW(3)', $sql );
		$this->assertStringNotContainsString( 'CURRENT_TIME(2)', $sql );
	}

	/**
	 * Tests DATE() and DATEDIFF() guard zero-date values before PostgreSQL casts.
	 */
	public function test_mysql_date_and_datediff_runtime_functions_guard_zero_date_casts_for_postgresql(): void {
		$driver = $this->create_driver();

		$select = "SELECT DATE('0000-00-00 13:05:00') AS zero_date,
			DATE('2020-00-15 13:05:00') AS partial_date,
			DATEDIFF('2024-01-05', '0000-00-00') AS diff_zero,
			DATEDIFF('2020-00-15', '2020-01-15') AS diff_partial";
		$sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			$select
		);

		$this->assertStringContainsString( $this->get_expected_mysql_date_sql( "'0000-00-00 13:05:00'" ) . ' AS zero_date', $sql );
		$this->assertStringContainsString( $this->get_expected_mysql_date_sql( "'2020-00-15 13:05:00'" ) . ' AS partial_date', $sql );
		$this->assertStringContainsString( $this->get_expected_mysql_datediff_sql( "'2024-01-05'", "'0000-00-00'" ) . ' AS diff_zero', $sql );
		$this->assertStringContainsString( $this->get_expected_mysql_datediff_sql( "'2020-00-15'", "'2020-01-15'" ) . ' AS diff_partial', $sql );
		$this->assertStringContainsString( "THEN SUBSTRING(CAST('0000-00-00 13:05:00' AS text) FROM 1 FOR 10)", $sql );
		$this->assertStringContainsString( "THEN SUBSTRING(CAST('2020-00-15 13:05:00' AS text) FROM 1 FOR 10)", $sql );
		$this->assertStringNotContainsString( "TO_CHAR(CAST('0000-00-00 13:05:00' AS timestamp)", $sql );
		$this->assertStringNotContainsString( "CAST('0000-00-00' AS date)", $sql );
		$this->assertStringNotContainsString( "CAST('2020-00-15' AS date)", $sql );
	}

	/**
	 * Tests SQLite UDF-style REGEXP(pattern, value) runtime calls are translated.
	 */
	public function test_regexp_runtime_function_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
				REGEXP('^rss_.+$', 'RSS_123') AS case_insensitive_match,
				REGEXP('^rss_.+$', 'feed_123') AS no_match,
				REGEXP(NULL, 'RSS_123') AS null_pattern,
				REGEXP('^rss', NULL) AS null_value"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString(
			"CASE WHEN CAST('^rss_.+$' AS text) IS NULL OR CAST('RSS_123' AS text) IS NULL THEN NULL WHEN CAST('RSS_123' AS text) ~* CAST('^rss_.+$' AS text) THEN 1 ELSE 0 END AS case_insensitive_match",
			$sql
		);
		$this->assertStringContainsString(
			"CASE WHEN CAST('^rss_.+$' AS text) IS NULL OR CAST('feed_123' AS text) IS NULL THEN NULL WHEN CAST('feed_123' AS text) ~* CAST('^rss_.+$' AS text) THEN 1 ELSE 0 END AS no_match",
			$sql
		);
		$this->assertStringContainsString(
			"CASE WHEN CAST(NULL AS text) IS NULL OR CAST('RSS_123' AS text) IS NULL THEN NULL WHEN CAST('RSS_123' AS text) ~* CAST(NULL AS text) THEN 1 ELSE 0 END AS null_pattern",
			$sql
		);
		$this->assertStringContainsString(
			"CASE WHEN CAST('^rss' AS text) IS NULL OR CAST(NULL AS text) IS NULL THEN NULL WHEN CAST(NULL AS text) ~* CAST('^rss' AS text) THEN 1 ELSE 0 END AS null_value",
			$sql
		);
		$this->assertStringNotContainsString( 'REGEXP(', $sql );
	}

	/**
	 * Tests nested MySQL base64 runtime functions from the SQLite parity suite are translated.
	 */
	public function test_nested_base64_runtime_functions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$select = "SELECT
			TO_BASE64(FROM_BASE64('dGVzdA==')) AS encoded_round_trip,
			FROM_BASE64(TO_BASE64('binary')) AS decoded_round_trip,
			COALESCE(FROM_BASE64(''), 'fallback') AS empty_decoded";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			$select
		);

		$this->assertStringContainsString( "ENCODE(CONVERT_TO(CAST(CASE WHEN CAST('dGVzdA==' AS text) IS NULL OR CAST('dGVzdA==' AS text) !~", $sql );
		$this->assertStringContainsString( "ELSE CONVERT_FROM(DECODE(CAST('dGVzdA==' AS text), 'base64'), 'UTF8') END AS text), 'UTF8'), 'base64') AS encoded_round_trip", $sql );
		$this->assertStringContainsString( "CASE WHEN CAST(ENCODE(CONVERT_TO(CAST('binary' AS text), 'UTF8'), 'base64') AS text) IS NULL OR CAST(ENCODE(CONVERT_TO(CAST('binary' AS text), 'UTF8'), 'base64') AS text) !~", $sql );
		$this->assertStringContainsString( "ELSE CONVERT_FROM(DECODE(CAST(ENCODE(CONVERT_TO(CAST('binary' AS text), 'UTF8'), 'base64') AS text), 'base64'), 'UTF8') END AS decoded_round_trip", $sql );
		$this->assertStringContainsString( "COALESCE(CASE WHEN CAST('' AS text) IS NULL OR CAST('' AS text) !~", $sql );
		$this->assertStringContainsString( "ELSE CONVERT_FROM(DECODE(CAST('' AS text), 'base64'), 'UTF8') END, 'fallback') AS empty_decoded", $sql );
		$this->assertStringNotContainsString( 'FROM_BASE64', $sql );
		$this->assertStringNotContainsString( 'TO_BASE64', $sql );
	}

	/**
	 * Tests NULL-only MySQL base64 runtime calls still trigger PostgreSQL translation.
	 */
	public function test_null_base64_runtime_functions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT FROM_BASE64(NULL) AS decoded_null, TO_BASE64(NULL) AS encoded_null'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'CASE WHEN CAST(NULL AS text) IS NULL OR CAST(NULL AS text) !~', $sql );
		$this->assertStringContainsString( "ELSE CONVERT_FROM(DECODE(CAST(NULL AS text), 'base64'), 'UTF8') END AS decoded_null", $sql );
		$this->assertStringContainsString( "ENCODE(CONVERT_TO(CAST(NULL AS text), 'UTF8'), 'base64') AS encoded_null", $sql );
		$this->assertStringNotContainsString( 'FROM_BASE64', $sql );
		$this->assertStringNotContainsString( 'TO_BASE64', $sql );
	}

	/**
	 * Tests malformed MySQL FROM_BASE64() input returns NULL instead of surfacing a PostgreSQL DECODE error.
	 */
	public function test_invalid_from_base64_runtime_function_is_guarded_for_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT FROM_BASE64('not base64!') AS decoded_invalid, LENGTH(FROM_BASE64('abc')) AS invalid_length"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( "CASE WHEN CAST('not base64!' AS text) IS NULL OR CAST('not base64!' AS text) !~", $sql );
		$this->assertStringContainsString( "THEN NULL ELSE CONVERT_FROM(DECODE(CAST('not base64!' AS text), 'base64'), 'UTF8') END AS decoded_invalid", $sql );
		$this->assertStringContainsString( "CASE WHEN CAST('abc' AS text) IS NULL OR CAST('abc' AS text) !~", $sql );
		$this->assertStringContainsString( "THEN NULL ELSE OCTET_LENGTH(DECODE(CAST('abc' AS text), 'base64')) END AS invalid_length", $sql );
		$this->assertStringNotContainsString( 'FROM_BASE64', $sql );
	}

	/**
	 * Tests JSON_VALID() runtime calls fold constants and use native dynamic fallback.
	 */
	public function test_json_valid_runtime_function_folds_constants_and_uses_native_fallback_for_dynamic_values(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT JSON_VALID(\'{"ok":true}\') AS object_valid,
				JSON_VALID(CONCAT(\'{"ok":\', \'true}\')) AS concat_object_valid,
				JSON_VALID(CONCAT_WS(\'\', \'[\', \'1\', \']\')) AS concat_array_valid,
				JSON_VALID(REPLACE(\'{"bad":true}\', \'bad\', \'ok\')) AS replace_object_valid,
				JSON_VALID(SUBSTRING(\'xx[1]\', 3)) AS substring_array_valid,
				JSON_VALID(IFNULL(NULL, \'{"fallback":true}\')) AS ifnull_object_valid,
				JSON_VALID(CONCAT(\'{\', NULL, \'}\')) AS concat_null_valid,
				JSON_VALID(NULLIF(\'[1]\', \'[1]\')) AS nullif_null_valid,
				JSON_VALID(\'not json\') AS invalid_json,
				JSON_VALID(NULL) AS null_valid,
				JSON_VALID(payload) AS payload_valid
			FROM runtime_names'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( '1 AS object_valid', $sql );
		$this->assertStringContainsString( '1 AS concat_object_valid', $sql );
		$this->assertStringContainsString( '1 AS concat_array_valid', $sql );
		$this->assertStringContainsString( '1 AS replace_object_valid', $sql );
		$this->assertStringContainsString( '1 AS substring_array_valid', $sql );
		$this->assertStringContainsString( '1 AS ifnull_object_valid', $sql );
		$this->assertStringContainsString( 'NULL AS concat_null_valid', $sql );
		$this->assertStringContainsString( 'NULL AS nullif_null_valid', $sql );
		$this->assertStringContainsString( '0 AS invalid_json', $sql );
		$this->assertStringContainsString( 'NULL AS null_valid', $sql );
		$this->assertStringContainsString( 'CASE WHEN payload IS NULL THEN NULL ELSE json_valid(CAST(payload AS text)) END AS payload_valid', $sql );
		$this->assertStringNotContainsString( '__wp_pg_mysql_json_valid', $sql );
		$this->assertStringNotContainsString( 'JSON_VALID', $sql );
		$this->assertStringNotContainsString( 'pg_input_is_valid', $sql );
	}

	/**
	 * Tests JSON_VALID() dynamic values use native PostgreSQL validation on pgsql connections.
	 */
	public function test_json_valid_runtime_function_uses_pg_input_is_valid_for_dynamic_pgsql_values(): void {
		$connection = new WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection(
			array(
				'pdo' => $this->create_pgsql_reporting_sqlite_pdo(),
			)
		);
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT JSON_VALID(\'{"ok":true}\') AS object_valid, JSON_VALID(\'not json\') AS invalid_json, JSON_VALID(NULL) AS null_valid, JSON_VALID(payload) AS payload_valid FROM runtime_names'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( '1 AS object_valid', $sql );
		$this->assertStringContainsString( '0 AS invalid_json', $sql );
		$this->assertStringContainsString( 'NULL AS null_valid', $sql );
		$this->assertStringContainsString( "CASE WHEN payload IS NULL THEN NULL WHEN pg_input_is_valid(CAST(payload AS text), 'json') THEN 1 ELSE 0 END AS payload_valid", $sql );
