	/**
	 * Tests PostgreSQL helper scanning no longer creates MySQL UDF shims.
	 */
	public function test_pgsql_runtime_helper_scanner_does_not_create_mysql_udf_shims(): void {
		$connection = new class( array( 'pdo' => new PDO( 'sqlite::memory:' ) ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured queries.
			 *
			 * @var array[]
			 */
			private $queries = array();

			/**
			 * Capture queries issued through the connection.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				$this->queries[] = array(
					'sql'    => $sql,
					'params' => $params,
				);

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured queries.
			 *
			 * @return array[] Captured queries.
			 */
			public function get_queries(): array {
				return $this->queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$ensure     = Closure::bind(
			function ( string $query ): void {
				$this->ensure_postgresql_runtime_helpers_for_query( $query );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		$ensure(
			"SELECT __wp_pg_mysql_json_valid(CAST(payload AS text)),
				__wp_pg_mysql_validate_temporal(CAST(value AS text), 'datetime', 1, 1)"
		);

		$this->assertSame( array(), $connection->get_queries() );
	}

	/**
	 * Tests JSON_VALID() runtime execution preserves MySQL NULL/0/1 semantics.
	 */
	public function test_json_valid_runtime_function_executes_with_mysql_semantics(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_json_valid_runtime (id INTEGER PRIMARY KEY, payload TEXT)' );
		$driver->query( "INSERT INTO wptests_json_valid_runtime (id, payload) VALUES (1, '{\"ok\":true}'), (2, 'not json'), (3, NULL), (4, 'null')" );

		$rows = $driver->query( 'SELECT id, JSON_VALID(payload) AS payload_valid FROM wptests_json_valid_runtime ORDER BY id' );

		$this->assertSame(
			array(
				array( '1', '1' ),
				array( '2', '0' ),
				array( '3', null ),
				array( '4', '1' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->payload_valid );
				},
				$rows
			)
		);

		$literal_result = $driver->query(
			'SELECT JSON_VALID(\'{"ok":true}\') AS object_valid,
				JSON_VALID(\'[1,2]\') AS array_valid,
				JSON_VALID(\'not json\') AS invalid_json,
				JSON_VALID(NULL) AS null_json,
				JSON_VALID(\'null\') AS null_literal_valid,
				JSON_VALID(123) AS number_valid'
		);

		$this->assertCount( 1, $literal_result );
		$this->assertSame( '1', $literal_result[0]->object_valid );
		$this->assertSame( '1', $literal_result[0]->array_valid );
		$this->assertSame( '0', $literal_result[0]->invalid_json );
		$this->assertNull( $literal_result[0]->null_json );
		$this->assertSame( '1', $literal_result[0]->null_literal_valid );
		$this->assertSame( '1', $literal_result[0]->number_valid );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( '1 AS object_valid', $sql );
		$this->assertStringContainsString( '1 AS array_valid', $sql );
		$this->assertStringContainsString( '0 AS invalid_json', $sql );
		$this->assertStringContainsString( 'NULL AS null_json', $sql );
		$this->assertStringContainsString( '1 AS null_literal_valid', $sql );
		$this->assertStringContainsString( '1 AS number_valid', $sql );
		$this->assertStringNotContainsString( '__wp_pg_mysql_json_valid', $sql );
		$this->assertStringNotContainsString( 'JSON_VALID', $sql );
		$this->assertStringNotContainsString( 'pg_input_is_valid', $sql );
	}

	/**
	 * Tests common MySQL runtime functions trigger rewrite without literal arguments.
	 */
	public function test_common_mysql_runtime_functions_with_column_arguments_trigger_postgresql_rewrite(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT IFNULL(primary_value, fallback_value) AS selected_value, NULLIF(primary_value, fallback_value) AS nullif_value, CONCAT(prefix, suffix) AS joined_value, CONCAT_WS('-', prefix, NULL, suffix) AS joined_ws_value, CHAR_LENGTH(display_name) AS name_length, LENGTH(display_name) AS byte_length FROM runtime_names"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'COALESCE(primary_value, fallback_value) AS selected_value', $sql );
		$this->assertStringContainsString( 'NULLIF(primary_value, fallback_value) AS nullif_value', $sql );
		$this->assertStringContainsString( '(CAST(prefix AS text) || CAST(suffix AS text)) AS joined_value', $sql );
		$this->assertStringContainsString( "CASE WHEN '-' IS NULL THEN NULL ELSE", $sql );
		$this->assertStringContainsString( "COALESCE(CAST(prefix AS text), '')", $sql );
		$this->assertStringContainsString( "COALESCE(CAST(suffix AS text), '')", $sql );
		$this->assertStringContainsString( 'END AS joined_ws_value', $sql );
		$this->assertStringContainsString( 'CHAR_LENGTH(CAST(display_name AS text)) AS name_length', $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(display_name AS text), 'UTF8')) END AS byte_length", $sql );
		$this->assertStringNotContainsString( 'IFNULL', $sql );
		$this->assertStringNotContainsString( 'CONCAT(', $sql );
		$this->assertStringNotContainsString( 'CONCAT_WS', $sql );
	}

	/**
	 * Tests MySQL CONCAT_WS() skips NULL values while preserving empty strings.
	 */
	public function test_concat_ws_runtime_function_executes_mysql_null_semantics(): void {
		$driver = $this->create_driver();

		$rows = $driver->query(
			"SELECT
				CONCAT_WS('-', 'wp', NULL, 'db') AS skipped_null,
				CONCAT_WS(',', '', NULL, 'tail') AS empty_string_kept,
				CONCAT_WS(NULL, 'a', 'b') AS null_separator,
				CONCAT_WS('|', NULL, NULL) AS all_values_null"
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( 'wp-db', $rows[0]->skipped_null );
		$this->assertSame( ',tail', $rows[0]->empty_string_kept );
		$this->assertNull( $rows[0]->null_separator );
		$this->assertSame( '', $rows[0]->all_values_null );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringNotContainsString( 'CONCAT_WS', $sql );
	}

	/**
	 * Tests MySQL LENGTH() counts bytes for UTF-8 text.
	 */
	public function test_length_runtime_function_counts_utf8_bytes_for_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
				LENGTH(UNHEX('c3a9')) AS utf8_byte_length,
				LENGTH(UNHEX('ff')) AS binary_byte_length,
				LENGTH(x'c3a9') AS raw_hex_byte_length,
				LENGTH(0xC3A9) AS prefixed_hex_byte_length"
		);

		$this->assertSame(
			"SELECT OCTET_LENGTH(DECODE(CAST('c3a9' AS text), 'hex')) AS utf8_byte_length, OCTET_LENGTH(DECODE(CAST('ff' AS text), 'hex')) AS binary_byte_length, 2 AS raw_hex_byte_length, 2 AS prefixed_hex_byte_length",
			$sql
		);
	}

	/**
	 * Tests CHAR_LENGTH() counts bytes for binary-producing runtime functions.
	 */
	public function test_char_length_binary_runtime_functions_count_bytes_for_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
				CHAR_LENGTH(UNHEX('c3a9')) AS unhex_char_bytes,
				CHARACTER_LENGTH(UNHEX('ff')) AS unhex_raw_bytes,
				CHAR_LENGTH(FROM_BASE64('w6k=')) AS base64_char_bytes,
				CHAR_LENGTH(x'c3a9') AS raw_hex_char_bytes,
				CHARACTER_LENGTH(0xC3A9) AS prefixed_hex_char_bytes"
		);

		$this->assertSame(
			"SELECT OCTET_LENGTH(DECODE(CAST('c3a9' AS text), 'hex')) AS unhex_char_bytes, OCTET_LENGTH(DECODE(CAST('ff' AS text), 'hex')) AS unhex_raw_bytes, CASE WHEN CAST('w6k=' AS text) IS NULL OR CAST('w6k=' AS text) !~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' THEN NULL ELSE OCTET_LENGTH(DECODE(CAST('w6k=' AS text), 'base64')) END AS base64_char_bytes, 2 AS raw_hex_char_bytes, 2 AS prefixed_hex_char_bytes",
			$sql
		);
	}

	/**
	 * Tests MySQL LENGTH() counts text bytes while CHAR_LENGTH() counts characters.
	 */
	public function test_length_runtime_function_counts_text_utf8_bytes_when_executed(): void {
		$driver  = $this->create_driver_with_postgresql_text_runtime_functions();
		$literal = $this->quote_mysql_string_literal_for_test( "\xC3\xA9" );

		$result = $driver->query(
			sprintf(
				'SELECT LENGTH(%1$s) AS byte_length, CHAR_LENGTH(%1$s) AS char_length, CHARACTER_LENGTH(%1$s) AS character_length',
				$literal
			)
		);

		$this->assertCount( 1, $result );
		$this->assertSame( '2', $result[0]->byte_length );
		$this->assertSame( '1', $result[0]->char_length );
		$this->assertSame( '1', $result[0]->character_length );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST($literal AS text), 'UTF8')) END AS byte_length", $sql );
		$this->assertStringContainsString( "CHAR_LENGTH(CAST($literal AS text)) AS char_length", $sql );
		$this->assertStringContainsString( "CHAR_LENGTH(CAST($literal AS text)) AS character_length", $sql );
	}

	/**
	 * Tests MySQL binary strings make CHAR_LENGTH() count bytes.
	 */
	public function test_binary_length_runtime_functions_count_utf8_bytes_when_executed(): void {
		$driver  = $this->create_driver_with_postgresql_text_runtime_functions();
		$literal = $this->quote_mysql_string_literal_for_test( "\xC3\xA9" );

		$result = $driver->query(
			sprintf(
				'SELECT
					LENGTH(%1$s) AS text_byte_length,
					CHAR_LENGTH(%1$s) AS text_char_length,
					CHAR_LENGTH(CAST(%1$s AS BINARY)) AS cast_binary_char_length,
					CHARACTER_LENGTH(BINARY %1$s) AS operator_binary_char_length,
					LENGTH(CONVERT(%1$s, BINARY)) AS convert_binary_byte_length,
					CHAR_LENGTH(CONVERT(%1$s, BINARY)) AS convert_binary_char_length',
				$literal
			)
		);

		$this->assertCount( 1, $result );
		$this->assertSame( '2', $result[0]->text_byte_length );
		$this->assertSame( '1', $result[0]->text_char_length );
		$this->assertSame( '2', $result[0]->cast_binary_char_length );
		$this->assertSame( '2', $result[0]->operator_binary_char_length );
		$this->assertSame( '2', $result[0]->convert_binary_byte_length );
		$this->assertSame( '2', $result[0]->convert_binary_char_length );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( "CHAR_LENGTH(CAST($literal AS text)) AS text_char_length", $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST($literal AS text), 'UTF8')) END AS cast_binary_char_length", $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST($literal AS text), 'UTF8')) END AS operator_binary_char_length", $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST($literal AS text), 'UTF8')) END AS convert_binary_byte_length", $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST($literal AS text), 'UTF8')) END AS convert_binary_char_length", $sql );
		$this->assertStringNotContainsString( "CAST($literal AS BINARY)", $sql );
		$this->assertStringNotContainsString( "CONVERT($literal, BINARY)", $sql );
	}

	/**
	 * Tests MySQL LENGTH() counts decoded PostgreSQL-safe text envelope bytes.
	 */
	public function test_length_runtime_function_counts_postgresql_text_envelope_bytes_when_executed(): void {
		$driver     = $this->create_driver_with_postgresql_quote_translation_and_text_runtime_functions();
		$connection = $driver->get_connection();

		$driver->query( 'CREATE TABLE wptests_length_text_envelope (value TEXT NOT NULL)' );
		$connection->query( 'INSERT INTO wptests_length_text_envelope (value) VALUES (' . $connection->quote( "a\0\xC3\xA9" ) . ')' );

		$stored_rows = $connection->query( 'SELECT value FROM wptests_length_text_envelope' )->fetchAll( PDO::FETCH_OBJ );
		$this->assertCount( 1, $stored_rows );
		$this->assertStringContainsString( 'WP_MYSQL_TEXT_V1:', $stored_rows[0]->value );

		$result = $driver->query( 'SELECT LENGTH(value) AS byte_length FROM wptests_length_text_envelope' );

		$this->assertCount( 1, $result );
		$this->assertSame( '4', (string) $result[0]->byte_length );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'STRPOS(SUBSTR(CAST(value AS text),', $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(value AS text), 'UTF8')) END AS byte_length", $sql );
	}

	/**
	 * Tests formatted FROM_UNIXTIME() shares DATE_FORMAT coverage and NULL semantics.
	 */
	public function test_from_unixtime_formatted_runtime_function_is_translated_with_null_guard(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
				FROM_UNIXTIME(0.123456, '%Y-%m-%d %H:%i:%s.%f') AS formatted_epoch,
				FROM_UNIXTIME(0, '%H.%i') AS formatted_hour_minute,
				FROM_UNIXTIME(0, '%H.%i%s') AS formatted_hour_minute_second,
				FROM_UNIXTIME(0, '0.%i%s') AS formatted_minute_second_fraction,
				FROM_UNIXTIME(1609632000, '%U %u %V %v %X %x') AS formatted_week_modes,
				FROM_UNIXTIME(0, CONCAT('%Y', '-%m')) AS constant_expression_format,
				FROM_UNIXTIME(0, CONCAT_WS('-', '%Y', '%m', '%d')) AS constant_ws_expression_format,
				FROM_UNIXTIME(0, REPLACE('%Y/%m/%d', '/', '-')) AS constant_replace_expression_format,
				FROM_UNIXTIME(0, SUBSTRING('xx%Y-%m-%d', 3, 8)) AS constant_substring_expression_format,
				FROM_UNIXTIME(0, RIGHT('ignored%Y-%m', 5)) AS constant_right_expression_format,
				FROM_UNIXTIME(0, LPAD('%m', 5, '%Y-')) AS constant_lpad_expression_format,
				FROM_UNIXTIME(0, RPAD('%Y', 5, '-%m')) AS constant_rpad_expression_format,
				FROM_UNIXTIME(0, REPEAT('%Y', 1)) AS constant_repeat_expression_format,
				FROM_UNIXTIME(0, TRIM(' %Y-%m ')) AS constant_trim_expression_format,
				FROM_UNIXTIME(0, LTRIM('   %Y')) AS constant_ltrim_expression_format,
				FROM_UNIXTIME(0, RTRIM('%m   ')) AS constant_rtrim_expression_format,
				FROM_UNIXTIME(0, CONCAT('%Y', SPACE(1), '%m')) AS constant_space_expression_format,
				FROM_UNIXTIME(0, REVERSE('Y%')) AS constant_reverse_expression_format,
				FROM_UNIXTIME(0, ELT(2, '%m', '%Y')) AS constant_elt_expression_format,
				FROM_UNIXTIME(0, IFNULL(NULL, '%Y-%m')) AS constant_ifnull_expression_format,
				FROM_UNIXTIME(0, CONCAT('%Y', NULL)) AS null_expression_format,
				FROM_UNIXTIME(0, NULLIF('%Y', '%Y')) AS null_nullif_expression_format,
				FROM_UNIXTIME(NULL, 'literal') AS null_literal,
				FROM_UNIXTIME(NULL, '') AS null_empty_from_unixtime,
				DATE_FORMAT(NULL, '%%') AS null_percent,
				DATE_FORMAT(NULL, '') AS null_empty_format"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( "TO_TIMESTAMP(CAST(0.123456 AS double precision)) AT TIME ZONE 'UTC'", $sql );
		$this->assertStringContainsString( "'HH24') || '.' || TO_CHAR", $sql );
		$this->assertStringContainsString( "'MI') END AS formatted_hour_minute", $sql );
		$this->assertStringContainsString( "'MI') || TO_CHAR", $sql );
		$this->assertStringContainsString( "'SS') END AS formatted_hour_minute_second", $sql );
		$this->assertStringContainsString( "'0.' || TO_CHAR", $sql );
		$this->assertStringContainsString( "'SS') END AS formatted_minute_second_fraction", $sql );
		$week_timestamp_sql = $this->get_expected_zero_date_safe_timestamp_sql( "TO_TIMESTAMP(CAST(1609632000 AS double precision)) AT TIME ZONE 'UTC'" );
		$this->assertStringContainsString(
			$this->get_expected_mysql_zero_padded_week_sql( $this->get_expected_mysql_sunday_week_mode_zero_sql( $week_timestamp_sql ) ),
			$sql
		);
		$this->assertStringContainsString(
			$this->get_expected_mysql_zero_padded_week_sql( $this->get_expected_mysql_week_mode_one_timestamp_sql( $week_timestamp_sql ) ),
			$sql
		);
		$this->assertStringContainsString(
			$this->get_expected_mysql_zero_padded_week_sql( $this->get_expected_mysql_sunday_week_mode_two_sql( $week_timestamp_sql ) ),
			$sql
		);
		$this->assertStringContainsString( 'TO_CHAR(' . $week_timestamp_sql . ", 'IW')", $sql );
		$this->assertStringContainsString( $this->get_expected_mysql_sunday_week_mode_two_year_sql( $week_timestamp_sql ), $sql );
		$this->assertStringContainsString( 'TO_CHAR(' . $week_timestamp_sql . ", 'IYYY')", $sql );
		$this->assertStringNotContainsString( "CAST(TO_CHAR(TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC', 'HH24.MI') AS double precision)", $sql );
		$this->assertStringNotContainsString( "CAST(TO_CHAR(TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC', 'HH24.MISS') AS double precision)", $sql );
		$this->assertStringNotContainsString( "CAST('0.' || TO_CHAR(TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC', 'MISS') AS double precision)", $sql );
		$this->assertStringContainsString( "'YYYY'", $sql );
		$this->assertStringContainsString( "'MM'", $sql );
		$this->assertStringContainsString( "'DD'", $sql );
		$this->assertStringContainsString( "'HH24'", $sql );
		$this->assertStringContainsString( "'MI'", $sql );
		$this->assertStringContainsString( "'SS'", $sql );
		$this->assertStringContainsString( "'US'", $sql );
		$this->assertStringContainsString( 'TO_CHAR(' . $this->get_expected_zero_date_safe_timestamp_sql( "TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC'" ) . ', \'YYYY\') || \'-\' || TO_CHAR', $sql );
		$this->assertStringContainsString( "'DD') END AS constant_ws_expression_format", $sql );
		$this->assertStringContainsString( 'AS constant_ws_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_replace_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_substring_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_right_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_lpad_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_rpad_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_repeat_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_trim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_ltrim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_rtrim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_space_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_reverse_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_elt_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_ifnull_expression_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_expression_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_nullif_expression_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_literal', $sql );
		$this->assertStringContainsString( 'NULL AS null_empty_from_unixtime', $sql );
		$this->assertStringContainsString( 'NULL AS null_percent', $sql );
		$this->assertStringContainsString( 'NULL AS null_empty_format', $sql );
		$this->assertStringNotContainsString( 'WITH RECURSIVE "__wp_pg_mysql_date_format"', $sql );
		$this->assertStringNotContainsString( "TRIM(' %Y-%m ')", $sql );
		$this->assertStringNotContainsString( "LTRIM('   %Y')", $sql );
		$this->assertStringNotContainsString( "RTRIM('%m   ')", $sql );
		$this->assertStringNotContainsString( 'SPACE(1)', $sql );
		$this->assertStringNotContainsString( "REVERSE('Y%')", $sql );
		$this->assertStringNotContainsString( "ELT(2, '%m', '%Y')", $sql );
		$this->assertStringNotContainsString( 'FROM_UNIXTIME', $sql );
		$this->assertStringNotContainsString( 'DATE_FORMAT', $sql );
	}

	/**
	 * Tests FROM_UNIXTIME() honors session time_zone and preserves fractional seconds.
	 */
	public function test_from_unixtime_runtime_function_honors_time_zone_and_fractional_seconds(): void {
		$driver = $this->create_driver();
		$driver->query( "SET SESSION time_zone = '+02:30'" );

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
					FROM_UNIXTIME(0) AS whole_epoch,
					FROM_UNIXTIME(0.123456) AS fractional_epoch,
					FROM_UNIXTIME(0, '%q %%') AS unknown_specifier"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( "(TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC' + INTERVAL '150 minutes')", $sql );
		$this->assertStringContainsString( "TO_CHAR((TO_TIMESTAMP(CAST(0.123456 AS double precision)) AT TIME ZONE 'UTC' + INTERVAL '150 minutes'), 'YYYY-MM-DD HH24:MI:SS.US')", $sql );
		$this->assertStringContainsString( "'q ' || '%'", $sql );
		$this->assertStringNotContainsString( "'%q '", $sql );
		$this->assertStringNotContainsString( 'FROM_UNIXTIME', $sql );
	}

	/**
	 * Tests DATE_FORMAT() supports runtime format expressions like SQLite's UDF.
	 */
	public function test_mysql_date_format_runtime_format_expressions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT
				DATE_FORMAT(post_date, format_mask) AS dynamic_column_format,
				DATE_FORMAT(post_date, CONCAT('%Y', '-%m')) AS constant_expression_format,
				DATE_FORMAT(post_date, CONCAT_WS('-', '%Y', '%m', '%d')) AS constant_ws_expression_format,
				DATE_FORMAT(post_date, REPLACE('%Y/%m/%d', '/', '-')) AS constant_replace_expression_format,
				DATE_FORMAT(post_date, LEFT('%Y-%m-%d ignored', 8)) AS constant_left_expression_format,
				DATE_FORMAT(post_date, RIGHT('ignored %Y-%m', 5)) AS constant_right_expression_format,
				DATE_FORMAT(post_date, LPAD('%m', 5, '%Y-')) AS constant_lpad_expression_format,
				DATE_FORMAT(post_date, RPAD('%Y', 5, '-%m')) AS constant_rpad_expression_format,
				DATE_FORMAT(post_date, REPEAT('%Y', 1)) AS constant_repeat_expression_format,
				DATE_FORMAT(post_date, TRIM(' %Y-%m ')) AS constant_trim_expression_format,
				DATE_FORMAT(post_date, LTRIM('   %Y')) AS constant_ltrim_expression_format,
				DATE_FORMAT(post_date, RTRIM('%m   ')) AS constant_rtrim_expression_format,
				DATE_FORMAT(post_date, CONCAT('%Y', SPACE(1), '%m')) AS constant_space_expression_format,
				DATE_FORMAT(post_date, REVERSE('Y%')) AS constant_reverse_expression_format,
				DATE_FORMAT(post_date, ELT(2, '%m', '%Y')) AS constant_elt_expression_format,
				DATE_FORMAT(post_date, COALESCE(NULL, '%Y-%m')) AS constant_coalesce_expression_format,
				DATE_FORMAT(post_date, IF(format_mask = '%Y', '%Y', '%m')) AS finite_if_expression_format,
				DATE_FORMAT(post_date, IF(format_mask = '%Y', '%Y', NULL)) AS finite_if_null_expression_format,
				DATE_FORMAT(post_date, CASE WHEN format_mask = '%Y' THEN '%Y' WHEN format_mask = '%m' THEN '%m' ELSE NULL END) AS finite_case_expression_format,
				DATE_FORMAT(post_date, CASE format_mask WHEN '%Y' THEN '%Y' ELSE '%m' END) AS finite_simple_case_expression_format,
				DATE_FORMAT(post_date, CONCAT('%Y-', NULL)) AS null_expression_format,
				DATE_FORMAT(post_date, NULLIF('%H', '%H')) AS null_nullif_expression_format,
				DATE_FORMAT(NULL, format_mask) AS null_date_format,
				DATE_FORMAT(post_date, NULL) AS null_mask_format
			FROM wptests_dynamic_date_formats"
		);

		$this->assertNotNull( $sql );
		$this->assertSame( 2, substr_count( $sql, 'WITH RECURSIVE "__wp_pg_mysql_date_format"' ) );
		$this->assertStringContainsString( 'CAST(format_mask AS text)', $sql );
		$this->assertStringNotContainsString( "(CAST('%Y' AS text) || CAST('-%m' AS text))", $sql );
		$this->assertStringContainsString( 'TO_CHAR(' . $this->get_expected_zero_date_safe_timestamp_sql( 'post_date' ) . ', \'YYYY\') || \'-\' || TO_CHAR', $sql );
		$this->assertStringContainsString( "'YYYY-MM-DD'", $sql );
		$this->assertStringContainsString( 'AS constant_ws_expression_format', $sql );
		$this->assertStringNotContainsString( "CONCAT_WS('-', '%Y', '%m', '%d')", $sql );
		$this->assertStringContainsString( 'AS constant_replace_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_left_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_right_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_lpad_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_rpad_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_repeat_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_trim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_ltrim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_rtrim_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_space_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_reverse_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_elt_expression_format', $sql );
		$this->assertStringContainsString( 'AS constant_coalesce_expression_format', $sql );
		$this->assertStringContainsString( 'AS finite_if_expression_format', $sql );
		$this->assertStringContainsString( 'AS finite_if_null_expression_format', $sql );
		$this->assertStringContainsString( 'AS finite_case_expression_format', $sql );
		$this->assertStringContainsString( 'AS finite_simple_case_expression_format', $sql );
		$this->assertStringContainsString( "CASE WHEN (format_mask = '%Y') THEN", $sql );
		$this->assertStringContainsString( 'ELSE NULL END AS finite_if_null_expression_format', $sql );
		$this->assertStringContainsString( "WHEN (format_mask = '%m') THEN", $sql );
		$this->assertStringContainsString( 'ELSE NULL END AS finite_case_expression_format', $sql );
		$this->assertStringNotContainsString( "REPLACE('%Y/%m/%d', '/', '-')", $sql );
		$this->assertStringNotContainsString( "LEFT('%Y-%m-%d ignored', 8)", $sql );
		$this->assertStringNotContainsString( "RIGHT('ignored %Y-%m', 5)", $sql );
		$this->assertStringNotContainsString( "LPAD('%m', 5, '%Y-')", $sql );
		$this->assertStringNotContainsString( "RPAD('%Y', 5, '-%m')", $sql );
		$this->assertStringNotContainsString( "REPEAT('%Y', 1)", $sql );
		$this->assertStringNotContainsString( "TRIM(' %Y-%m ')", $sql );
		$this->assertStringNotContainsString( "LTRIM('   %Y')", $sql );
		$this->assertStringNotContainsString( "RTRIM('%m   ')", $sql );
		$this->assertStringNotContainsString( 'SPACE(1)', $sql );
		$this->assertStringNotContainsString( "REVERSE('Y%')", $sql );
		$this->assertStringNotContainsString( "ELT(2, '%m', '%Y')", $sql );
		$this->assertStringNotContainsString( "COALESCE(NULL, '%Y-%m')", $sql );
		$this->assertStringNotContainsString( "IF(format_mask = '%Y'", $sql );
		$this->assertStringNotContainsString( "CASE WHEN format_mask = '%Y' THEN '%Y'", $sql );
		$this->assertStringNotContainsString( "CASE format_mask WHEN '%Y'", $sql );
		$this->assertStringContainsString( 'NULL AS null_expression_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_nullif_expression_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_date_format', $sql );
		$this->assertStringContainsString( 'NULL AS null_mask_format', $sql );
		$this->assertStringContainsString( "WHEN 'Y' THEN TO_CHAR", $sql );
		$this->assertStringContainsString( "WHEN 'D' THEN CAST(CAST(EXTRACT(DAY FROM", $sql );
		$this->assertStringContainsString( "WHEN 'w' THEN CAST(CAST(EXTRACT(DOW FROM", $sql );
		$this->assertStringContainsString( "WHEN 'U' THEN LPAD(CAST(CASE WHEN", $sql );
		$this->assertStringContainsString( "WHEN 'u' THEN LPAD(CAST(CASE WHEN", $sql );
		$this->assertStringContainsString( "WHEN 'V' THEN LPAD(CAST(CASE WHEN", $sql );
		$this->assertStringContainsString( "WHEN 'v' THEN TO_CHAR", $sql );
		$this->assertStringContainsString( "WHEN 'X' THEN CASE WHEN", $sql );
		$this->assertStringContainsString( "WHEN 'x' THEN TO_CHAR", $sql );
		$this->assertStringContainsString( 'ELSE SUBSTRING', $sql );
		$this->assertStringNotContainsString( "ELSE '%' || SUBSTRING", $sql );
		$this->assertStringNotContainsString( 'DATE_FORMAT', $sql );

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT DATE_FORMAT(post_date, format_mask) AS dynamic_column_format FROM wptests_dynamic_date_formats'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'WITH RECURSIVE "__wp_pg_mysql_date_format"', $sql );
		$this->assertStringNotContainsString( 'DATE_FORMAT', $sql );
	}

	/**
	 * Tests runtime DATE_FORMAT() masks preserve derivable zero-date parts.
	 */
	public function test_mysql_date_format_runtime_format_preserves_zero_date_numeric_and_time_parts_for_postgresql(): void {
		$driver         = $this->create_driver();
		$expression_sql = "CAST('2006-06-00 13:04:05.123' AS text)";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT DATE_FORMAT('2006-06-00 13:04:05.123', format_mask) AS dynamic_zero_format
			FROM wptests_dynamic_date_formats"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'WHEN ' . $this->get_expected_zero_date_condition_sql( $expression_sql ) . ' THEN (WITH RECURSIVE "__wp_pg_mysql_date_format"', $sql );
		$this->assertStringContainsString( 'WHEN \'Y\' THEN SUBSTRING(' . $expression_sql . ' FROM 1 FOR 4)', $sql );
		$this->assertStringContainsString( 'WHEN \'m\' THEN SUBSTRING(' . $expression_sql . ' FROM 6 FOR 2)', $sql );
		$this->assertStringContainsString( 'WHEN \'d\' THEN SUBSTRING(' . $expression_sql . ' FROM 9 FOR 2)', $sql );
		$this->assertStringContainsString( "WHEN 'H' THEN CASE WHEN $expression_sql ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}' THEN SUBSTRING($expression_sql FROM 12 FOR 2) ELSE '00' END", $sql );
		$this->assertStringContainsString( "WHEN 'i' THEN CASE WHEN $expression_sql ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}' THEN SUBSTRING($expression_sql FROM 15 FOR 2) ELSE '00' END", $sql );
		$this->assertStringContainsString( "WHEN 's' THEN CASE WHEN $expression_sql ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}' THEN SUBSTRING($expression_sql FROM 18 FOR 2) ELSE '00' END", $sql );
		$this->assertStringContainsString( "WHEN 'f' THEN CASE WHEN $expression_sql ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]+' THEN LEFT(RPAD(SUBSTRING($expression_sql FROM '[.]([0-9]+)'), 6, '0'), 6) ELSE '000000' END", $sql );
		$this->assertStringContainsString( "WHEN 'W' THEN NULL", $sql );
		$this->assertStringContainsString( 'ELSE SUBSTRING(CAST(format_mask AS text) FROM "__wp_pg_mysql_date_format"."position" + 1 FOR 1) END', $sql );
		$this->assertStringNotContainsString( "ELSE '%' || SUBSTRING", $sql );
		$this->assertStringNotContainsString( "CAST('2006-06-00 13:04:05.123' AS timestamp)", $sql );
		$this->assertStringNotContainsString( 'DATE_FORMAT', $sql );
	}

	/**
	 * Tests formatted FROM_UNIXTIME() supports runtime format expressions.
	 */
	public function test_from_unixtime_runtime_format_expression_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT FROM_UNIXTIME(0, format_mask) AS formatted_epoch,
				FROM_UNIXTIME(0, IF(format_mask = \'%Y\', \'%Y\', \'%m\')) AS finite_if_epoch,
				FROM_UNIXTIME(0, CASE WHEN format_mask = \'%Y\' THEN \'%Y\' ELSE \'%m\' END) AS finite_case_epoch,
				FROM_UNIXTIME(0, CASE format_mask WHEN \'%Y\' THEN \'%Y\' ELSE \'%m\' END) AS finite_simple_case_epoch,
				FROM_UNIXTIME(NULL, format_mask) AS null_dynamic_epoch
			FROM wptests_unix_time_formats'
		);

		$this->assertNotNull( $sql );
		$this->assertSame( 2, substr_count( $sql, 'WITH RECURSIVE "__wp_pg_mysql_date_format"' ) );
		$this->assertStringContainsString( "TO_TIMESTAMP(CAST(0 AS double precision)) AT TIME ZONE 'UTC'", $sql );
		$this->assertStringContainsString( 'CAST(format_mask AS text)', $sql );
		$this->assertStringContainsString( 'AS finite_if_epoch', $sql );
		$this->assertStringContainsString( 'AS finite_case_epoch', $sql );
		$this->assertStringContainsString( 'AS finite_simple_case_epoch', $sql );
		$this->assertStringContainsString( "CASE WHEN (format_mask = '%Y') THEN", $sql );
		$this->assertStringContainsString( 'NULL AS null_dynamic_epoch', $sql );
		$this->assertStringNotContainsString( "IF(format_mask = '%Y'", $sql );
		$this->assertStringNotContainsString( "CASE WHEN format_mask = '%Y' THEN '%Y'", $sql );
		$this->assertStringNotContainsString( "CASE format_mask WHEN '%Y'", $sql );
		$this->assertStringNotContainsString( 'FROM_UNIXTIME', $sql );
	}

	/**
	 * Tests unsupported common MySQL runtime function forms are left without compatibility translations.
	 */
	public function test_unsupported_common_mysql_runtime_function_forms_return_null_translation(): void {
		$driver  = $this->create_driver();
		$queries = array(
			'SELECT CONCAT() AS empty_concat',
			"SELECT CONCAT_WS('-') AS invalid_concat_ws",
			'SELECT ASCII() AS invalid_ascii',
			'SELECT ASCII(primary_value, fallback_value) AS invalid_ascii FROM runtime_names',
			'SELECT DAYNAME() AS invalid_dayname',
			'SELECT DAYNAME(primary_value, fallback_value) AS invalid_dayname FROM runtime_names',
			'SELECT ELT(1) AS invalid_elt',
			'SELECT FIND_IN_SET(primary_value) AS invalid_find_in_set FROM runtime_names',
			'SELECT FIND_IN_SET(primary_value, fallback_value, third_value) AS invalid_find_in_set FROM runtime_names',
			'SELECT IFNULL(primary_value) AS invalid_ifnull FROM runtime_names',
			'SELECT INSTR(primary_value) AS invalid_instr FROM runtime_names',
			'SELECT INSTR(primary_value, fallback_value, third_value) AS invalid_instr FROM runtime_names',
			'SELECT IS_UUID() AS invalid_is_uuid',
			'SELECT IS_UUID(primary_value, fallback_value) AS invalid_is_uuid FROM runtime_names',
			'SELECT NULLIF(primary_value) AS invalid_nullif FROM runtime_names',
			'SELECT NULLIF(primary_value, fallback_value, third_value) AS invalid_nullif FROM runtime_names',
			'SELECT JSON_VALID() AS invalid_json',
			'SELECT JSON_VALID(payload, fallback_value) AS invalid_json FROM runtime_names',
			'SELECT LOG() AS invalid_log',
			'SELECT LTRIM(primary_value, fallback_value) AS invalid_ltrim FROM runtime_names',
			'SELECT MAKE_SET() AS invalid_make_set',
			'SELECT MAKE_SET(primary_value) AS invalid_make_set FROM runtime_names',
			'SELECT MONTHNAME() AS invalid_monthname',
			'SELECT MONTHNAME(primary_value, fallback_value) AS invalid_monthname FROM runtime_names',
			'SELECT REVERSE() AS invalid_reverse',
			'SELECT REVERSE(primary_value, fallback_value) AS invalid_reverse FROM runtime_names',
			'SELECT RTRIM(primary_value, fallback_value) AS invalid_rtrim FROM runtime_names',
			'SELECT SPACE() AS invalid_space',
			'SELECT SPACE(1, 2) AS invalid_space',
			'SELECT TRIM() AS invalid_trim',
			'SELECT TRIM(primary_value, fallback_value) AS invalid_trim FROM runtime_names',
			'SELECT CURRENT_TIMESTAMP(7) AS invalid_fractional_timestamp',
			'SELECT CURRENT_USER(1) AS invalid_current_user',
			'SELECT FOUND_ROWS(1) AS invalid_found_rows',
			'SELECT ROW_COUNT(123) AS rows_changed',
			'SELECT UUID(1) AS invalid_uuid',
		);

		foreach ( $queries as $query ) {
			$this->assertNull(
				$this->translate_driver_query_with_private_method(
					$driver,
					'translate_mysql_compatible_query',
					$query
				),
				$query
			);
		}
	}

	/**
	 * Tests unsupported known MySQL runtime functions fail before backend execution.
	 */
	public function test_unsupported_common_mysql_runtime_function_forms_fail_closed_before_backend_execution(): void {
		$queries = array(
			'SELECT CONCAT() AS empty_concat',
			"SELECT CONCAT_WS('-') AS invalid_concat_ws",
			'SELECT DAYNAME() AS invalid_dayname',
			'SELECT DAYNAME(primary_value, fallback_value) AS invalid_dayname FROM runtime_names',
			'SELECT FIND_IN_SET(primary_value) AS invalid_find_in_set FROM runtime_names',
			'SELECT FIND_IN_SET(primary_value, fallback_value, third_value) AS invalid_find_in_set FROM runtime_names',
			'SELECT IFNULL(primary_value) AS invalid_ifnull FROM runtime_names',
			'SELECT IS_UUID() AS invalid_is_uuid',
			'SELECT IS_UUID(primary_value, fallback_value) AS invalid_is_uuid FROM runtime_names',
			'SELECT NULLIF(primary_value) AS invalid_nullif FROM runtime_names',
			'SELECT NULLIF(primary_value, fallback_value, third_value) AS invalid_nullif FROM runtime_names',
			'SELECT JSON_VALID() AS invalid_json',
			'SELECT JSON_VALID(payload, fallback_value) AS invalid_json FROM runtime_names',
			'SELECT LOG() AS invalid_log',
			'SELECT MAKE_SET() AS invalid_make_set',
			'SELECT MAKE_SET(primary_value) AS invalid_make_set FROM runtime_names',
			'SELECT MONTHNAME() AS invalid_monthname',
			'SELECT MONTHNAME(primary_value, fallback_value) AS invalid_monthname FROM runtime_names',
			'SELECT TRIM() AS invalid_trim',
			'SELECT TRIM(primary_value, fallback_value) AS invalid_trim FROM runtime_names',
			'SELECT CURRENT_TIMESTAMP(7) AS invalid_fractional_timestamp',
			"SELECT FROM_UNIXTIME(0, '%Y', 'extra') AS invalid_from_unixtime",
			"SELECT LAST_INSERT_ID('123') AS invalid_last_insert_id",
			'SELECT CURRENT_USER(1) AS invalid_current_user',
			'SELECT USER(1) AS invalid_user',
			'SELECT FOUND_ROWS(1) AS invalid_found_rows',
			'SELECT ROW_COUNT(123) AS rows_changed',
			'SELECT UUID(1) AS invalid_uuid',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported MySQL runtime function form to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL runtime function form.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

