			'SUM(' . $meta_value_cast_sql . ') AS refunded',
			$driver->get_last_postgresql_queries()[0]['sql']
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( '5.25', $rows[0]->refunded );
	}

