	/**
	 * Tests invalid date arithmetic forms fail before backend execution.
	 */
	public function test_mysql_date_arithmetic_unsupported_shapes_fail_closed_before_backend_execution(): void {
		$queries = array(
			'SELECT DATE_ADD(post_date_gmt, 1) AS shifted',
			'SELECT DATE_SUB(post_date_gmt, 1) AS shifted',
			'SELECT DATE_ADD(post_date_gmt, INTERVAL 1 fortnight) AS shifted',
			'SELECT DATE_ADD(post_date_gmt, INTERVAL 6/4 HOUR_MINUTE) AS shifted',
			"SELECT DATE_ADD(post_date_gmt, INTERVAL '1:2:3' MINUTE_SECOND) AS shifted",
			'SELECT TIMESTAMPADD(FORTNIGHT, 1, post_date_gmt) AS shifted',
			'SELECT TIMESTAMPADD(DAY_SECOND, interval_value, post_date_gmt) AS shifted',
			'SELECT TIMESTAMPADD(DAY_SECOND, 6/4, post_date_gmt) AS shifted',
			"SELECT TIMESTAMPADD(MINUTE_SECOND, '1:2:3', post_date_gmt) AS shifted",
			'SELECT TIMESTAMPADD(DAY, 1) AS shifted',
			'SELECT TIMESTAMPDIFF(FORTNIGHT, started_at, finished_at) AS diff',
			'SELECT TIMESTAMPDIFF(DAY_SECOND, started_at, finished_at) AS diff',
			'SELECT TIMESTAMPDIFF(DAY, started_at) AS diff',
			'SELECT TIMESTAMPDIFF(DAY, started_at, finished_at, extra_at) AS diff',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported date arithmetic statement to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL date arithmetic statement.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
		}
	}

	/**
	 * Tests ON DUPLICATE KEY UPDATE supports constant scalar subquery assignments.
	 */
	public function test_options_upsert_scalar_subquery_assignment_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$this->install_options_table_with_mysql_metadata( $driver );
		$driver->query( "INSERT INTO wptests_options (option_name, option_value, autoload) VALUES ('siteurl', 'old', 'yes')" );

		$upsert = "INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('siteurl', 'http://example.org', 'yes')
			ON DUPLICATE KEY UPDATE `option_value` = (SELECT 'http://example.net')";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_options" ("option_name", "option_value", "autoload") VALUES (\'siteurl\', \'http://example.org\', \'yes\') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = CAST((SELECT \'http://example.net\') AS text)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( "SELECT option_value FROM wptests_options WHERE option_name = 'siteurl'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'http://example.net', $rows[0]->option_value );

		$dual_tail_upsert = "INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('siteurl', 'http://example.org', 'yes')
			ON DUPLICATE KEY UPDATE `option_value` = (SELECT 'http://example.net/dual' FROM DUAL WHERE 1 = 1 ORDER BY 1 LIMIT 1)";

		$this->assertSame( 1, $driver->query( $dual_tail_upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_options" ("option_name", "option_value", "autoload") VALUES (\'siteurl\', \'http://example.org\', \'yes\') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = CAST((SELECT \'http://example.net/dual\' WHERE 1 = 1 ORDER BY 1 LIMIT 1) AS text)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( "SELECT option_value FROM wptests_options WHERE option_name = 'siteurl'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'http://example.net/dual', $rows[0]->option_value );
	}

	/**
	 * Tests ON DUPLICATE KEY UPDATE supports table-backed scalar subquery assignments.
	 */
	public function test_options_upsert_table_backed_scalar_subquery_assignment_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$this->install_options_table_with_mysql_metadata( $driver );
		$driver->query(
			'CREATE TABLE wptests_upsert_source (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_upsert_source (
				id int(11) NOT NULL,
				label varchar(20) NOT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->query( "INSERT INTO wptests_options (option_name, option_value, autoload) VALUES ('source_counts', '0', '0')" );
		$driver->query( "INSERT INTO wptests_upsert_source (id, label) VALUES (1, 'one'), (2, 'two'), (3, 'three')" );

		$upsert = "INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('source_counts', 'ignored', 'ignored')
			ON DUPLICATE KEY UPDATE `option_value` = (SELECT COUNT(*) FROM `wptests_upsert_source` WHERE `id` > 1),
			                        `autoload` = (SELECT `s`.`label` FROM `wptests_upsert_source` AS `s` WHERE `s`.`id` = 2)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_options" ("option_name", "option_value", "autoload") VALUES (\'source_counts\', \'ignored\', \'ignored\') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = CAST((SELECT COUNT(*) FROM "wptests_upsert_source" WHERE "id" > 1) AS text), "autoload" = CAST((SELECT "s"."label" FROM "wptests_upsert_source" AS "s" WHERE "s"."id" = 2) AS text)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( "SELECT option_value, autoload FROM wptests_options WHERE option_name = 'source_counts'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( '2', $rows[0]->option_value );
		$this->assertSame( 'two', $rows[0]->autoload );

		$count_literal_upsert = "INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('source_counts', 'ignored', 'ignored')
			ON DUPLICATE KEY UPDATE `option_value` = (SELECT COUNT(1) FROM `wptests_upsert_source` WHERE `id` > 0),
			                        `autoload` = (SELECT COUNT(NULL) FROM `wptests_upsert_source`)";

		$this->assertSame( 1, $driver->query( $count_literal_upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_options" ("option_name", "option_value", "autoload") VALUES (\'source_counts\', \'ignored\', \'ignored\') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = CAST((SELECT COUNT(1) FROM "wptests_upsert_source" WHERE "id" > 0) AS text), "autoload" = CAST((SELECT COUNT(NULL) FROM "wptests_upsert_source") AS text)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( "SELECT option_value, autoload FROM wptests_options WHERE option_name = 'source_counts'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( '3', $rows[0]->option_value );
		$this->assertSame( '0', $rows[0]->autoload );

		$ordered_upsert = "INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('source_counts', 'ignored', 'ignored')
			ON DUPLICATE KEY UPDATE `option_value` = (SELECT `label` FROM `wptests_upsert_source` ORDER BY `id` DESC LIMIT 1),
			                        `autoload` = (SELECT `s`.`label` FROM `wptests_upsert_source` AS `s` WHERE `s`.`id` > 0 ORDER BY `s`.`id` ASC LIMIT 1, 1)";

		$this->assertSame( 1, $driver->query( $ordered_upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_options" ("option_name", "option_value", "autoload") VALUES (\'source_counts\', \'ignored\', \'ignored\') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = CAST((SELECT "label" FROM "wptests_upsert_source" ORDER BY "id" DESC LIMIT 1) AS text), "autoload" = CAST((SELECT "s"."label" FROM "wptests_upsert_source" AS "s" WHERE "s"."id" > 0 ORDER BY "s"."id" ASC LIMIT 1 OFFSET 1) AS text)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( "SELECT option_value, autoload FROM wptests_options WHERE option_name = 'source_counts'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'three', $rows[0]->option_value );
		$this->assertSame( 'two', $rows[0]->autoload );
	}

	/**
	 * Tests ON DUPLICATE KEY UPDATE supports scalar subqueries inside expressions.
	 */
	public function test_options_upsert_scalar_subquery_inside_expression_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_upsert_subquery_expr (
				id INTEGER PRIMARY KEY,
				counter INTEGER NOT NULL,
				bonus INTEGER NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_upsert_subquery_expr (
				id int(11) NOT NULL,
				counter int(11) NOT NULL DEFAULT 3,
				bonus int(11) NOT NULL DEFAULT 2,
				PRIMARY KEY (id)
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_upsert_subquery_expr_source (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_upsert_subquery_expr_source (
				id int(11) NOT NULL,
				label varchar(20) NOT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->query( 'INSERT INTO wptests_upsert_subquery_expr (id, counter, bonus) VALUES (1, 9, 5)' );
		$driver->query( "INSERT INTO wptests_upsert_subquery_expr_source (id, label) VALUES (1, 'one'), (2, 'two'), (3, 'three')" );

		$upsert = 'INSERT INTO `wptests_upsert_subquery_expr` (`id`, `counter`, `bonus`)
			VALUES (1, 4, 8)
			ON DUPLICATE KEY UPDATE `counter` = (SELECT COUNT(*) FROM `wptests_upsert_subquery_expr_source` WHERE `id` > 1) + VALUES(`counter`) + DEFAULT(`bonus`)';

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_upsert_subquery_expr" ("id", "counter", "bonus") VALUES (1, 4, 8) ON CONFLICT ("id") DO UPDATE SET "counter" = (SELECT COUNT(*) FROM "wptests_upsert_subquery_expr_source" WHERE "id" > 1) + excluded."counter" + \'2\'',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT counter, bonus FROM wptests_upsert_subquery_expr WHERE id = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '8', $rows[0]->counter );
		$this->assertSame( '5', $rows[0]->bonus );
	}

	/**
	 * Tests unsupported table-backed scalar subquery shapes fail closed.
	 */
	public function test_options_upsert_unsupported_table_backed_subquery_assignment_fails_closed(): void {
		$driver = $this->create_driver();

		$this->install_options_table_with_mysql_metadata( $driver );
		$driver->query(
			'CREATE TABLE wptests_upsert_source (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_upsert_source (
				id int(11) NOT NULL,
				label varchar(20) NOT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->query( "INSERT INTO wptests_options (option_name, option_value, autoload) VALUES ('source_counts', '0', '0')" );

		$queries = array(
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT missing FROM `wptests_upsert_source` WHERE id > 0)",
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT label FROM `wptests_upsert_source` WHERE missing > 0)",
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT label FROM `wptests_upsert_source` ORDER BY missing LIMIT 1)",
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT COUNT(missing) FROM `wptests_upsert_source`)",
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT 'bad' FROM DUAL WHERE missing > 0)",
			"INSERT INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
				VALUES ('source_counts', 'ignored', 'ignored')
				ON DUPLICATE KEY UPDATE `option_value` = (SELECT 'bad' FROM DUAL ORDER BY missing LIMIT 1)",
		);

		foreach ( $queries as $query ) {
			$this->assertNull(
				$this->translate_driver_query_data_with_private_method(
					$driver,
					'translate_mysql_on_duplicate_key_update_query',
					$query
				),
				$query
			);

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported table-backed scalar subquery assignment to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ON DUPLICATE KEY UPDATE statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

