							? 'SELECT \'id\' AS column_name'
							: 'SELECT NULL AS column_name WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) && isset( $params[2] ) && 'id' === (string) $params[2] ) {
