	/**
	 * Tests ALTER TABLE preserves ON UPDATE CURRENT_TIMESTAMP metadata and pgsql trigger side effects.
	 */
	public function test_alter_table_on_update_current_timestamp_updates_mysql_metadata_and_postgresql_triggers(): void {
		$connection = new class() extends WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection {
			public function query( string $sql, array $params = array() ): PDOStatement {
				if (
					0 === strpos( $sql, 'CREATE OR REPLACE FUNCTION ' )
					|| 0 === strpos( $sql, 'DROP TRIGGER IF EXISTS ' )
					|| 0 === strpos( $sql, 'CREATE TRIGGER ' )
					|| 0 === strpos( $sql, 'DROP FUNCTION IF EXISTS ' )
				) {
					return parent::query( 'SELECT 1 WHERE 0 = 1' );
				}

				return parent::query( $sql, $params );
			}

			public function get_driver_name(): string {
				return 'pgsql';
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$this->install_information_schema_fixture( $driver );
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_on_update_alter (
				id int NOT NULL,
				updated timestamp NULL
			)'
		);

		$driver->query( 'ALTER TABLE wptests_on_update_alter ADD COLUMN touched timestamp NULL ON UPDATE CURRENT_TIMESTAMP' );

		$this->assertSame(
			'ALTER TABLE "wptests_on_update_alter" ADD COLUMN "touched" __wp_mysql_timestamp',
			$driver->get_last_postgresql_queries()[0]['sql']
		);
		$this->assertStringContainsString( 'CREATE OR REPLACE FUNCTION "__wp_pg_on_update_fn_', $driver->get_last_postgresql_queries()[1]['sql'] );
		$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "__wp_pg_on_update_', $driver->get_last_postgresql_queries()[2]['sql'] );
		$this->assertStringContainsString( 'CREATE TRIGGER "__wp_pg_on_update_', $driver->get_last_postgresql_queries()[3]['sql'] );
		$this->assertStringContainsString( 'BEFORE UPDATE ON "wptests_on_update_alter"', $driver->get_last_postgresql_queries()[3]['sql'] );

		$columns = $this->get_mysql_column_metadata_rows( $driver, 'wptests_on_update_alter' );
		$this->assertSame( array( 'id', 'updated', 'touched' ), array_column( $columns, 'column_name' ) );
		$this->assertSame( 'on update CURRENT_TIMESTAMP', $columns[2]['extra'] );

		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_on_update_alter' )[0]->{'Create Table'};
		$this->assertStringContainsString( '  `touched` timestamp DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP', $create_table );

		$driver->query( 'ALTER TABLE wptests_on_update_alter CHANGE COLUMN touched touched timestamp NULL' );

		$queries = $driver->get_last_postgresql_queries();
		$this->assertSame( 'ALTER TABLE "wptests_on_update_alter" ALTER COLUMN "touched" TYPE __wp_mysql_timestamp', $queries[0]['sql'] );
		$this->assertSame( 'ALTER TABLE "wptests_on_update_alter" ALTER COLUMN "touched" DROP NOT NULL', $queries[1]['sql'] );
		$this->assertSame( 'ALTER TABLE "wptests_on_update_alter" ALTER COLUMN "touched" DROP DEFAULT', $queries[2]['sql'] );
		$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "__wp_pg_on_update_', $queries[3]['sql'] );
		$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "__wp_pg_on_update_fn_', $queries[4]['sql'] );

		$columns = $this->get_mysql_column_metadata_rows( $driver, 'wptests_on_update_alter' );
		$this->assertSame( '', $columns[2]['extra'] );
		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_on_update_alter' )[0]->{'Create Table'};
		$this->assertStringNotContainsString( '  `touched` timestamp DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP', $create_table );
		$this->assertStringContainsString( '  `touched` timestamp DEFAULT NULL', $create_table );
	}

	/**
	 * Tests generated timestamp defaults preserve MySQL metadata and SHOW CREATE shape.
	 */
	public function test_create_table_generated_timestamp_defaults_preserve_mysql_shape(): void {
		$driver = $this->create_driver();
		$query  = 'CREATE TABLE wptests_on_update_default (
			id int NOT NULL,
			updated timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP
		)';

		$translator = new WP_PostgreSQL_Create_Table_Translator();
		$statements = $translator->translate_schema( $query );

		$this->assertCount( 1, $statements );
		$this->assertStringContainsString(
			'"updated" __wp_mysql_timestamp NOT NULL DEFAULT TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE \'UTC\', \'YYYY-MM-DD HH24:MI:SS\')',
			$statements[0]
		);

		$metadata = $translator->extract_schema_metadata( $query, true );
		$this->assertSame( 'now()', $metadata[0]['columns'][1]['default'] );
		$this->assertSame( 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP', $metadata[0]['columns'][1]['extra'] );

		$driver->store_mysql_schema_metadata( $query );
		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_on_update_default' )[0]->{'Create Table'};

		$this->assertStringContainsString( '  `updated` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP', $create_table );

		$fractional_query = 'CREATE TABLE wptests_fractional_timestamp_defaults (
			id int NOT NULL,
			created timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
			updated timestamp(3) NOT NULL DEFAULT (now(3)) ON UPDATE CURRENT_TIMESTAMP(3),
			expires datetime(2) NOT NULL DEFAULT (DATE_ADD(NOW(2), INTERVAL 1 SECOND))
		)';

		$statements = $translator->translate_schema( $fractional_query );

		$this->assertCount( 1, $statements );
		$this->assertStringContainsString(
			'"created" __wp_mysql_timestamp_6 NOT NULL DEFAULT LEFT(TO_CHAR(CURRENT_TIMESTAMP(6) AT TIME ZONE \'UTC\', \'YYYY-MM-DD HH24:MI:SS.US\'), 26)',
			$statements[0]
		);
		$this->assertStringContainsString(
			'"updated" __wp_mysql_timestamp_3 NOT NULL DEFAULT LEFT(TO_CHAR(CURRENT_TIMESTAMP(3) AT TIME ZONE \'UTC\', \'YYYY-MM-DD HH24:MI:SS.US\'), 23)',
			$statements[0]
		);
		$this->assertStringContainsString(
			'"expires" __wp_mysql_datetime_2 NOT NULL DEFAULT (LEFT(TO_CHAR((CURRENT_TIMESTAMP(2) AT TIME ZONE \'UTC\' + (1 * INTERVAL \'1 second\')), \'YYYY-MM-DD HH24:MI:SS.US\'), 22))',
			$statements[0]
		);

		$metadata = $translator->extract_schema_metadata( $fractional_query, true );
		$this->assertSame( 'CURRENT_TIMESTAMP(6)', $metadata[0]['columns'][1]['default'] );
		$this->assertSame( 'now(3)', $metadata[0]['columns'][2]['default'] );
		$this->assertSame( 'DATE_ADD(NOW(2), INTERVAL 1 SECOND)', $metadata[0]['columns'][3]['default'] );
		$this->assertSame( 'DEFAULT_GENERATED', $metadata[0]['columns'][1]['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP', $metadata[0]['columns'][2]['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED', $metadata[0]['columns'][3]['extra'] );

		$driver->store_mysql_schema_metadata( $fractional_query );
		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_fractional_timestamp_defaults' )[0]->{'Create Table'};

		$this->assertStringContainsString( '  `created` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)', $create_table );
		$this->assertStringContainsString( '  `updated` timestamp(3) NOT NULL DEFAULT (now(3)) ON UPDATE CURRENT_TIMESTAMP', $create_table );
		$this->assertStringContainsString( '  `expires` datetime(2) NOT NULL DEFAULT (DATE_ADD(NOW(2), INTERVAL 1 SECOND))', $create_table );
	}

	/**
	 * Tests generated default expressions preserve SQLite-compatible MySQL metadata.
	 */
	public function test_create_table_generated_default_expressions_preserve_mysql_shape(): void {
		$driver = $this->create_driver();
		$query  = "CREATE TABLE wptests_generated_defaults (
			id int NOT NULL,
			col1 int NOT NULL DEFAULT (1 + 2),
			col2 datetime NOT NULL DEFAULT (DATE_ADD(NOW(), INTERVAL 1 YEAR)),
			col3 varchar(255) NOT NULL DEFAULT (CONCAT('a', 'b'))
		)";

		$translator = new WP_PostgreSQL_Create_Table_Translator();
		$statements = $translator->translate_schema( $query );

		$this->assertCount( 1, $statements );
		$this->assertStringContainsString(
			'"col1" integer NOT NULL DEFAULT (1 + 2)',
			$statements[0]
		);
		$this->assertStringContainsString(
			'"col2" __wp_mysql_datetime NOT NULL DEFAULT (TO_CHAR((CURRENT_TIMESTAMP AT TIME ZONE \'UTC\' + (1 * INTERVAL \'1 year\')), \'YYYY-MM-DD HH24:MI:SS\'))',
			$statements[0]
		);
		$this->assertStringContainsString(
			'"col3" varchar(255) NOT NULL DEFAULT ((CAST(\'a\' AS text) || CAST(\'b\' AS text)))',
			$statements[0]
		);

		$metadata = $translator->extract_schema_metadata( $query, true );
		$this->assertSame( '1 + 2', $metadata[0]['columns'][1]['default'] );
		$this->assertSame( 'DATE_ADD(NOW(), INTERVAL 1 YEAR)', $metadata[0]['columns'][2]['default'] );
		$this->assertSame( "CONCAT('a', 'b')", $metadata[0]['columns'][3]['default'] );
		$this->assertSame( 'DEFAULT_GENERATED', $metadata[0]['columns'][1]['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED', $metadata[0]['columns'][2]['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED', $metadata[0]['columns'][3]['extra'] );

		$driver->store_mysql_schema_metadata( $query );
		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_generated_defaults' )[0]->{'Create Table'};

		$this->assertStringContainsString( '  `col1` int NOT NULL DEFAULT (1 + 2)', $create_table );
		$this->assertStringContainsString( '  `col2` datetime NOT NULL DEFAULT (DATE_ADD(NOW(), INTERVAL 1 YEAR))', $create_table );
		$this->assertStringContainsString( "  `col3` varchar(255) NOT NULL DEFAULT (CONCAT('a', 'b'))", $create_table );
	}

