	/**
	 * Tests ALTER TABLE accepts current database-qualified targets and updates metadata.
	 */
	public function test_alter_table_accepts_current_database_qualified_targets_and_updates_metadata(): void {
		$driver = $this->create_driver( 'wp' );

		$driver->query( 'CREATE TABLE wp.t (id INT PRIMARY KEY)' );

		$driver->query( 'ALTER TABLE wp.t ADD COLUMN name VARCHAR(255)' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "t" ADD COLUMN "name" varchar(255)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( "ALTER TABLE `wp`.`t` ADD COLUMN `slug` VARCHAR(191) DEFAULT 'x'" );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "t" ADD COLUMN "slug" varchar(191) DEFAULT \'x\'',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$columns = $this->get_mysql_column_metadata_rows( $driver, 't' );

		$this->assertSame( array( 'id', 'name', 'slug' ), array_column( $columns, 'column_name' ) );
		$this->assertSame( 'varchar(255)', $columns[1]['column_type'] );
		$this->assertSame( 'varchar(191)', $columns[2]['column_type'] );
		$this->assertSame( 'x', $columns[2]['column_default'] );
	}

	/**
	 * Tests ALTER TABLE resolves existing column references case-insensitively.
	 */
	public function test_alter_table_resolves_existing_column_names_case_insensitively(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$this->install_information_schema_fixture( $driver );
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_case_alter (
				value int DEFAULT 1,
				parent_id int,
				obsolete int,
				PRIMARY KEY (value)
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_case_parent (
				id int NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$driver->query( 'ALTER TABLE wptests_case_alter CHANGE COLUMN VaLuE renamed_value bigint NOT NULL DEFAULT 2' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" RENAME COLUMN "value" TO "renamed_value"',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" ALTER COLUMN "renamed_value" TYPE bigint',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" ALTER COLUMN "renamed_value" SET NOT NULL',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" ALTER COLUMN "renamed_value" SET DEFAULT \'2\'',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'ALTER TABLE wptests_case_alter ALTER COLUMN ReNaMeD_Value DROP DEFAULT' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" ALTER COLUMN "renamed_value" DROP DEFAULT',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'ALTER TABLE wptests_case_alter ADD INDEX mixed_case_idx (ReNaMeD_Value DESC)' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'CREATE INDEX "wptests_case_alter__mixed_case_idx" ON "wptests_case_alter" ("renamed_value" DESC)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'ALTER TABLE wptests_case_alter ADD CONSTRAINT parent_fk FOREIGN KEY (PaReNt_Id) REFERENCES wptests_case_parent (ID)' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" ADD CONSTRAINT "parent_fk" FOREIGN KEY ("parent_id") REFERENCES "wptests_case_parent" ("id")',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'ALTER TABLE wptests_case_alter RENAME COLUMN ReNaMeD_Value TO final_value' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" RENAME COLUMN "renamed_value" TO "final_value"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'ALTER TABLE wptests_case_alter DROP COLUMN ObSoLeTe' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_case_alter" DROP COLUMN "obsolete"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$columns      = $this->get_mysql_column_metadata_rows( $driver, 'wptests_case_alter' );
		$indexes      = $this->get_mysql_index_metadata_rows( $driver, 'wptests_case_alter' );
		$foreign_keys = $this->get_mysql_foreign_key_metadata_rows( $driver, 'wptests_case_alter' );

		$this->assertSame( array( 'final_value', 'parent_id' ), array_column( $columns, 'column_name' ) );
		$this->assertSame( array( 'PRIMARY', 'mixed_case_idx' ), array_values( array_unique( array_column( $indexes, 'key_name' ) ) ) );
		$this->assertSame( array( 'final_value', 'final_value' ), array_column( $indexes, 'column_name' ) );
		$this->assertSame( array( 'parent_id' ), array_column( $foreign_keys, 'column_name' ) );
		$this->assertSame( array( 'id' ), array_column( $foreign_keys, 'referenced_column_name' ) );
	}

	/**
	 * Tests unsupported CREATE TABLE column attributes fail before backend execution.
	 */
	public function test_create_table_unsupported_column_attributes_fail_closed_before_backend_execution(): void {
		$queries = array(
			'CREATE TABLE wptests_bad_column_attribute (base int, generated_value int GENERATED ALWAYS AS (base + 1) STORED)',
			'CREATE TABLE wptests_bad_column_attribute (base int, generated_value int GENERATED ALWAYS AS (base + 1) VIRTUAL)',
			'CREATE TABLE wptests_bad_column_attribute (id int INVISIBLE)',
			'CREATE TABLE wptests_bad_column_attribute (id int VISIBLE)',
			'CREATE TABLE wptests_bad_column_attribute (id int COLUMN_FORMAT FIXED)',
			'CREATE TABLE wptests_bad_column_attribute (id int STORAGE DISK)',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported CREATE TABLE column attribute to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported CREATE TABLE column attribute.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests unsupported ALTER TABLE column attributes fail before backend execution.
	 */
	public function test_alter_table_unsupported_column_attributes_fail_closed_before_backend_execution(): void {
		$queries = array(
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN generated_value int GENERATED ALWAYS AS (base + 1) STORED',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN hidden_value int INVISIBLE',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN stored_value int COLUMN_FORMAT FIXED',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN disk_value int STORAGE DISK',
			'ALTER TABLE wptests_bad_column_attribute MODIFY COLUMN hidden_value int INVISIBLE',
			'ALTER TABLE wptests_bad_column_attribute CHANGE COLUMN hidden_value hidden_value int INVISIBLE',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported ALTER TABLE column attribute to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests ALTER TABLE rejects non-current schema-qualified targets before backend execution.
	 */
	public function test_alter_table_rejects_non_current_schema_qualified_targets(): void {
		$queries = array(
			'ALTER TABLE other_db.t ADD COLUMN name VARCHAR(255)'                 => 'Unsupported ALTER TABLE statement.',
			'ALTER TABLE information_schema.tables ADD COLUMN name VARCHAR(255)' => 'Unsupported information_schema query.',
		);

		foreach ( $queries as $query => $message ) {
			$driver = $this->create_driver( 'wp' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported ALTER TABLE target to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}

		$driver = $this->create_driver( 'wp' );
		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		try {
			$driver->query( 'ALTER TABLE tables ADD COLUMN name VARCHAR(255)' );
			$this->fail( 'Expected information_schema ALTER TABLE target to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests CREATE TABLE inline constraints update PostgreSQL and MySQL-facing metadata.
	 */
	public function test_create_table_inline_constraints_update_postgresql_and_show_create_metadata(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_inline_parent (id int(11) PRIMARY KEY) DEFAULT CHARACTER SET utf8mb4' );
		$driver->query(
			'CREATE TABLE wptests_inline_child (
				id int(11) PRIMARY KEY,
				slug varchar(100) UNIQUE,
				score int CHECK (score > 0),
				parent_id int(11) REFERENCES wptests_inline_parent(id) ON DELETE CASCADE ON UPDATE SET NULL
			) DEFAULT CHARACTER SET utf8mb4'
		);
		$this->assertStringContainsString(
			'CONSTRAINT "wptests_inline_child_chk_1" CHECK (score > 0)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$this->assertSame(
			array(
				array(
					'key_name'     => 'PRIMARY',
					'seq_in_index' => '1',
					'column_name'  => 'id',
					'non_unique'   => '0',
					'index_type'   => 'BTREE',
					'collation'    => 'A',
					'sub_part'     => null,
					'nullable'     => '',
				),
				array(
					'key_name'     => 'slug',
					'seq_in_index' => '1',
					'column_name'  => 'slug',
					'non_unique'   => '0',
					'index_type'   => 'BTREE',
					'collation'    => 'A',
					'sub_part'     => null,
					'nullable'     => 'YES',
				),
			),
			$this->get_mysql_index_metadata_rows( $driver, 'wptests_inline_child' )
		);

		$this->assertSame(
			array(
				array(
					'constraint_name'        => 'wptests_inline_child_ibfk_1',
					'seq_in_index'           => '1',
					'column_name'            => 'parent_id',
					'referenced_table_name'  => 'wptests_inline_parent',
					'referenced_column_name' => 'id',
					'update_rule'            => 'SET NULL',
					'delete_rule'            => 'CASCADE',
				),
			),
			$this->get_mysql_foreign_key_metadata_rows( $driver, 'wptests_inline_child' )
		);

		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_inline_child' )[0]->{'Create Table'};
		$this->assertStringContainsString( '  PRIMARY KEY (`id`)', $create_table );
		$this->assertStringContainsString( '  UNIQUE KEY `slug` (`slug`)', $create_table );
		$this->assertStringContainsString(
			'  CONSTRAINT `wptests_inline_child_ibfk_1` FOREIGN KEY (`parent_id`) REFERENCES `wptests_inline_parent` (`id`) ON DELETE CASCADE ON UPDATE SET NULL',
			$create_table
		);
	}

	/**
	 * Tests ALTER TABLE ADD COLUMN inline constraints update PostgreSQL and MySQL-facing metadata.
