	/**
	 * Tests ALTER TABLE ADD FOREIGN KEY forms update PostgreSQL and SHOW CREATE metadata.
	 */
	public function test_alter_table_add_foreign_key_updates_postgresql_and_show_create_metadata(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$driver->query( 'CREATE TABLE wptests_fk_parent (id int NOT NULL, code int NOT NULL, PRIMARY KEY (id, code))' );
		$driver->query( 'CREATE TABLE wptests_fk_child (id int, code int)' );
		$driver->store_mysql_schema_metadata( 'CREATE TABLE wptests_fk_child (id int, code int)' );

		$driver->query( 'ALTER TABLE wptests_fk_child ADD FOREIGN KEY (id) REFERENCES wptests_fk_parent (id)' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_fk_child" ADD CONSTRAINT "wptests_fk_child_ibfk_1" FOREIGN KEY ("id") REFERENCES "wptests_fk_parent" ("id")',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query(
			'ALTER TABLE wptests_fk_child
				ADD CONSTRAINT fk_child_parent FOREIGN KEY (id, code)
				REFERENCES wptests_fk_parent (id, code)
				ON DELETE CASCADE ON UPDATE SET NULL'
		);
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_fk_child" ADD CONSTRAINT "fk_child_parent" FOREIGN KEY ("id", "code") REFERENCES "wptests_fk_parent" ("id", "code") ON DELETE CASCADE ON UPDATE SET NULL',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame(
			array(
				array(
					'constraint_name'        => 'fk_child_parent',
					'seq_in_index'           => '1',
					'column_name'            => 'id',
					'referenced_table_name'  => 'wptests_fk_parent',
					'referenced_column_name' => 'id',
					'update_rule'            => 'SET NULL',
					'delete_rule'            => 'CASCADE',
				),
				array(
					'constraint_name'        => 'fk_child_parent',
					'seq_in_index'           => '2',
					'column_name'            => 'code',
					'referenced_table_name'  => 'wptests_fk_parent',
					'referenced_column_name' => 'code',
					'update_rule'            => 'SET NULL',
					'delete_rule'            => 'CASCADE',
				),
				array(
					'constraint_name'        => 'wptests_fk_child_ibfk_1',
					'seq_in_index'           => '1',
					'column_name'            => 'id',
					'referenced_table_name'  => 'wptests_fk_parent',
					'referenced_column_name' => 'id',
					'update_rule'            => 'NO ACTION',
					'delete_rule'            => 'NO ACTION',
				),
			),
			$this->get_mysql_foreign_key_metadata_rows( $driver, 'wptests_fk_child' )
		);

		$show_create = $driver->query( 'SHOW CREATE TABLE wptests_fk_child' );
		$this->assertStringContainsString(
			'  CONSTRAINT `fk_child_parent` FOREIGN KEY (`id`, `code`) REFERENCES `wptests_fk_parent` (`id`, `code`) ON DELETE CASCADE ON UPDATE SET NULL',
			$show_create[0]->{'Create Table'}
		);
		$this->assertStringContainsString(
			'  CONSTRAINT `wptests_fk_child_ibfk_1` FOREIGN KEY (`id`) REFERENCES `wptests_fk_parent` (`id`)',
			$show_create[0]->{'Create Table'}
		);
		$this->assertStringContainsString(
			WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
			$driver->get_last_postgresql_queries()[2]['sql']
		);
	}

	/**
	 * Tests ALTER TABLE DROP FOREIGN KEY updates PostgreSQL and SHOW CREATE metadata.
	 */
	public function test_alter_table_drop_foreign_key_updates_postgresql_and_show_create_metadata(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$driver->query( 'CREATE TABLE wptests_fk_drop_parent (id int NOT NULL, PRIMARY KEY (id))' );
		$driver->query( 'CREATE TABLE wptests_fk_drop_child (id int)' );
		$driver->store_mysql_schema_metadata( 'CREATE TABLE wptests_fk_drop_child (id int)' );
		$driver->query( 'ALTER TABLE wptests_fk_drop_child ADD FOREIGN KEY (id) REFERENCES wptests_fk_drop_parent (id)' );
		$driver->query( 'ALTER TABLE wptests_fk_drop_child ADD CONSTRAINT fk_drop_parent FOREIGN KEY (id) REFERENCES wptests_fk_drop_parent (id) ON DELETE CASCADE' );

		$driver->query( 'ALTER TABLE wptests_fk_drop_child DROP FOREIGN KEY wptests_fk_drop_child_ibfk_1' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_fk_drop_child" DROP CONSTRAINT "wptests_fk_drop_child_ibfk_1"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame(
			array( 'fk_drop_parent' ),
			array_values( array_unique( array_column( $this->get_mysql_foreign_key_metadata_rows( $driver, 'wptests_fk_drop_child' ), 'constraint_name' ) ) )
		);

		$show_create = $driver->query( 'SHOW CREATE TABLE wptests_fk_drop_child' );
		$this->assertStringContainsString( 'CONSTRAINT `fk_drop_parent` FOREIGN KEY', $show_create[0]->{'Create Table'} );
		$this->assertStringNotContainsString( 'wptests_fk_drop_child_ibfk_1', $show_create[0]->{'Create Table'} );

		$driver->query( 'ALTER TABLE wptests_fk_drop_child DROP FOREIGN KEY fk_drop_parent' );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_fk_drop_child" DROP CONSTRAINT "fk_drop_parent"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame( array(), $this->get_mysql_foreign_key_metadata_rows( $driver, 'wptests_fk_drop_child' ) );

		$show_create = $driver->query( 'SHOW CREATE TABLE wptests_fk_drop_child' );
		$this->assertStringNotContainsString( 'FOREIGN KEY', $show_create[0]->{'Create Table'} );
	}

	/**
	 * Tests PostgreSQL-backed ALTER TABLE foreign keys use catalogs without metadata tables.
	 */
	public function test_alter_table_foreign_keys_use_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured metadata-table catalog checks.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Captured foreign-key catalog queries.
			 *
			 * @var array[]
			 */
			private $foreign_key_catalog_queries = array();

			/**
			 * Whether the fixture foreign key exists in the simulated catalog.
			 *
			 * @var bool
			 */
			private $foreign_key_added = false;

			/**
			 * Execute fixture-backed catalog/foreign-key queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE ) ) {
					throw new RuntimeException( 'Hidden foreign-key metadata table access was not expected for catalog-backed ALTER TABLE FOREIGN KEY.' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query( 'SELECT ? AS column_name', array( (string) ( $params[2] ?? '' ) ) );
				}

				if ( false !== strpos( $sql, 'pg_catalog.pg_constraint con' ) && false !== strpos( $sql, 'con.contype = \'f\'' ) ) {
					$this->foreign_key_catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						$this->foreign_key_added && 'fk_catalog_parent' === (string) ( $params[2] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( 0 === strpos( $sql, 'ALTER TABLE "catalog_fk_child" ADD CONSTRAINT "fk_catalog_parent"' ) ) {
					$this->foreign_key_added = true;
					return parent::query( 'SELECT 1' );
				}

				if ( 'ALTER TABLE "catalog_fk_child" DROP CONSTRAINT "fk_catalog_parent"' === $sql ) {
					$this->foreign_key_added = false;
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}

			/**
			 * Get captured foreign-key catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_foreign_key_catalog_queries(): array {
				return $this->foreign_key_catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$pdo->exec( 'CREATE TABLE catalog_fk_parent (id INTEGER PRIMARY KEY)' );
		$pdo->exec( 'CREATE TABLE catalog_fk_child (id INTEGER, parent_id INTEGER)' );

		$this->assertSame(
			0,
			$driver->query(
				'ALTER TABLE catalog_fk_child
					ADD CONSTRAINT fk_catalog_parent FOREIGN KEY (parent_id)
					REFERENCES catalog_fk_parent (id)
					ON DELETE CASCADE ON UPDATE SET NULL'
			)
		);
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "catalog_fk_child" ADD CONSTRAINT "fk_catalog_parent" FOREIGN KEY ("parent_id") REFERENCES "catalog_fk_parent" ("id") ON DELETE CASCADE ON UPDATE SET NULL',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame( 0, $driver->query( 'ALTER TABLE catalog_fk_child DROP FOREIGN KEY fk_catalog_parent' ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "catalog_fk_child" DROP CONSTRAINT "fk_catalog_parent"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

			$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
			$this->assertNotEmpty( $connection->get_foreign_key_catalog_queries() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

