	/**
	 * Tests MySQL table-option ALTER clauses accept optional-equals forms as no-ops.
	 */
	public function test_alter_table_storage_options_accept_optional_equals_forms_as_noops(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$this->install_information_schema_fixture( $driver );
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_plugin_option_spacing (
				id int(11) NOT NULL,
				status varchar(20) DEFAULT 'draft',
				PRIMARY KEY (id)
			)"
		);

		$columns_before = $this->get_mysql_column_metadata_rows( $driver, 'wptests_plugin_option_spacing' );
		$queries        = array(
			'ALTER TABLE wptests_plugin_option_spacing ENGINE InnoDB',
			'ALTER TABLE wptests_plugin_option_spacing ROW_FORMAT DYNAMIC',
			'ALTER TABLE wptests_plugin_option_spacing DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
			'ALTER TABLE wptests_plugin_option_spacing DEFAULT CHAR SET utf8mb4 COLLATE utf8mb4_unicode_ci',
			'ALTER TABLE wptests_plugin_option_spacing CHAR SET utf8mb4',
			'ALTER TABLE wptests_plugin_option_spacing DEFAULT CHARSET utf8mb4',
			'ALTER TABLE wptests_plugin_option_spacing COLLATE utf8mb4_unicode_ci',
			'ALTER TABLE wptests_plugin_option_spacing CONVERT TO CHAR SET utf8mb4 COLLATE utf8mb4_unicode_ci',
			'ALTER TABLE wptests_plugin_option_spacing STATS_PERSISTENT DEFAULT',
			'ALTER TABLE wptests_plugin_option_spacing ENGINE_ATTRIBUTE "{}"',
		);

		foreach ( $queries as $query ) {
			$this->assertSame( 0, $driver->query( $query ), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}

		$this->assertSame( $columns_before, $this->get_mysql_column_metadata_rows( $driver, 'wptests_plugin_option_spacing' ) );

		$this->assertSame(
			1,
			$driver->query(
				'ALTER TABLE wptests_plugin_option_spacing
					ENGINE InnoDB,
					ADD COLUMN note varchar(20),
					DEFAULT CHAR SET utf8mb4 COLLATE utf8mb4_unicode_ci'
			)
		);
		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_plugin_option_spacing" ADD COLUMN "note" varchar(20)',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);
		$this->assertSame(
			array( 'id', 'status', 'note' ),
			array_column( $this->get_mysql_column_metadata_rows( $driver, 'wptests_plugin_option_spacing' ), 'column_name' )
		);
	}

	/**
	 * Tests ALTER TABLE comment clauses update MySQL-facing metadata.
	 */
	public function test_alter_table_comment_clauses_update_introspection_metadata(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$this->install_information_schema_fixture( $driver );
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_alter_comment_metadata (
				id int(11) NOT NULL COMMENT 'Old id',
				label varchar(20) DEFAULT NULL COMMENT 'Old label',
				PRIMARY KEY (id),
				KEY label_lookup (label) COMMENT 'Old index'
			) COMMENT='Old table'"
		);

		$driver->query(
			"ALTER TABLE wptests_alter_comment_metadata
				COMMENT = 'New table',
				CHANGE COLUMN id id int(11) NOT NULL COMMENT 'New id',
				ADD COLUMN note varchar(100) DEFAULT NULL COMMENT 'Note column',
				ADD KEY note_lookup (note) COMMENT 'Note lookup'"
		);

		$this->assertSame(
			array(
				array(
					'sql'    => 'ALTER TABLE "wptests_alter_comment_metadata" ALTER COLUMN "id" TYPE __wp_mysql_int_11',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_alter_comment_metadata" ALTER COLUMN "id" SET NOT NULL',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_alter_comment_metadata" ALTER COLUMN "id" DROP DEFAULT',
					'params' => array(),
				),
				array(
					'sql'    => 'ALTER TABLE "wptests_alter_comment_metadata" ADD COLUMN "note" varchar(100) DEFAULT NULL',
					'params' => array(),
				),
				array(
					'sql'    => 'CREATE INDEX "wptests_alter_comment_metadata__note_lookup" ON "wptests_alter_comment_metadata" ("note")',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$column_comments = $driver->get_connection()->query(
			sprintf(
				'SELECT column_name, column_comment
				FROM %s
				WHERE table_schema = ? AND table_name = ?
				ORDER BY ordinal_position',
				$driver->get_connection()->quote_identifier( WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( 'public', 'wptests_alter_comment_metadata' )
		)->fetchAll( PDO::FETCH_KEY_PAIR );
		$this->assertSame( 'New id', $column_comments['id'] );
		$this->assertSame( 'Note column', $column_comments['note'] );

		$index_comments = $driver->get_connection()->query(
			sprintf(
				'SELECT key_name, index_comment
				FROM %s
				WHERE table_schema = ? AND table_name = ?
				ORDER BY index_ordinal, seq_in_index',
				$driver->get_connection()->quote_identifier( WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE )
			),
			array( 'public', 'wptests_alter_comment_metadata' )
		)->fetchAll( PDO::FETCH_KEY_PAIR );
		$this->assertSame( 'Note lookup', $index_comments['note_lookup'] );

		$table_comment = $driver->get_connection()->query(
			sprintf(
				'SELECT table_comment
				FROM %s
				WHERE table_schema = ? AND table_name = ?',
				$driver->get_connection()->quote_identifier( WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE )
			),
			array( 'public', 'wptests_alter_comment_metadata' )
		)->fetchColumn();
		$this->assertSame( 'New table', $table_comment );

		$create_table = $driver->query( 'SHOW CREATE TABLE wptests_alter_comment_metadata' )[0]->{'Create Table'};
		$this->assertStringContainsString( "  `id` int(11) NOT NULL COMMENT 'New id'", $create_table );
		$this->assertStringContainsString( "  `note` varchar(100) DEFAULT NULL COMMENT 'Note column'", $create_table );
		$this->assertStringContainsString( "  KEY `note_lookup` (`note`) COMMENT 'Note lookup'", $create_table );
		$this->assertStringEndsWith( "COMMENT='New table'", $create_table );
	}

	/**
	 * Tests PostgreSQL-backed ALTER TABLE COMMENT uses catalogs without metadata tables.
	 */
	public function test_alter_table_comment_uses_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured metadata-table catalog checks.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE ) ) {
					throw new RuntimeException( 'Hidden table metadata table access was not expected for catalog-backed ALTER TABLE COMMENT.' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'pg_catalog.obj_description(t.oid, \'pg_class\')' ) ) {
					return parent::query(
						"SELECT '__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=\nPrevious table note' AS table_comment"
					);
				}

				if ( 0 === strpos( $sql, 'COMMENT ON TABLE ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$pdo->exec( 'CREATE TABLE catalog_alter_comment (id INTEGER)' );

		$this->assertSame( 0, $driver->query( "ALTER TABLE catalog_alter_comment COMMENT = 'Catalog table note'" ) );
		$this->assertSame(
			array(
				array(
					'sql'    => "COMMENT ON TABLE \"public\".\"catalog_alter_comment\" IS E'__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=\\nCatalog table note'",
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

