		$this->assertStringNotContainsString( 'SHOW FIELDS', strtoupper( $queries[0]['sql'] ) );

		$result = $driver->query( 'SHOW COLUMNS FROM wptests_options WHERE LENGTH(Field) * 2 = 16' );

		$this->assertSame(
			array( 'autoload' ),
			array_map(
				static function ( $row ): string {
					return $row->Field;
				},
				$result
			)
