	public function test_show_grants_for_and_using_forms_return_static_row(): void {
		$queries = array(
			'SHOW GRANTS FOR current_user();',
			'SHOW GRANTS FOR CURRENT_USER',
			'sHoW gRaNtS FoR CuRrEnT_UsEr()',
			'SHOW GRANTS FOR root',
			"SHOW GRANTS FOR 'root'@'localhost'",
