	/**
	 * Tests SHOW CHARACTER SET returns MySQL-shaped static character set rows.
	 */
	public function test_show_character_set_returns_mysql_shaped_rows(): void {
		$driver = $this->create_driver();

		$rows = $driver->query( 'SHOW CHARACTER SET' );

		$this->assertEquals(
			array(
				(object) array(
					'Charset'           => 'binary',
					'Description'       => 'Binary pseudo charset',
					'Default collation' => 'binary',
					'Maxlen'            => '1',
				),
				(object) array(
					'Charset'           => 'utf8',
					'Description'       => 'UTF-8 Unicode',
					'Default collation' => 'utf8_general_ci',
					'Maxlen'            => '3',
				),
				(object) array(
					'Charset'           => 'utf8mb4',
					'Description'       => 'UTF-8 Unicode',
					'Default collation' => 'utf8mb4_0900_ai_ci',
					'Maxlen'            => '4',
				),
			),
			$rows
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame(
			array( 'Charset', 'Description', 'Default collation', 'Maxlen' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);

		$charset_rows = $driver->query( 'SHOW CHARSET' );
		$this->assertEquals( $rows, $charset_rows );

		$like_rows = $driver->query( "SHOW CHARACTER SET LIKE 'utf8%'" );
		$this->assertSame(
			array( 'utf8', 'utf8mb4' ),
			array_map(
				static function ( $row ): string {
					return $row->Charset;
				},
				$like_rows
			)
		);

		$where_rows = $driver->query( "SHOW CHARACTER SET WHERE Charset = 'utf8mb4'" );
		$this->assertSame( array( 'utf8mb4' ), array( $where_rows[0]->Charset ) );

		$collation_rows = $driver->query( "SHOW CHARACTER SET WHERE `Default collation` = 'binary'" );
		$this->assertSame( array( 'binary' ), array( $collation_rows[0]->Charset ) );

		$where_expression_rows = $driver->query( "SHOW CHARACTER SET WHERE Charset <> 'binary' AND Maxlen >= 4" );
		$this->assertSame( array( 'utf8mb4' ), array( $where_expression_rows[0]->Charset ) );

		$literal_left_rows = $driver->query( "SHOW CHARACTER SET WHERE 'Charset' = 'utf8mb4'" );
		$this->assertSame( array(), $literal_left_rows );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests SHOW COLLATION returns MySQL-shaped static collation rows.
	 */
	public function test_show_collation_returns_mysql_shaped_rows(): void {
		$driver = $this->create_driver();

		$rows = $driver->query( 'SHOW COLLATION' );

		$this->assertSame(
			array(
				'binary',
				'utf8_bin',
				'utf8_general_ci',
				'utf8_unicode_ci',
				'utf8mb4_bin',
				'utf8mb4_unicode_ci',
				'utf8mb4_0900_ai_ci',
			),
			array_map(
				static function ( $row ) {
					return $row->Collation;
				},
				$rows
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame(
			array( 'Collation', 'Charset', 'Id', 'Default', 'Compiled', 'Sortlen', 'Pad_attribute' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);

		$like_rows = $driver->query( "SHOW COLLATION LIKE 'utf8%'" );
		$this->assertCount( 6, $like_rows );
		$this->assertSame( 'utf8_bin', $like_rows[0]->Collation );
		$this->assertSame( 'utf8mb4_0900_ai_ci', $like_rows[5]->Collation );

		$where_rows = $driver->query( "SHOW COLLATION WHERE Collation = 'utf8_bin'" );
		$this->assertSame( array( 'utf8_bin' ), array( $where_rows[0]->Collation ) );

		$case_insensitive_charset_rows = $driver->query( "SHOW COLLATION WHERE Charset = 'UTF8'" );
		$this->assertSame(
			array( 'utf8_bin', 'utf8_general_ci', 'utf8_unicode_ci' ),
			array_map(
				static function ( $row ): string {
					return $row->Collation;
				},
				$case_insensitive_charset_rows
			)
		);

		$binary_charset_rows = $driver->query( "SHOW COLLATION WHERE BINARY Charset = 'UTF8'" );
		$this->assertSame( array(), $binary_charset_rows );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$where_expression_rows = $driver->query( "SHOW COLLATION WHERE Collation LIKE 'utf8%' AND Charset = 'utf8'" );
		$this->assertSame(
			array( 'utf8_bin', 'utf8_general_ci', 'utf8_unicode_ci' ),
			array_map(
				static function ( $row ): string {
					return $row->Collation;
				},
				$where_expression_rows
			)
		);

		$not_equal_rows = $driver->query( "SHOW COLLATION WHERE Collation <> 'binary' AND Charset = 'utf8mb4'" );
		$this->assertSame(
			array( 'utf8mb4_bin', 'utf8mb4_unicode_ci', 'utf8mb4_0900_ai_ci' ),
			array_map(
				static function ( $row ): string {
					return $row->Collation;
				},
				$not_equal_rows
			)
		);

		$literal_left_rows = $driver->query( "SHOW COLLATION WHERE 'Collation' = 'utf8_bin'" );
		$this->assertSame( array(), $literal_left_rows );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests PostgreSQL-backed SHOW CHARACTER SET/COLLATION do not use hidden metadata.
	 */
	public function test_show_charset_and_collation_do_not_use_hidden_metadata_for_pgsql_connections(): void {
		$connection = new class( array( 'pdo' => $this->create_pgsql_reporting_sqlite_pdo() ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured backend queries.
			 *
			 * @var string[]
			 */
			private $queries = array();

			/**
			 * Capture unexpected backend queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				$this->queries[] = $sql;

				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHARSET_METADATA_TABLE,
					) as $metadata_table
				) {
					if ( false !== strpos( $sql, $metadata_table ) ) {
						throw new RuntimeException( 'Hidden metadata table access was not expected for PostgreSQL-backed charset metadata.' );
					}
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured backend query SQL.
			 *
			 * @return string[] Captured queries.
			 */
			public function get_queries(): array {
				return $this->queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$character_sets = $driver->query( 'SHOW CHARACTER SET' );
		$this->assertSame( array( 'binary', 'utf8', 'utf8mb4' ), array_column( $character_sets, 'Charset' ) );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$collations = $driver->query( "SHOW COLLATION WHERE Charset = 'utf8mb4'" );
		$this->assertSame(
			array( 'utf8mb4_bin', 'utf8mb4_unicode_ci', 'utf8mb4_0900_ai_ci' ),
			array_column( $collations, 'Collation' )
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( array(), $connection->get_queries() );
		$this->assertSame(
			array(),
			$connection->get_pdo()->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests SHOW DATABASES and SHOW SCHEMAS return MySQL-shaped database rows.
	 */
	public function test_show_databases_and_schemas_return_mysql_shaped_rows(): void {
		$driver = $this->create_driver();

		$databases = $driver->query( 'SHOW DATABASES' );

		$this->assertEquals(
			array(
				(object) array( 'Database' => 'information_schema' ),
				(object) array( 'Database' => 'wptests' ),
			),
			$databases
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( array( 'Database' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$like_rows = $driver->query( 'SHOW DATABASES LIKE "w%"' );
		$this->assertEquals( array( (object) array( 'Database' => 'wptests' ) ), $like_rows );

		$where_rows = $driver->query( 'SHOW DATABASES WHERE `Database` = "information_schema"' );
		$this->assertEquals( array( (object) array( 'Database' => 'information_schema' ) ), $where_rows );

		$where_rows = $driver->query( "SHOW DATABASES WHERE Database = 'information_schema'" );
		$this->assertEquals( array( (object) array( 'Database' => 'information_schema' ) ), $where_rows );

		$where_like_rows = $driver->query( "SHOW DATABASES WHERE Database LIKE 'info%'" );
		$this->assertEquals( array( (object) array( 'Database' => 'information_schema' ) ), $where_like_rows );

		$where_or_rows = $driver->query( "SHOW DATABASES WHERE Database = 'wptests' OR Database = 'information_schema'" );
		$this->assertEquals( $databases, $where_or_rows );

		$this->assertSame( array(), $driver->query( "SHOW DATABASES WHERE 'Database' = 'information_schema'" ) );
		$this->assertSame( array(), $driver->query( 'SHOW DATABASES WHERE "Database" = \'information_schema\'' ) );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$schemas = $driver->query( 'SHOW SCHEMAS' );
		$this->assertEquals( $databases, $schemas );
	}

	/**
	 * Tests PostgreSQL-backed SHOW DATABASES/SCHEMAS uses native catalogs.
	 */
	public function test_show_databases_and_schemas_use_postgresql_catalog_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_queries = array();

			/**
			 * Execute fixture-backed catalog queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, '__wp_postgresql_mysql_' ) ) {
					throw new RuntimeException( 'Hidden metadata table access was not expected for catalog-backed SHOW DATABASES.' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					$this->catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						"SELECT 'information_schema' AS \"Database\"
						UNION ALL SELECT 'plugin_schema'
						UNION ALL SELECT 'wptests'"
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_queries(): array {
				return $this->catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$databases = $driver->query( 'SHOW DATABASES' );

		$this->assertEquals(
			array(
				(object) array( 'Database' => 'information_schema' ),
				(object) array( 'Database' => 'plugin_schema' ),
				(object) array( 'Database' => 'wptests' ),
			),
			$databases
		);
		$this->assertSame(
			array(
				array(
					'sql'    => $connection->get_catalog_queries()[0]['sql'],
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$plugin_rows = $driver->query( 'SHOW DATABASES LIKE "plugin%"' );
		$this->assertEquals( array( (object) array( 'Database' => 'plugin_schema' ) ), $plugin_rows );

		$selected_rows = $driver->query( "SHOW SCHEMAS WHERE Database = 'wptests' OR Database = 'information_schema'" );
		$this->assertEquals(
			array(
				(object) array( 'Database' => 'information_schema' ),
				(object) array( 'Database' => 'wptests' ),
			),
			$selected_rows
		);
		$this->assertCount( 3, $connection->get_catalog_queries() );

		$catalog_query = $connection->get_catalog_queries()[0]['sql'];
		$this->assertStringContainsString( 'FROM information_schema.schemata s', $catalog_query );
		$this->assertStringContainsString( 's."SCHEMA_NAME" AS "Database"', $catalog_query );
		$this->assertStringContainsString( 'AS "SCHEMA_NAME"', $catalog_query );
		$this->assertStringContainsString( 'LEFT(s.schema_name, 3) <> \'pg_\'', $catalog_query );
		$this->assertStringContainsString( 'ORDER BY "Database"', $catalog_query );
		$this->assertStringNotContainsString( '__wp_postgresql_mysql_', $catalog_query );
	}

	/**
	 * Tests SQLite-compatible FOUND_ROWS() accounting for static SHOW/admin rows.
	 */
	public function test_static_show_and_table_administration_update_found_rows_accounting(): void {
		$driver = $this->create_driver();

		$driver->query( 'SHOW PROCESSLIST' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW VARIABLES' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '0', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW COLLATION' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '7', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( "SHOW COLLATION WHERE Collation LIKE 'utf8mb4%'" );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '3', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW CHARACTER SET' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '3', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW DATABASES' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '2', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( "SHOW DATABASES WHERE Database = 'missing'" );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '0', $found_rows[0]->{'FOUND_ROWS()'} );

		$this->install_information_schema_fixture( $driver );

		$driver->query( 'SHOW COLUMNS FROM wptests_options' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '4', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW PROCESSLIST' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW COLUMNS FROM wptests_options' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '4', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( "SHOW TABLES LIKE 'wptests_%'" );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '3', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( "SHOW TABLE STATUS WHERE Name = 'wptests_options'" );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'SHOW CREATE TABLE wptests_missing' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '0', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'CREATE TABLE found_rows_admin (id INTEGER)' );
		$driver->query( 'ANALYZE TABLE found_rows_admin' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

		$driver->query( 'OPTIMIZE TABLE found_rows_missing' );
		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '2', $found_rows[0]->{'FOUND_ROWS()'} );
	}

	/**
	 * Tests SHOW CREATE DATABASE/SCHEMA return MySQL-shaped static metadata.
	 */
	public function test_show_create_database_returns_mysql_shaped_metadata(): void {
		$driver = $this->create_driver();

		$rows = $driver->query( 'SHOW CREATE DATABASE `wptests`' );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'wptests', $rows[0]->Database );
		$this->assertSame(
			'CREATE DATABASE `wptests` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
			$rows[0]->{'Create Database'}
		);
		$this->assertSame( array( 'Database', 'Create Database' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$rows = $driver->query( 'SHOW CREATE SCHEMA IF NOT EXISTS wptests', PDO::FETCH_ASSOC );
		$this->assertSame(
			array(
				array(
					'Database'        => 'wptests',
					'Create Database' => 'CREATE DATABASE IF NOT EXISTS `wptests` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
				),
			),
			$rows
		);

		$this->assertSame( array(), $driver->query( 'SHOW CREATE DATABASE missing_database' ) );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests PostgreSQL-backed SHOW CREATE DATABASE/SCHEMA uses native catalogs.
	 */
	public function test_show_create_database_uses_postgresql_catalog_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_queries = array();

			/**
			 * Execute fixture-backed catalog queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, '__wp_postgresql_mysql_' ) ) {
					throw new RuntimeException( 'Hidden metadata table access was not expected for catalog-backed SHOW CREATE DATABASE.' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					$this->catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					$database = (string) ( $params[1] ?? '' );
					return parent::query(
						in_array( $database, array( 'wptests', 'plugin_schema', 'information_schema' ), true )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_queries(): array {
				return $this->catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$rows = $driver->query( 'SHOW CREATE DATABASE wptests' );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'wptests', $rows[0]->Database );
		$this->assertSame(
			'CREATE DATABASE `wptests` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
			$rows[0]->{'Create Database'}
		);
		$this->assertSame(
			array(
				array(
					'sql'    => $connection->get_catalog_queries()[0]['sql'],
					'params' => array( 'wptests', 'wptests' ),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$schema_rows = $driver->query( 'SHOW CREATE SCHEMA plugin_schema', PDO::FETCH_ASSOC );
		$this->assertSame(
			array(
				array(
					'Database'        => 'plugin_schema',
					'Create Database' => 'CREATE DATABASE `plugin_schema` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
				),
			),
			$schema_rows
		);

		$this->assertSame( array(), $driver->query( 'SHOW CREATE DATABASE missing_schema' ) );
		$this->assertCount( 3, $connection->get_catalog_queries() );

		$catalog_query = $connection->get_catalog_queries()[0]['sql'];
		$this->assertStringContainsString( 'FROM information_schema.schemata s', $catalog_query );
		$this->assertStringContainsString( 'AS "SCHEMA_NAME"', $catalog_query );
		$this->assertStringContainsString( 's."SCHEMA_NAME" = ?', $catalog_query );
		$this->assertStringContainsString( 'LEFT(s.schema_name, 3) <> \'pg_\'', $catalog_query );
		$this->assertStringNotContainsString( '__wp_postgresql_mysql_', $catalog_query );
	}

