	/**
	 * Tests USE information_schema routes supported direct table reads.
	 */
	public function test_use_statement_information_schema_table_reads_route_supported_relations(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_direct_information_schema_options_metadata( $driver );

		try {
			$driver->query( 'SELECT variable_name FROM server_status' );
			$this->fail( 'Expected unqualified server_status to be treated as an application table before USE information_schema.' );
		} catch ( PDOException $e ) {
			$this->assertStringContainsString( 'no such table: server_status', $e->getMessage() );
		}

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$columns = $driver->query(
			"SELECT t.table_name AS table_name, c.column_name AS column_name
			FROM tables AS t, columns AS c
			WHERE c.table_schema = t.table_schema
				AND c.table_name = t.table_name
				AND t.table_name = 'wptests_options'
			ORDER BY c.ordinal_position"
		);

		$this->assertSame(
			array(
				array( 'wptests_options', 'option_id' ),
				array( 'wptests_options', 'option_name' ),
				array( 'wptests_options', 'option_value' ),
				array( 'wptests_options', 'autoload' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->table_name, $row->column_name );
				},
				$columns
			)
		);

		$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'AS "t"', $sql );
		$this->assertStringContainsString( 'AS "c"', $sql );
		$this->assertStringContainsString( '"c"."TABLE_SCHEMA" = "t"."TABLE_SCHEMA"', $sql );

		$checks = $driver->query(
			"SELECT tc.constraint_name AS constraint_name, cc.check_clause AS check_clause
			FROM table_constraints AS tc
			JOIN check_constraints AS cc
				ON cc.constraint_schema = tc.constraint_schema
				AND cc.constraint_name = tc.constraint_name
			WHERE tc.table_name = 'wptests_posts'"
		);

		$this->assertEquals(
			array(
				(object) array(
					'constraint_name' => 'wptests_posts_status_chk',
					'check_clause'    => 'post_status IS NOT NULL',
				),
			),
			$checks
		);

		$status = $driver->query(
			"SELECT variable_name AS variable_name
			FROM server_status
			WHERE variable_name = 'Threads_connected'"
		);

		$this->assertEquals(
			array(
				(object) array(
					'variable_name' => 'Threads_connected',
				),
			),
			$status
		);
		$this->assertStringContainsString(
			'AS "server_status"',
			$this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'AS "server_status"' )
		);

		$status_names = $driver->query( 'SELECT variable_name FROM server_status' );
		$this->assertContains( 'Threads_connected', array_column( $status_names, 'VARIABLE_NAME' ) );
	}

	/**
	 * Tests USE information_schema routes multi-source catalog joins.
	 */
	public function test_use_statement_information_schema_routes_multi_source_catalog_joins(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_direct_information_schema_options_metadata( $driver );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$rows = $driver->query(
			"SELECT t.table_name AS table_name, c.column_name AS column_name, s.index_name AS index_name
			FROM tables AS t
			JOIN columns AS c USING (table_schema, table_name)
			LEFT JOIN statistics AS s
				ON s.table_schema = c.table_schema
				AND s.table_name = c.table_name
				AND s.column_name = c.column_name
			WHERE t.table_name = 'wptests_options'
			ORDER BY c.ordinal_position, s.index_name"
		);

		$this->assertSame(
			array(
				array( 'wptests_options', 'option_id', 'PRIMARY' ),
				array( 'wptests_options', 'option_name', 'option_name' ),
				array( 'wptests_options', 'option_value', null ),
				array( 'wptests_options', 'autoload', 'autoload' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->table_name, $row->column_name, $row->index_name );
				},
				$rows
			)
		);

		$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'AS "t"', $sql );
		$this->assertStringContainsString( 'AS "c"', $sql );
		$this->assertStringContainsString( 'AS "s"', $sql );
		$this->assertStringContainsString( 'LEFT JOIN', $sql );
	}

	/**
	 * Tests USE information_schema routes supported CTE reads.
	 */
	public function test_use_statement_information_schema_cte_selects_route_supported_relations(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_direct_information_schema_options_metadata( $driver );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$rows = $driver->query(
			"WITH
				cols AS (
					SELECT column_name
					FROM columns
					WHERE table_name = 'wptests_options'
				),
				indexes AS (
					SELECT DISTINCT index_name
					FROM statistics
					WHERE table_name = 'wptests_options'
				)
			SELECT CONCAT(column_name, ' (column)') AS name
			FROM cols
			UNION ALL
			SELECT CONCAT(index_name, ' (index)') AS name
			FROM indexes
			ORDER BY name"
		);

		$this->assertSame(
			array(
				'PRIMARY (index)',
				'autoload (column)',
				'autoload (index)',
				'option_id (column)',
				'option_name (column)',
				'option_name (index)',
				'option_value (column)',
			),
			array_column( $rows, 'name' )
		);

		$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'WITH "cols" ("column_name") AS', $sql );
		$this->assertStringContainsString( '"indexes" ("index_name") AS', $sql );
		$this->assertStringContainsString( 'AS "columns"', $sql );
		$this->assertStringContainsString( 'AS "statistics"', $sql );
		$this->assertStringContainsString( 'UNION ALL', $sql );
	}

	/**
	 * Tests USE information_schema routes final CTE SELECT reads from supported relations.
	 */
	public function test_use_statement_information_schema_cte_final_select_routes_supported_relations(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_direct_information_schema_options_metadata( $driver );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$rows = $driver->query(
			"WITH cols AS (
				SELECT DISTINCT table_name
				FROM columns
				WHERE table_name = 'wptests_options'
			)
			SELECT t.table_name AS table_name, t.table_type AS table_type
			FROM cols
			JOIN tables AS t ON t.table_name = cols.table_name
			ORDER BY t.table_name"
		);

		$this->assertEquals(
			array(
				(object) array(
					'table_name' => 'wptests_options',
					'table_type' => 'BASE TABLE',
				),
			),
			$rows
		);

		$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'WITH "cols" ("table_name") AS', $sql );
		$this->assertStringContainsString( '"cols" AS "cols"', $sql );
		$this->assertStringContainsString( 'AS "t"', $sql );
		$this->assertStringContainsString( 'USING ("TABLE_NAME")', $sql );
	}

