				(object) array(
					'Field'   => 'TABLE_NAME',
					'Type'    => 'varchar(512)',
					'Null'    => 'YES',
					'Key'     => '',
					'Default' => null,
					'Extra'   => '',
				),
			),
			$columns
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$full_fields = $driver->query( "SHOW FULL FIELDS FROM columns WHERE Field = 'COLUMN_NAME'" );

		$this->assertCount( 1, $full_fields );
