			if ( 1 === preg_match( '/^SELECT\s+NULL AS "[A-Z0-9_]+"(?:,\s+NULL AS "[A-Z0-9_]+")*\s+WHERE 1 = 0$/s', $sql ) ) {
				$empty_relations[] = $relation;
			}
		}

		sort( $empty_relations );
		sort( $empty_allowlist );

		$this->assertSame( $empty_allowlist, $empty_relations );
