	/**
	 * Tests privilege/security information_schema relations are empty and queryable.
	 */
	public function test_direct_information_schema_privilege_security_relations_are_empty_and_queryable(): void {
		$relations = array(
			'user_privileges'                   => array( 'GRANTEE', 'TABLE_CATALOG', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'schema_privileges'                 => array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'table_privileges'                  => array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'column_privileges'                 => array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'COLUMN_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'applicable_roles'                  => array( 'USER', 'HOST', 'GRANTEE', 'GRANTEE_HOST', 'ROLE_NAME', 'ROLE_HOST', 'IS_GRANTABLE', 'IS_DEFAULT', 'IS_MANDATORY' ),
			'administrable_role_authorizations' => array( 'USER', 'HOST', 'GRANTEE', 'GRANTEE_HOST', 'ROLE_NAME', 'ROLE_HOST', 'IS_GRANTABLE', 'IS_DEFAULT', 'IS_MANDATORY' ),
			'enabled_roles'                     => array( 'ROLE_NAME', 'ROLE_HOST', 'IS_DEFAULT', 'IS_MANDATORY' ),
			'role_table_grants'                 => array( 'GRANTOR', 'GRANTOR_HOST', 'GRANTEE', 'GRANTEE_HOST', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'role_column_grants'                => array( 'GRANTOR', 'GRANTOR_HOST', 'GRANTEE', 'GRANTEE_HOST', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'COLUMN_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			'role_routine_grants'               => array( 'GRANTOR', 'GRANTOR_HOST', 'GRANTEE', 'GRANTEE_HOST', 'SPECIFIC_CATALOG', 'SPECIFIC_SCHEMA', 'SPECIFIC_NAME', 'ROUTINE_CATALOG', 'ROUTINE_SCHEMA', 'ROUTINE_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
		);

		foreach ( $relations as $relation => $columns ) {
			$driver = $this->create_driver();
			$rows   = $driver->query( "SELECT * FROM information_schema.$relation" );

			$this->assertSame( array(), $rows, $relation );
			$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ), $relation );
		}

		$driver = $this->create_driver();
		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$roles = $driver->query( "SELECT ROLE_NAME FROM enabled_roles WHERE IS_DEFAULT = 'YES'" );
		$this->assertSame( array(), $roles );
		$this->assertSame( array( 'ROLE_NAME' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$columns = $driver->query( "SHOW COLUMNS FROM enabled_roles LIKE 'IS_%'" );
		$this->assertSame( array( 'IS_DEFAULT', 'IS_MANDATORY' ), array_column( $columns, 'Field' ) );

		$grant_columns = $driver->query( "SHOW COLUMNS FROM role_table_grants LIKE '%GRANT%'" );
		$this->assertSame(
			array( 'GRANTOR', 'GRANTOR_HOST', 'GRANTEE', 'GRANTEE_HOST', 'IS_GRANTABLE' ),
			array_column( $grant_columns, 'Field' )
		);

		$describe = $driver->query( 'DESCRIBE role_routine_grants' );
		$this->assertSame(
			array(
				'GRANTOR',
				'GRANTOR_HOST',
				'GRANTEE',
				'GRANTEE_HOST',
				'SPECIFIC_CATALOG',
				'SPECIFIC_SCHEMA',
				'SPECIFIC_NAME',
				'ROUTINE_CATALOG',
				'ROUTINE_SCHEMA',
				'ROUTINE_NAME',
				'PRIVILEGE_TYPE',
				'IS_GRANTABLE',
			),
			array_column( $describe, 'Field' )
		);

		$qualified_describe = $driver->query( 'DESC information_schema.role_table_grants' );
		$this->assertSame(
			array( 'GRANTOR', 'GRANTOR_HOST', 'GRANTEE', 'GRANTEE_HOST', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			array_column( $qualified_describe, 'Field' )
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$joined = $driver->query(
			'SELECT p.GRANTEE, t.TABLE_NAME
			FROM information_schema.role_table_grants AS p
			JOIN information_schema.tables AS t
				ON p.TABLE_SCHEMA = t.TABLE_SCHEMA
				AND p.TABLE_NAME = t.TABLE_NAME'
		);

		$this->assertSame( array(), $joined );
		$this->assertSame( array( 'GRANTEE', 'TABLE_NAME' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$role_join = $driver->query(
			'SELECT c.GRANTEE, r.ROUTINE_NAME
			FROM information_schema.role_column_grants AS c
			LEFT JOIN information_schema.role_routine_grants AS r
				ON r.GRANTEE = c.GRANTEE'
		);

		$this->assertSame( array(), $role_join );
		$this->assertSame( array( 'GRANTEE', 'ROUTINE_NAME' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		try {
			$driver->query( 'SELECT * FROM information_schema.role_database_grants' );
			$this->fail( 'Expected unsupported role grant relation to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests plugin-facing empty information_schema metadata relations are queryable.
	 */
	public function test_direct_information_schema_empty_plugin_metadata_relations_are_queryable(): void {
		$driver = $this->create_driver();

		$views = $driver->query(
			'SELECT COUNT(*) AS view_count
			FROM information_schema.views
			WHERE table_schema = DATABASE()'
		);

		$this->assertSame( '0', $views[0]->view_count );

		$trigger_columns = $driver->query( "SHOW COLUMNS FROM information_schema.triggers LIKE 'TRIGGER_%'" );
		$this->assertSame(
			array( 'TRIGGER_CATALOG', 'TRIGGER_SCHEMA', 'TRIGGER_NAME' ),
			array_column( $trigger_columns, 'Field' )
		);

		$routines = $driver->query(
			"SELECT ROUTINE_NAME
			FROM information_schema.routines
			WHERE ROUTINE_SCHEMA = DATABASE()
				AND ROUTINE_TYPE IN ('FUNCTION', 'PROCEDURE')"
		);

		$this->assertSame( array(), $routines );

		$parameters = $driver->query(
			'SELECT COUNT(*) AS parameter_count
			FROM information_schema.parameters
			WHERE specific_schema = DATABASE()'
		);

		$this->assertCount( 1, $parameters );
		$this->assertSame( '0', $parameters[0]->parameter_count );

		$parameter_rows = $driver->query(
			"SELECT DTD_IDENTIFIER
			FROM INFORMATION_SCHEMA.PARAMETERS
			WHERE SPECIFIC_NAME = 'f1'"
		);

		$this->assertSame( array(), $parameter_rows );
		$this->assertSame( array( 'DTD_IDENTIFIER' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$parameter_columns = $driver->query( "SHOW COLUMNS FROM information_schema.parameters LIKE 'PARAMETER_%'" );
		$this->assertSame(
			array( 'PARAMETER_MODE', 'PARAMETER_NAME' ),
			array_column( $parameter_columns, 'Field' )
		);

		$show_create = $driver->query( 'SHOW CREATE TABLE INFORMATION_SCHEMA.PARAMETERS' );

		$this->assertCount( 1, $show_create );
		$this->assertSame( 'PARAMETERS', $show_create[0]->Table );
		$this->assertStringContainsString( '  `SPECIFIC_NAME` varchar(512) DEFAULT NULL', $show_create[0]->{'Create Table'} );
		$this->assertStringContainsString( '  `DTD_IDENTIFIER` varchar(512) DEFAULT NULL', $show_create[0]->{'Create Table'} );

		$routine_parameters = $driver->query(
			'SELECT r.routine_name, p.parameter_name
			FROM information_schema.routines AS r
			LEFT JOIN information_schema.parameters AS p
				ON p.specific_schema = r.routine_schema
				AND p.specific_name = r.specific_name
			WHERE r.routine_schema = DATABASE()'
		);

		$this->assertSame( array(), $routine_parameters );
		$this->assertSame(
			array(),
			$driver->get_connection()->get_pdo()->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

