	/**
	 * Tests column-reference metadata lookups use PostgreSQL catalogs.
	 */
	public function test_column_reference_metadata_lookups_use_postgresql_catalog_for_pgsql_connections(): void {
		$connection = new WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection(
			array(
				'pdo' => new PDO( 'sqlite::memory:' ),
			)
		);
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$pdo        = $connection->get_pdo();
		$pdo->exec( "ATTACH DATABASE ':memory:' AS information_schema" );
		$pdo->exec(
			'CREATE TABLE information_schema.columns (
				table_schema TEXT NOT NULL,
				table_name TEXT NOT NULL,
				column_name TEXT NOT NULL,
				ordinal_position INTEGER NOT NULL,
				data_type TEXT NOT NULL,
				character_maximum_length INTEGER,
				numeric_precision INTEGER,
				numeric_scale INTEGER,
				collation_name TEXT,
				column_default TEXT,
				is_identity TEXT,
				domain_name TEXT
			)'
		);
		$pdo->exec(
			"INSERT INTO information_schema.columns
				(table_schema, table_name, column_name, ordinal_position, data_type, character_maximum_length, numeric_precision, numeric_scale, collation_name, column_default, is_identity, domain_name)
			VALUES
				('public', 'wptests_posts', 'ID', 1, 'integer', NULL, NULL, NULL, NULL, NULL, 'NO', NULL),
				('public', 'wptests_posts', 'post_title', 2, 'character varying', 191, NULL, NULL, 'utf8mb4_unicode_ci', NULL, 'NO', NULL)"
		);
		$get_name = Closure::bind(
			function ( string $column ): ?string {
				return $this->get_mysql_table_catalog_column_name( 'public', 'wptests_posts', $column );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		$this->assertSame( 'ID', $get_name( 'id' ) );
		$this->assertSame( 'post_title', $get_name( 'post_title' ) );
		$this->assertNull( $get_name( 'missing_column' ) );

		$pgsql_pdo         = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$pgsql_connection  = new class( array( 'pdo' => $pgsql_pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_queries = array();

			/**
			 * Execute fixture-backed catalog queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if (
					false !== strpos( $sql, 'FROM information_schema.columns c' )
					&& false !== strpos( $sql, 'pg_catalog.col_description(pc.oid, pa.attnum)' )
					&& isset( $params[2] )
				) {
					$this->catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					if ( false !== strpos( $sql, ' AS column_type' ) ) {
						return parent::query( "SELECT 'enum(''draft'',''published'')' AS column_type" );
					}

					return parent::query( "SELECT 'utf8mb4_unicode_ci' AS collation_name" );
				}

				if (
					false !== strpos( $sql, 'FROM information_schema.columns c' )
					&& false !== strpos( $sql, 'SELECT 1' )
					&& isset( $params[1] )
					&& ! isset( $params[2] )
				) {
					return parent::query( 'wptests_posts' === $params[1] ? 'SELECT 1' : 'SELECT 1 WHERE 0 = 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_queries(): array {
				return $this->catalog_queries;
			}
		};
		$pgsql_driver      = new WP_PostgreSQL_Driver( $pgsql_connection, 'wptests' );
		$pgsql_get_type    = Closure::bind(
			function ( string $column ): ?string {
				return $this->get_mysql_table_column_type( 'public', 'wptests_posts', $column );
			},
			$pgsql_driver,
			WP_PostgreSQL_Driver::class
		);
		$pgsql_get_collate = Closure::bind(
			function ( string $column ): ?string {
				return $this->get_mysql_table_column_collation( 'public', 'wptests_posts', $column );
			},
			$pgsql_driver,
			WP_PostgreSQL_Driver::class
		);
		$pgsql_has_columns = Closure::bind(
			function ( string $table ): bool {
				return $this->mysql_table_has_column_metadata( 'public', $table );
			},
			$pgsql_driver,
			WP_PostgreSQL_Driver::class
		);

		$this->assertSame( "enum('draft','published')", $pgsql_get_type( 'status' ) );
		$this->assertSame( 'utf8mb4_unicode_ci', $pgsql_get_collate( 'status' ) );
		$this->assertTrue( $pgsql_has_columns( 'wptests_posts' ) );
		$this->assertFalse( $pgsql_has_columns( 'wptests_missing' ) );

		$catalog_queries = $pgsql_connection->get_catalog_queries();
		$this->assertCount( 2, $catalog_queries );
		foreach ( $catalog_queries as $catalog_query ) {
			$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_namespace pn', $catalog_query['sql'] );
			$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_class pc', $catalog_query['sql'] );
			$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_attribute pa', $catalog_query['sql'] );
			$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $catalog_query['sql'] );
			$this->assertStringContainsString( 'pg_catalog.pg_enum e', $catalog_query['sql'] );
			$this->assertStringContainsString( '__wp_mysql_column_type:', $catalog_query['sql'] );
			if ( false !== strpos( $catalog_query['sql'], ' AS collation_name' ) ) {
				$this->assertStringContainsString( '__wp_mysql_column_collation:', $catalog_query['sql'] );
			}
			$this->assertStringNotContainsString( WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE, $catalog_query['sql'] );
			$this->assertSame( array( 'public', 'wptests_posts', 'status' ), $catalog_query['params'] );
		}
		$this->assertStringContainsString( "LIKE 'enum%'", $catalog_queries[1]['sql'] );
		$this->assertStringContainsString( "LIKE 'set%'", $catalog_queries[1]['sql'] );
	}

	/**
	 * Tests MySQL comments are represented as PostgreSQL catalog comments.
	 */
	public function test_mysql_comments_sync_to_postgresql_catalog_comment_statements(): void {
		$connection           = new class( array( 'pdo' => $this->create_pgsql_reporting_sqlite_pdo() ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( 0 === strpos( $sql, 'COMMENT ON ' ) ) {
					return parent::query( 'SELECT 1 WHERE 0 = 1' );
				}

				return parent::query( $sql, $params );
			}
		};
		$driver               = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$get_index_statements = Closure::bind(
			function (): array {
				return array(
					$this->get_postgresql_catalog_index_comment_statement( 'public', 'wptests_posts', 'post_title', "Index's note" ),
					$this->get_postgresql_catalog_index_comment_statement( 'public', 'wptests_posts', 'post_title', '' ),
					$this->get_postgresql_catalog_index_comment_statement( 'public', 'wptests_posts', 'PRIMARY', 'Primary note' ),
					$this->get_postgresql_catalog_index_comment_statement( 'public', 'wptests_posts', 'post_title', 'Fulltext note', 'FULLTEXT' ),
				);
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);
		$sync_comments        = Closure::bind(
			function (): void {
				$this->sync_postgresql_catalog_table_comment( 'public', 'wptests_posts', "Table's note" );
				$this->sync_postgresql_catalog_column_comment( 'public', 'wptests_posts', 'post_title', "Title's note" );
				$this->sync_postgresql_catalog_column_comment( 'public', 'wptests_posts', 'post_excerpt', '' );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		$sync_comments();

		$this->assertSame(
			array(
				array(
					'sql'    => 'COMMENT ON TABLE "public"."wptests_posts" IS \'Table\'\'s note\'',
					'params' => array(),
				),
				array(
					'sql'    => 'COMMENT ON COLUMN "public"."wptests_posts"."post_title" IS \'Title\'\'s note\'',
					'params' => array(),
				),
				array(
					'sql'    => 'COMMENT ON COLUMN "public"."wptests_posts"."post_excerpt" IS NULL',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertSame(
			array(
				'COMMENT ON INDEX "public"."wptests_posts__post_title" IS \'Index\'\'s note\'',
				'COMMENT ON INDEX "public"."wptests_posts__post_title" IS NULL',
				null,
				"COMMENT ON INDEX \"public\".\"wptests_posts__post_title\" IS E'__wp_mysql_index_type:RlVMTFRFWFQ=\\nFulltext note'",
			),
			$get_index_statements()
		);
	}

	/**
	 * Tests direct information_schema.TABLES AUTO_INCREMENT values match SHOW TABLE STATUS metadata.
	 */
	public function test_direct_information_schema_tables_exposes_auto_increment_values(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_show_table_status_auto_increment_fixture( $driver );
		$pdo = $driver->get_connection()->get_pdo();

		$pdo->exec( 'CREATE TABLE analytics_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, value TEXT)' );
		$pdo->exec( "INSERT INTO analytics_posts (value) VALUES ('a'), ('b')" );
		$pdo->exec(
			"INSERT INTO information_schema.tables
				(table_schema, table_name, table_type)
			VALUES
				('analytics', 'analytics_posts', 'BASE TABLE')"
		);
		$pdo->exec(
			"INSERT INTO information_schema.columns
				(table_schema, table_name, column_name, ordinal_position, data_type, character_maximum_length, collation_name, is_nullable, column_default, is_identity)
			VALUES
				('analytics', 'analytics_posts', 'id', 1, 'bigint', NULL, NULL, 'NO', NULL, 'YES')"
		);

		$tables = $driver->query(
			"SELECT TABLE_NAME, AUTO_INCREMENT
			FROM information_schema.tables
			WHERE table_schema = 'wptests'
				AND table_name IN ('wptests_options', 'wptests_plain', 'wptests_posts')
			ORDER BY table_name"
		);

		$this->assertSame(
			array(
				array( 'wptests_options', '1' ),
				array( 'wptests_plain', null ),
				array( 'wptests_posts', '6' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->TABLE_NAME, $row->AUTO_INCREMENT );
				},
				$tables
			)
		);

		$high_auto_increment = $driver->query(
			"SELECT TABLE_NAME
			FROM information_schema.tables
			WHERE table_schema = 'wptests'
				AND table_type = 'BASE TABLE'
				AND auto_increment > 3"
		);

		$this->assertSame( array( 'wptests_posts' ), array_column( $high_auto_increment, 'TABLE_NAME' ) );

		$without_auto_increment = $driver->query(
			"SELECT TABLE_NAME
			FROM information_schema.tables
			WHERE table_schema = 'wptests'
				AND table_type = 'BASE TABLE'
				AND auto_increment IS NULL"
		);

		$this->assertSame( array( 'wptests_plain' ), array_column( $without_auto_increment, 'TABLE_NAME' ) );

		$schema_qualified_auto_increment = $driver->query(
			"SELECT TABLE_SCHEMA, TABLE_NAME, AUTO_INCREMENT
			FROM information_schema.tables
			WHERE table_schema = 'analytics'
				AND table_name = 'analytics_posts'"
		);

		$this->assertSame( 'analytics', $schema_qualified_auto_increment[0]->TABLE_SCHEMA );
		$this->assertSame( 'analytics_posts', $schema_qualified_auto_increment[0]->TABLE_NAME );
		$this->assertSame( '3', $schema_qualified_auto_increment[0]->AUTO_INCREMENT );
	}

	/**
	 * Tests direct information_schema.TABLES BINARY predicates use exact matching.
	 */
	public function test_direct_information_schema_tables_binary_predicates_use_exact_matching(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$exact = $driver->query(
			"SELECT table_name
			FROM information_schema.tables
			WHERE table_name = BINARY 'wptests_options'"
		);

		$this->assertCount( 1, $exact );
		$this->assertSame( 'wptests_options', $exact[0]->TABLE_NAME );
		$sql = $this->get_logged_postgresql_sql_containing(
			$driver->get_last_postgresql_queries(),
			'"TABLE_NAME" = \'wptests_options\''
		);
		$this->assertStringContainsString( '"TABLE_NAME" = \'wptests_options\'', $sql );
		$this->assertStringNotContainsString( 'BINARY', strtoupper( $sql ) );

		$case_mismatch = $driver->query(
			"SELECT table_name
			FROM information_schema.tables
			WHERE table_name = BINARY 'WPTESTS_OPTIONS'"
		);

		$this->assertSame( array(), $case_mismatch );
		$sql = $this->get_logged_postgresql_sql_containing(
			$driver->get_last_postgresql_queries(),
			'"TABLE_NAME" = \'WPTESTS_OPTIONS\''
		);
		$this->assertStringNotContainsString( 'BINARY', strtoupper( $sql ) );
	}

	/**
	 * Tests direct information_schema schema predicates accept DATABASE() and SCHEMA().
	 */
	public function test_direct_information_schema_current_database_function_predicates_return_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$this->install_direct_information_schema_options_metadata( $driver );

		$cases = array(
			'SELECT schema_name AS name FROM information_schema.schemata WHERE schema_name = DATABASE()' => 'wptests',
			"SELECT table_name AS name FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'wptests_options'" => 'wptests_options',
			"SELECT column_name AS name FROM information_schema.columns AS c WHERE SCHEMA() = c.table_schema AND c.table_name = 'wptests_options' AND c.column_name = 'option_name'" => 'option_name',
			"SELECT index_name AS name FROM information_schema.statistics WHERE index_schema = SCHEMA() AND table_name = 'wptests_options' AND index_name = 'option_name'" => 'option_name',
			"SELECT constraint_name AS name FROM information_schema.table_constraints WHERE constraint_schema = DATABASE() AND table_name = 'wptests_options' AND constraint_name = 'PRIMARY'" => 'PRIMARY',
			"SELECT referenced_table_schema AS name FROM information_schema.key_column_usage WHERE referenced_table_schema = SCHEMA() AND table_name = 'wptests_posts'" => 'wptests',
			"SELECT unique_constraint_schema AS name FROM information_schema.referential_constraints WHERE unique_constraint_schema = DATABASE() AND table_name = 'wptests_posts'" => 'wptests',
			"SELECT constraint_schema AS name FROM information_schema.check_constraints WHERE constraint_schema = SCHEMA() AND constraint_name = 'wptests_posts_status_chk'" => 'wptests',
		);

		foreach ( $cases as $query => $expected_name ) {
			$rows = $driver->query( $query );

			$this->assertCount( 1, $rows, $query );
			$this->assertSame( $expected_name, $rows[0]->name, $query );

			$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertSame( 0, preg_match( '/\b(?:DATABASE|SCHEMA)\s*\(/i', $sql ), $query );
			$this->assertStringContainsString( "'wptests'", $sql, $query );
		}

		try {
			$driver->query( "SELECT table_name FROM information_schema.tables WHERE table_schema = DATABASE('wptests')" );
			$this->fail( 'Expected unsupported information_schema query.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests direct information_schema projections accept DATABASE() and SCHEMA().
	 */
	public function test_direct_information_schema_current_database_function_projections_return_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$explicit = $driver->query(
			"SELECT DATABASE() AS current_database, SCHEMA() AS current_schema, table_name AS table_name
			FROM information_schema.tables
			WHERE table_schema = DATABASE()
				AND table_name = 'wptests_options'"
		);

		$this->assertCount( 1, $explicit );
		$this->assertSame( 'wptests', $explicit[0]->current_database );
		$this->assertSame( 'wptests', $explicit[0]->current_schema );
		$this->assertSame( 'wptests_options', $explicit[0]->table_name );

		$sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertSame( 0, preg_match( '/\b(?:DATABASE|SCHEMA)\s*\(/i', $sql ) );
		$this->assertStringContainsString( "'wptests' AS current_database", $sql );
		$this->assertStringContainsString( "'wptests' AS current_schema", $sql );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$selected_schema = $driver->query(
			'SELECT DATABASE() AS current_database, SCHEMA() AS current_schema, schema_name AS schema_name
			FROM schemata
			WHERE schema_name = DATABASE()'
		);

		$this->assertCount( 1, $selected_schema );
		$this->assertSame( 'information_schema', $selected_schema[0]->current_database );
		$this->assertSame( 'information_schema', $selected_schema[0]->current_schema );
		$this->assertSame( 'information_schema', $selected_schema[0]->schema_name );

		try {
			$driver->query( "SELECT DATABASE('wptests') AS current_database FROM tables" );
			$this->fail( 'Expected unsupported information_schema query.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests direct information_schema.SCHEMATA SELECTs return MySQL-shaped rows.
	 */
	public function test_direct_information_schema_schemata_selects_return_mysql_shape(): void {
		$driver = $this->create_driver( 'wp_test_new' );

		$schemata = $driver->query( 'SELECT schema_name FROM information_schema.schemata ORDER BY schema_name' );

		$this->assertEquals(
			array(
				(object) array( 'SCHEMA_NAME' => 'information_schema' ),
				(object) array( 'SCHEMA_NAME' => 'wp_test_new' ),
			),
			$schemata
		);

		$aliased = $driver->query( 'SELECT s.schema_name FROM information_schema.schemata AS s WHERE s.schema_name = \'wp_test_new\'' );

		$this->assertEquals( array( (object) array( 'SCHEMA_NAME' => 'wp_test_new' ) ), $aliased );

		$star = $driver->query( 'SELECT * FROM information_schema.schemata WHERE schema_name = \'information_schema\'' );

		$this->assertCount( 1, $star );
		$this->assertSame( 'def', $star[0]->CATALOG_NAME );
		$this->assertSame( 'information_schema', $star[0]->SCHEMA_NAME );
		$this->assertSame( 'utf8mb4', $star[0]->DEFAULT_CHARACTER_SET_NAME );
		$this->assertSame( 'utf8mb4_unicode_ci', $star[0]->DEFAULT_COLLATION_NAME );
		$this->assertNull( $star[0]->SQL_PATH );
		$this->assertSame( 'NO', $star[0]->DEFAULT_ENCRYPTION );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$current_database_schemata = $driver->query( 'SELECT schema_name FROM schemata WHERE schema_name = \'wp_test_new\'' );

		$this->assertEquals( array( (object) array( 'SCHEMA_NAME' => 'wp_test_new' ) ), $current_database_schemata );
	}

	/**
	 * Tests PostgreSQL-backed information_schema.SCHEMATA is a native catalog relation.
	 */
	public function test_direct_information_schema_schemata_uses_postgresql_catalog_relation_for_pgsql_connections(): void {
		$connection = new WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection(
			array(
				'pdo' => $this->create_pgsql_reporting_sqlite_pdo(),
			)
		);
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$get_sql    = Closure::bind(
			function (): string {
				return $this->get_direct_information_schema_relation_sql( 'schemata' );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);
		$sql        = $get_sql();

		$this->assertStringContainsString( 'FROM information_schema.schemata s', $sql );
		$this->assertStringContainsString( 's.schema_name = \'information_schema\'', $sql );
		$this->assertStringContainsString( 'LEFT(s.schema_name, 3) <> \'pg_\'', $sql );
		$this->assertStringContainsString( 'AS "SCHEMA_NAME"', $sql );
		$this->assertStringNotContainsString( 'UNION ALL', $sql );
	}

