	/**
	 * Tests direct information_schema derived SELECT sources return MySQL-shaped rows.
	 */
	public function test_direct_information_schema_derived_selects_return_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$aliased = $driver->query(
			"SELECT d.table_name AS table_name
			FROM (
				SELECT table_name
				FROM information_schema.tables
				WHERE table_schema = 'wptests'
			) AS d
			WHERE d.table_name = 'wptests_options'"
		);

		$this->assertCount( 1, $aliased );
		$this->assertSame( 'wptests_options', $aliased[0]->table_name );

		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'AS "d"' );
		$this->assertStringContainsString( 'AS "d"', $sql );
		$this->assertStringContainsString( '"d"."TABLE_NAME" = \'wptests_options\'', $sql );

		$unaliased = $driver->query(
			"SELECT table_name
			FROM (
				SELECT table_name
				FROM information_schema.tables
				WHERE table_schema = 'wptests'
			)
			WHERE table_name = 'wptests_options'"
		);

		$this->assertCount( 1, $unaliased );
		$this->assertSame( 'wptests_options', $unaliased[0]->TABLE_NAME );
		$this->assertStringContainsString(
			'AS "derived"',
			$this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'AS "derived"' )
		);

		$union = $driver->query(
			"SELECT d.object_name AS object_name
			FROM (
				SELECT table_name AS object_name
				FROM information_schema.tables
				WHERE table_name = 'wptests_options'
				UNION ALL
				SELECT schema_name AS object_name
				FROM information_schema.schemata
				WHERE schema_name = 'wptests'
			) AS d
			WHERE d.object_name LIKE 'wptests%'
			ORDER BY d.object_name"
		);

		$this->assertSame( array( 'wptests', 'wptests_options' ), array_column( $union, 'object_name' ) );
		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'UNION ALL SELECT' );
		$this->assertStringContainsString( 'UNION ALL SELECT', $sql );
		$this->assertStringContainsString( 'AS "d"', $sql );
		$this->assertStringContainsString( '"d"."object_name" LIKE \'wptests%\'', $sql );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$unqualified_union = $driver->query(
			"SELECT object_name
			FROM (
				SELECT table_name AS object_name
				FROM tables
				WHERE table_name = 'wptests_options'
				UNION ALL
				SELECT schema_name AS object_name
				FROM schemata
				WHERE schema_name = 'wptests'
			) AS d
			WHERE object_name LIKE 'wptests%'
			ORDER BY object_name"
		);

		$this->assertSame( array( 'wptests', 'wptests_options' ), array_column( $unqualified_union, 'object_name' ) );

		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$projected_database_join = $driver->query(
			"SELECT d.current_database AS current_database, t.table_name AS table_name
			FROM (
				SELECT DATABASE() AS current_database
				FROM information_schema.schemata
				WHERE schema_name = DATABASE()
			) AS d
			JOIN information_schema.tables AS t ON t.table_schema = d.current_database
			WHERE t.table_name = 'wptests_options'"
		);

		$this->assertSame( array( 'wptests_options' ), array_column( $projected_database_join, 'table_name' ) );
		$this->assertSame( 'wptests', $projected_database_join[0]->current_database );
		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'current_database' );
		$this->assertSame( 0, preg_match( '/\b(?:DATABASE|SCHEMA)\s*\(/i', $sql ) );
		$this->assertStringContainsString( "'wptests' AS current_database", $sql );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$use_information_schema_join = $driver->query(
			'SELECT d.current_schema AS current_schema, s.schema_name AS schema_name
			FROM (
				SELECT SCHEMA() AS current_schema
				FROM schemata
				WHERE schema_name = DATABASE()
			) AS d
			JOIN schemata AS s ON s.schema_name = d.current_schema'
		);

		$this->assertCount( 1, $use_information_schema_join );
		$this->assertSame( 'information_schema', $use_information_schema_join[0]->current_schema );
		$this->assertSame( 'information_schema', $use_information_schema_join[0]->schema_name );
		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'current_schema' );
		$this->assertSame( 0, preg_match( '/\b(?:DATABASE|SCHEMA)\s*\(/i', $sql ) );
		$this->assertStringContainsString( "'information_schema' AS current_schema", $sql );

		try {
			$driver->query(
				'SELECT d.object_name
				FROM (
					SELECT table_name AS object_name, table_schema
					FROM tables
					UNION ALL
					SELECT schema_name AS object_name
					FROM schemata
				) AS d'
			);
			$this->fail( 'Expected unsupported mismatched derived information_schema UNION to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertStringNotContainsString(
				'SELECT d.object_name',
				implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) )
			);
		}
	}

	/**
	 * Tests direct information_schema scalar subqueries route without a top-level FROM.
	 */
	public function test_direct_information_schema_scalar_subqueries_route_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$rows = $driver->query(
			"SELECT
				(SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE()) AS table_count,
				(SELECT table_name FROM information_schema.tables WHERE table_name = 'wptests_options') AS option_table"
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( '3', $rows[0]->table_count );
		$this->assertSame( 'wptests_options', $rows[0]->option_table );

		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'AS "tables"' );
		$this->assertStringContainsString( 'AS "tables"', $sql );
		$this->assertStringNotContainsString( 'information_schema.tables', $sql );
		$this->assertSame( 0, preg_match( '/\bDATABASE\s*\(/i', $sql ) );

		$projected = $driver->query(
			"SELECT t.table_name,
				(SELECT COUNT(*) FROM information_schema.columns WHERE table_name = 'wptests_options') AS column_count
			FROM information_schema.tables AS t
			WHERE t.table_name = 'wptests_options'"
		);

		$this->assertCount( 1, $projected );
		$this->assertSame( 'wptests_options', $projected[0]->TABLE_NAME );
		$this->assertSame( '4', $projected[0]->column_count );

		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'AS "columns"' );
		$this->assertStringContainsString( 'AS "columns"', $sql );
		$this->assertStringContainsString( 'AS "t"', $sql );
	}

