	/**
	 * Tests simple DML can read supported information_schema subqueries in predicates.
	 */
	public function test_simple_dml_information_schema_subquery_predicates_route_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );
		$driver->query(
			'CREATE TABLE wptests_options (
				option_name TEXT NOT NULL,
				option_value TEXT NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_options (option_name, option_value)
			VALUES ('wptests_options', 'before'), ('other', 'before')"
		);

		$this->assertSame(
			1,
			$driver->query(
				"UPDATE wptests_options
				SET option_value = 'updated'
				WHERE option_name IN (
					SELECT table_name FROM information_schema.tables WHERE table_name = 'wptests_options'
				)"
			)
		);

		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'UPDATE "wptests_options"' );
		$this->assertStringContainsString( 'AS "tables"', $sql );
		$this->assertStringNotContainsString( 'information_schema.tables', $sql );

		$rows = $driver->query( 'SELECT option_name, option_value FROM wptests_options ORDER BY option_name' );
		$this->assertSame(
			array(
				array(
					'option_name'  => 'other',
					'option_value' => 'before',
				),
				array(
					'option_name'  => 'wptests_options',
					'option_value' => 'updated',
				),
			),
			array_map(
				static function ( $row ): array {
					return array(
						'option_name'  => $row->option_name,
						'option_value' => $row->option_value,
					);
				},
				$rows
			)
		);

		$this->assertSame(
			1,
			$driver->query(
				"DELETE FROM wptests_options
				WHERE option_name IN (
					SELECT table_name FROM information_schema.tables WHERE table_name = 'wptests_options'
				)"
			)
		);

		$sql = $this->get_logged_postgresql_sql_containing( $driver->get_last_postgresql_queries(), 'DELETE FROM "wptests_options"' );
		$this->assertStringContainsString( 'AS "tables"', $sql );
		$this->assertStringNotContainsString( 'information_schema.tables', $sql );

		$rows = $driver->query( 'SELECT option_name, option_value FROM wptests_options' );
		$this->assertSame( 1, count( $rows ) );
		$this->assertSame( 'other', $rows[0]->option_name );
		$this->assertSame( 'before', $rows[0]->option_value );
	}

	/**
	 * Tests unsupported simple DML subquery predicates fail before backend execution.
	 */
	public function test_simple_dml_subquery_predicates_fail_closed(): void {
		$queries = array(
			'UPDATE wptests_options SET option_value = "updated" WHERE option_name IN (
				SELECT option_name FROM wptests_options
			)' => 'Unsupported UPDATE statement.',
			'DELETE FROM wptests_options WHERE option_name IN (
				SELECT option_name FROM wptests_options
			)' => 'Unsupported DELETE statement.',
		);

		foreach ( $queries as $query => $expected_message ) {
			$driver = $this->create_driver();
			$driver->query(
				'CREATE TABLE wptests_options (
					option_name TEXT NOT NULL,
					option_value TEXT NOT NULL
				)'
			);
			$driver->query( "INSERT INTO wptests_options (option_name, option_value) VALUES ('wptests_options', 'before')" );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported simple DML subquery to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $expected_message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests direct information_schema SELECTs can join one application table source.
	 */
	public function test_direct_information_schema_mixed_application_table_join_returns_mysql_shape(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query(
			'CREATE TABLE wptests_schema_names (
				id INTEGER NOT NULL,
				db_name TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE wptests_schema_names (
				id int(11) NOT NULL,
				db_name varchar(191) NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_schema_names (id, db_name)
			VALUES (1, 'other'), (2, 'wptests')"
		);

		$result = $driver->query(
			"SELECT sub.id, sub.table_schema, sub.table_name, sub.column_name
			FROM (
				SELECT *
				FROM information_schema.columns AS c
				JOIN wptests_schema_names AS app
					ON app.db_name = CONCAT(COALESCE(c.table_schema, 'default'), '')
				JOIN information_schema.schemata AS s
					ON s.schema_name = c.table_schema
				WHERE c.table_name = 'wptests_schema_names'
			) AS sub
			ORDER BY ordinal_position"
		);

		$this->assertSame(
			array(
				array( '2', 'wptests', 'wptests_schema_names', 'id' ),
				array( '2', 'wptests', 'wptests_schema_names', 'db_name' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->TABLE_SCHEMA, $row->TABLE_NAME, $row->COLUMN_NAME );
				},
				$result
			)
		);

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( '"wptests_schema_names" AS "app"', $sql );
		$this->assertStringContainsString( '"app"."db_name" = CONCAT', $sql );
		$this->assertStringContainsString( 'COALESCE ( "c"."TABLE_SCHEMA" , \'default\')', $sql );
	}

	/**
	 * Tests PostgreSQL-backed information_schema joins read application columns from catalogs.
	 */
	public function test_direct_information_schema_mixed_application_table_join_uses_postgresql_catalog_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured catalog column metadata queries.
			 *
			 * @var array[]
			 */
			private $column_catalog_queries = array();

			/**
			 * Execute fixture-backed catalog metadata queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if (
					false !== strpos( $sql, 'FROM information_schema.columns c' )
					&& false !== strpos( $sql, 'ORDER BY c.ordinal_position' )
				) {
					$this->column_catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						"SELECT 'id' AS column_name, 1 AS ordinal_position, 'int(11)' AS column_type, 'NO' AS is_nullable, NULL AS column_default, '' AS extra
						UNION ALL
						SELECT 'db_name', 2, 'varchar(191)', 'NO', NULL, ''"
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured catalog column metadata queries.
			 *
			 * @return array[] Queries.
			 */
			public function get_column_catalog_queries(): array {
				return $this->column_catalog_queries;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$sql        = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_direct_information_schema_select_query',
			"SELECT app.id, c.table_schema, c.table_name, c.column_name
			FROM information_schema.columns AS c
			JOIN wptests_schema_names AS app
				ON app.db_name = c.table_schema
			WHERE c.table_name = 'wptests_schema_names'"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( '"wptests_schema_names" AS "app"', $sql );
		$this->assertStringContainsString( '"app"."db_name" = "c"."TABLE_SCHEMA"', $sql );
		$this->assertStringNotContainsString( 'FROM "' . WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE . '"', $sql );
		$this->assertStringNotContainsString( 'JOIN "' . WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE . '"', $sql );

		$this->assertCount( 1, $connection->get_column_catalog_queries() );
		$column_catalog_query = $connection->get_column_catalog_queries()[0];
		$this->assertSame( array( 'public', 'wptests_schema_names' ), $column_catalog_query['params'] );
		$this->assertStringContainsString( 'FROM information_schema.columns c', $column_catalog_query['sql'] );
		$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $column_catalog_query['sql'] );
		$this->assertStringNotContainsString( WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE, $column_catalog_query['sql'] );
	}

