		$this->assertStringContainsString(
			'COMMENT ON COLUMN "public"."catalog_pg_generated_defaults"."col2" IS \'' . $prefix . 'REFURV9BREQoTk9XKCksIElOVEVSVkFMIDEgWUVBUik=\'',
