			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Execute fixture-backed CREATE TABLE and metadata queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( 0 === strpos( $sql, 'CREATE TABLE "catalog_json_check" ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if ( 0 === strpos( $sql, 'DO ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if ( 0 === strpos( $sql, 'COMMENT ON ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if (
						false !== strpos( $sql, WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
					throw new RuntimeException( 'Hidden CHECK metadata table access was not expected for catalog-backed JSON CHECK.' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns' ) && false !== strpos( $sql, 'current_schema()' ) ) {
					$table_name  = str_replace( '"', '""', (string) ( $params[0] ?? '' ) );
					$column_name = (string) ( $params[1] ?? '' );
					$columns     = parent::query( sprintf( 'PRAGMA table_info("%s")', $table_name ) )->fetchAll( PDO::FETCH_ASSOC );
					foreach ( $columns as $column ) {
						if ( (string) ( $column['name'] ?? '' ) === $column_name ) {
							return parent::query( 'SELECT 1' );
						}
					}

					return parent::query( 'SELECT 0' );
				}

				return parent::query( $sql, $params );
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$this->install_information_schema_fixture( $driver );

		$this->assertSame(
			0,
			$driver->query( 'CREATE TABLE catalog_json_check (data JSON CHECK (json_valid(data)))' )
		);

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertContains(
			'COMMENT ON CONSTRAINT "catalog_json_check_chk_1" ON "public"."catalog_json_check" IS \'__wp_mysql_check_clause:json_valid(data)\'',
			$sql
		);

		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests CREATE TABLE ... AS SELECT is translated and stores MySQL-facing metadata.
	 */
	public function test_create_table_as_select_translates_and_stores_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_source (`id` INTEGER, `name` TEXT)' );
		$driver->query( "INSERT INTO ctas_source (`id`, `name`) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE TABLE ctas_copy AS SELECT `id`, `name` FROM `ctas_source` WHERE `id` > 1' )
		);
		$this->assertSame(
			'CREATE TABLE "ctas_copy" AS SELECT "id", "name" FROM "ctas_source" WHERE "id" > 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM ctas_copy' );
		$this->assertEquals(
			array(
				(object) array(
					'id'   => '2',
					'name' => 'two',
				),
			),
			$rows
		);

		$columns = $driver->query( 'SHOW COLUMNS FROM ctas_copy' );
		$this->assertSame( 'id', $columns[0]->Field );
		$this->assertSame( 'int', $columns[0]->Type );
		$this->assertSame( 'name', $columns[1]->Field );
		$this->assertSame( 'text', $columns[1]->Type );

		$this->assertSame(
			array(
				array(
					'column_name'        => 'id',
					'column_type'        => 'int',
					'character_set_name' => null,
					'collation_name'     => null,
					'is_nullable'        => 'YES',
					'column_default'     => null,
					'extra'              => '',
				),
				array(
					'column_name'        => 'name',
					'column_type'        => 'text',
					'character_set_name' => 'utf8mb4',
					'collation_name'     => 'utf8mb4_unicode_ci',
					'is_nullable'        => 'YES',
					'column_default'     => null,
					'extra'              => '',
				),
			),
			$this->get_mysql_column_metadata_rows( $driver, 'ctas_copy' )
		);
	}

	/**
	 * Tests PostgreSQL-backed CREATE TABLE ... AS SELECT uses catalogs without metadata tables.
	 */
	public function test_create_table_as_select_uses_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Catalog checks for existing metadata side tables.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed CTAS.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$column_name = strtolower( (string) ( $params[2] ?? '' ) );
					if ( false !== strpos( $sql, 'AS collation_name' ) ) {
						return parent::query(
							'SELECT ? AS collation_name',
							array( 'name' === $column_name ? 'utf8mb4_unicode_ci' : null )
						);
					}

					return parent::query(
						'SELECT ? AS column_type',
						array( 'id' === $column_name ? 'int' : 'text' )
					);
				}

				if ( 0 === strpos( $sql, 'COMMENT ON TABLE ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$pdo->exec( "ATTACH DATABASE ':memory:' AS public" );
		$pdo->exec( 'CREATE TABLE ctas_pg_source (id INTEGER, name TEXT)' );
		$pdo->exec( "INSERT INTO ctas_pg_source (id, name) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( "CREATE TABLE ctas_pg_copy COMMENT = 'Copied table' AS SELECT `id`, `name` FROM `ctas_pg_source` WHERE `id` > 1" )
		);

		$this->assertSame(
			array(
				array(
					'sql'    => 'CREATE TABLE "public"."ctas_pg_copy" AS SELECT "id", "name" FROM "ctas_pg_source" WHERE "id" > 1',
					'params' => array(),
				),
				array(
					'sql'    => 'COMMENT ON TABLE "public"."ctas_pg_copy" IS \'Copied table\'',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( 'SELECT * FROM ctas_pg_copy' );
		$this->assertEquals(
			array(
				(object) array(
					'id'   => '2',
					'name' => 'two',
				),
			),
			$rows
		);

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE TABLE ctas_pg_plain AS SELECT `id` FROM `ctas_pg_source` WHERE `id` = 1' )
		);
		$this->assertSame(
			array(
				array(
					'sql'    => 'CREATE TABLE "public"."ctas_pg_plain" AS SELECT "id" FROM "ctas_pg_source" WHERE "id" = 1',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests CREATE TABLE ... AS SELECT uses the selected PostgreSQL catalog schema.
	 */
	public function test_create_table_as_select_uses_current_postgresql_catalog_schema_after_use(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Catalog checks for existing metadata side tables.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed CTAS.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					return parent::query(
						'plugin_schema' === (string) ( $params[1] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if (
					0 === strpos( $sql, 'CREATE TABLE ' )
					|| 0 === strpos( $sql, 'COMMENT ON TABLE ' )
				) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertSame( 0, $driver->query( 'USE plugin_schema' ) );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( "CREATE TABLE ctas_plugin_copy COMMENT = 'Copied table' AS SELECT 1 AS id" )
		);

		$this->assertSame(
			array(
				array(
					'sql'    => 'CREATE TABLE "plugin_schema"."ctas_plugin_copy" AS SELECT 1 AS id',
					'params' => array(),
				),
				array(
					'sql'    => 'COMMENT ON TABLE "plugin_schema"."ctas_plugin_copy" IS \'Copied table\'',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);
		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
	}

	/**
	 * Tests CREATE TABLE ... SELECT without AS and IF NOT EXISTS are translated.
	 */
	public function test_create_table_select_without_as_and_if_not_exists_translates(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_no_as_source (`id` INTEGER, `name` TEXT)' );
		$driver->query( "INSERT INTO ctas_no_as_source (`id`, `name`) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( "CREATE TABLE IF NOT EXISTS ctas_no_as SELECT `id` FROM `ctas_no_as_source` WHERE `name` = 'one'" )
		);
		$this->assertSame(
			'CREATE TABLE IF NOT EXISTS "ctas_no_as" AS SELECT "id" FROM "ctas_no_as_source" WHERE "name" = \'one\'',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM ctas_no_as' );
		$this->assertEquals( array( (object) array( 'id' => '1' ) ), $rows );
	}

	/**
	 * Tests CREATE TABLE ... SELECT IF NOT EXISTS does not replace existing MySQL metadata.
	 */
	public function test_create_table_select_if_not_exists_preserves_existing_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_if_existing (id INTEGER NOT NULL, name TEXT NOT NULL)' );
		$driver->store_mysql_schema_metadata(
			'CREATE TABLE ctas_if_existing (
				id int NOT NULL,
				name varchar(20) NOT NULL,
				KEY name_key (name)
			)'
		);
		$driver->query( "INSERT INTO ctas_if_existing (id, name) VALUES (1, 'kept')" );
		$driver->query( 'CREATE TABLE ctas_if_source (changed INTEGER NOT NULL)' );
		$driver->query( 'INSERT INTO ctas_if_source (changed) VALUES (2)' );

		$columns_before = $this->get_mysql_column_metadata_rows( $driver, 'ctas_if_existing' );
		$indexes_before = $this->get_mysql_index_metadata_rows( $driver, 'ctas_if_existing' );

		$this->assertSame(
			0,
			$driver->query( 'CREATE TABLE IF NOT EXISTS ctas_if_existing AS SELECT changed FROM ctas_if_source' )
		);

		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( $columns_before, $this->get_mysql_column_metadata_rows( $driver, 'ctas_if_existing' ) );
		$this->assertSame( $indexes_before, $this->get_mysql_index_metadata_rows( $driver, 'ctas_if_existing' ) );

		$rows = $driver->query( 'SELECT id, name FROM ctas_if_existing' );
		$this->assertEquals(
			array(
				(object) array(
					'id'   => '1',
					'name' => 'kept',
				),
			),
			$rows
		);
	}

	/**
	 * Tests CREATE TABLE ... SELECT ignores supported MySQL table options.
	 */
	public function test_create_table_select_ignores_supported_mysql_table_options(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_options_source (`id` INTEGER, `name` TEXT)' );
		$driver->query( "INSERT INTO ctas_options_source (`id`, `name`) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				'CREATE TABLE ctas_with_options
					ENGINE=InnoDB
					DEFAULT CHARSET=utf8mb4
					COLLATE=utf8mb4_unicode_ci
					ROW_FORMAT=DYNAMIC
					STATS_PERSISTENT=DEFAULT
					COMMENT="option copy"
					AS SELECT `id`, `name` FROM `ctas_options_source` WHERE `id` = 2'
			)
		);
		$this->assertSame(
			'CREATE TABLE "ctas_with_options" AS SELECT "id", "name" FROM "ctas_options_source" WHERE "id" = 2',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM ctas_with_options' );
		$this->assertEquals(
			array(
				(object) array(
					'id'   => '2',
					'name' => 'two',
				),
			),
			$rows
		);

		$columns = $driver->query( 'SHOW COLUMNS FROM ctas_with_options' );
		$this->assertSame( array( 'id', 'name' ), array_column( $columns, 'Field' ) );
		$this->assertSame( array( 'int', 'text' ), array_column( $columns, 'Type' ) );

		$create_table = $driver->query( 'SHOW CREATE TABLE ctas_with_options' )[0]->{'Create Table'};
		$this->assertStringEndsWith( "COMMENT='option copy'", $create_table );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				'CREATE TEMPORARY TABLE IF NOT EXISTS ctas_temp_with_options
					DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
					ENGINE InnoDB
					SELECT 7 AS `id`'
			)
		);
		$this->assertSame(
			'CREATE TEMPORARY TABLE IF NOT EXISTS "ctas_temp_with_options" AS SELECT 7 AS "id"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$temp_rows = $driver->query( 'SELECT * FROM ctas_temp_with_options' );
		$this->assertEquals( array( (object) array( 'id' => '7' ) ), $temp_rows );
	}

	/**
	 * Tests CREATE TABLE ... SELECT with explicit definitions creates then inserts.
	 */
	public function test_create_table_select_with_definitions_translates_and_stores_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_defined_source (`id` INTEGER, `name` TEXT, `score` INTEGER)' );
		$driver->query( "INSERT INTO ctas_defined_source (`id`, `name`, `score`) VALUES (1, 'one', 1), (2, 'two', 2)" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				"CREATE TABLE ctas_with_definitions (
					`id` bigint(20) unsigned NOT NULL,
					`name` varchar(20) NOT NULL COMMENT 'Copied name',
					PRIMARY KEY (`id`)
				) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='copy'
				AS SELECT `id`, `name` FROM `ctas_defined_source` WHERE `score` > 1"
			)
		);

		$queries = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertCount( 2, $queries );
		$this->assertStringContainsString( 'CREATE TABLE "ctas_with_definitions"', $queries[0] );
		$this->assertStringContainsString( 'PRIMARY KEY ("id")', $queries[0] );
		$this->assertSame(
			'INSERT INTO "ctas_with_definitions" ("id", "name") SELECT "id", "name" FROM "ctas_defined_source" WHERE "score" > 1',
			$queries[1]
		);

		$rows = $driver->query( 'SELECT id, name FROM ctas_with_definitions' );
		$this->assertEquals(
			array(
				(object) array(
					'id'   => '2',
					'name' => 'two',
				),
			),
			$rows
		);

		$columns = $driver->query( 'SHOW COLUMNS FROM ctas_with_definitions' );
		$this->assertSame( array( 'id', 'name' ), array_column( $columns, 'Field' ) );
		$this->assertSame( array( 'bigint(20) unsigned', 'varchar(20)' ), array_column( $columns, 'Type' ) );
		$this->assertSame( array( 'NO', 'NO' ), array_column( $columns, 'Null' ) );
		$this->assertSame( 'PRI', $columns[0]->Key );

		$create_table = $driver->query( 'SHOW CREATE TABLE ctas_with_definitions' )[0]->{'Create Table'};
		$this->assertStringContainsString( '`id` bigint(20) unsigned NOT NULL', $create_table );
		$this->assertStringContainsString( "`name` varchar(20) NOT NULL COMMENT 'Copied name'", $create_table );
		$this->assertStringContainsString( 'PRIMARY KEY (`id`)', $create_table );
		$this->assertStringEndsWith( "COMMENT='copy'", $create_table );
	}

