					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed CTAS definitions.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT
							'id' AS column_name,
							'bigint(20) unsigned' AS column_type
						UNION ALL
						SELECT
							'name' AS column_name,
							'varchar(20)' AS column_type"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					return parent::query(
						"SELECT
							'PRIMARY' AS key_name,
							1 AS index_ordinal,
							1 AS seq_in_index,
							'id' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_constraint con' ) ) {
					return parent::query( 'SELECT NULL AS constraint_name WHERE 0 = 1' );
				}

				if ( 0 === strpos( $sql, 'COMMENT ON ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if ( 0 === strpos( $sql, 'DO ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if (
					0 === strpos( $sql, 'CREATE TABLE "public"."ctas_pg_defined"' )
					|| 0 === strpos( $sql, 'INSERT INTO "public"."ctas_pg_defined"' )
				) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$pdo->exec( "ATTACH DATABASE ':memory:' AS public" );
		$pdo->exec( 'CREATE TABLE ctas_pg_defined_source (id INTEGER, name TEXT, score INTEGER)' );
		$pdo->exec( "INSERT INTO ctas_pg_defined_source (id, name, score) VALUES (1, 'one', 1), (2, 'two', 2)" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				"CREATE TABLE ctas_pg_defined (
					id bigint(20) unsigned NOT NULL,
					name varchar(20) NOT NULL COMMENT 'Copied name',
					PRIMARY KEY (id)
				) COMMENT='copy'
				AS SELECT id, name FROM ctas_pg_defined_source WHERE score > 1"
			)
		);

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertStringContainsString( 'CREATE TABLE "ctas_pg_defined"', $sql[0] );
		$this->assertContains(
			'INSERT INTO "public"."ctas_pg_defined" ("id", "name") SELECT id, name FROM ctas_pg_defined_source WHERE score > 1',
			$sql
		);
		$this->assertContains( 'COMMENT ON TABLE "public"."ctas_pg_defined" IS \'copy\'', $sql );
		$this->assertContains( 'COMMENT ON COLUMN "public"."ctas_pg_defined"."name" IS \'Copied name\'', $sql );
		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests PostgreSQL-backed temporary CTAS with definitions uses catalogs.
	 */
	public function test_create_temporary_table_select_with_definitions_uses_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured temporary-schema checks.
			 *
			 * @var array[]
			 */
			private $temporary_schema_checks = array();

			/**
			 * Captured metadata-table catalog checks.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed temporary catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed temporary CTAS definitions.' );
					}
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					$this->temporary_schema_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						'ctas_pg_temp_defined' === (string) ( $params[0] ?? '' )
							? "SELECT 'pg_temp_5' AS nspname"
							: 'SELECT NULL AS nspname WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT
							'id' AS column_name,
							'int' AS column_type
						UNION ALL
						SELECT
							'name' AS column_name,
							'varchar(20)' AS column_type"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					return parent::query(
						"SELECT
							'PRIMARY' AS key_name,
							1 AS index_ordinal,
							1 AS seq_in_index,
							'id' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_constraint con' ) ) {
					return parent::query( 'SELECT NULL AS constraint_name WHERE 0 = 1' );
				}

				if ( 0 === strpos( $sql, 'COMMENT ON ' ) || 0 === strpos( $sql, 'DO ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				if (
					0 === strpos( $sql, 'CREATE TEMPORARY TABLE "ctas_pg_temp_defined"' )
					|| 0 === strpos( $sql, 'INSERT INTO "ctas_pg_temp_defined"' )
				) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured temporary-schema checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_temporary_schema_checks(): array {
				return $this->temporary_schema_checks;
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				"CREATE TEMPORARY TABLE ctas_pg_temp_defined (
					id int NOT NULL,
					name varchar(20) NOT NULL COMMENT 'Copied name',
					PRIMARY KEY (id)
				) COMMENT='copy'
				AS SELECT 2 AS id, 'two' AS name"
			)
		);

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "ctas_pg_temp_defined"', $sql[0] );
		$this->assertContains(
			'INSERT INTO "ctas_pg_temp_defined" ("id", "name") SELECT 2 AS id, \'two\' AS name',
			$sql
		);
		$this->assertContains( 'COMMENT ON TABLE "pg_temp_5"."ctas_pg_temp_defined" IS \'copy\'', $sql );
		$this->assertContains( 'COMMENT ON COLUMN "pg_temp_5"."ctas_pg_temp_defined"."name" IS \'Copied name\'', $sql );
		$this->assertNotEmpty( $connection->get_temporary_schema_checks() );
		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests CREATE TABLE ... SELECT accepts main database-qualified targets.
	 */
	public function test_create_table_select_main_database_qualified_target_translates(): void {
		$driver = $this->create_driver( 'wp' );
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_qualified_source (id INTEGER, name TEXT)' );
		$driver->query( "INSERT INTO ctas_qualified_source (id, name) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( "CREATE TABLE wp.ctas_qualified_copy AS SELECT id FROM ctas_qualified_source WHERE name = 'two'" )
		);
		$this->assertSame(
			'CREATE TABLE "ctas_qualified_copy" AS SELECT id FROM ctas_qualified_source WHERE name = \'two\'',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM wp.ctas_qualified_copy' );
		$this->assertEquals( array( (object) array( 'id' => '2' ) ), $rows );
	}

	/**
	 * Tests CREATE TEMPORARY TABLE ... SELECT is translated and stores temporary metadata.
	 */
	public function test_create_temporary_table_select_translates_and_stores_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_temp_source (`id` INTEGER, `name` TEXT)' );
		$driver->query( "INSERT INTO ctas_temp_source (`id`, `name`) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE TEMPORARY TABLE ctas_temp SELECT `name` FROM `ctas_temp_source` WHERE `id` = 2' )
		);
		$this->assertSame(
			'CREATE TEMPORARY TABLE "ctas_temp" AS SELECT "name" FROM "ctas_temp_source" WHERE "id" = 2',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM ctas_temp' );
		$this->assertEquals( array( (object) array( 'name' => 'two' ) ), $rows );

		$columns = $driver->query( 'SHOW COLUMNS FROM ctas_temp' );
		$this->assertSame( 'name', $columns[0]->Field );
		$this->assertSame( 'text', $columns[0]->Type );

		$this->assertSame(
			array(
				array(
					'column_name'        => 'name',
					'column_type'        => 'text',
					'character_set_name' => 'utf8mb4',
					'collation_name'     => 'utf8mb4_unicode_ci',
					'is_nullable'        => 'YES',
					'column_default'     => null,
					'extra'              => '',
				),
			),
			$this->get_mysql_column_metadata_rows( $driver, 'ctas_temp', 'temp' )
		);
	}

	/**
	 * Tests CREATE TABLE ... AS (SELECT ...) parenthesized SELECT forms are translated.
	 */
	public function test_create_table_parenthesized_select_translates(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query( 'CREATE TABLE ctas_parenthesized_source (`id` INTEGER, `label` TEXT)' );
		$driver->query( "INSERT INTO ctas_parenthesized_source (`id`, `label`) VALUES (1, 'name')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE TABLE ctas_parenthesized AS (SELECT `id`, `label` FROM `ctas_parenthesized_source`)' )
		);
		$this->assertSame(
			'CREATE TABLE "ctas_parenthesized" AS SELECT "id", "label" FROM "ctas_parenthesized_source"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT * FROM ctas_parenthesized' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'label' => 'name',
				),
			),
			$rows
		);

		$columns = $driver->query( 'SHOW COLUMNS FROM ctas_parenthesized' );
		$this->assertSame( 'id', $columns[0]->Field );
		$this->assertSame( 'int', $columns[0]->Type );
		$this->assertSame( 'label', $columns[1]->Field );
		$this->assertSame( 'text', $columns[1]->Type );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE TEMPORARY TABLE ctas_parenthesized_temp (SELECT 2 AS `id`)' )
		);
		$this->assertSame(
			'CREATE TEMPORARY TABLE "ctas_parenthesized_temp" AS SELECT 2 AS "id"',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests CREATE TABLE ... LIKE copies source structure and MySQL-facing metadata.
	 */
	public function test_create_table_like_translates_and_copies_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query(
			"CREATE TABLE like_source (
				id int NOT NULL,
				slug varchar(20) NOT NULL DEFAULT 'untitled',
				score int NOT NULL DEFAULT 3,
				note longtext DEFAULT NULL,
				PRIMARY KEY (id),
				UNIQUE KEY slug_unique (slug),
				KEY score_key (score),
				CONSTRAINT score_positive CHECK (score >= 0)
			) COMMENT='template'"
		);
		$driver->query( "INSERT INTO like_source (id, slug, score, note) VALUES (1, 'existing', 4, 'source row')" );

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TABLE like_copy LIKE like_source' ) );
		$logged_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'CREATE TABLE "like_copy"', $logged_sql );
		$this->assertStringNotContainsString( ' LIKE ', strtoupper( $logged_sql ) );

		$count = $driver->query( 'SELECT COUNT(*) AS row_count FROM like_copy' );
		$this->assertSame( '0', $count[0]->row_count );

		$this->assertSame(
			$this->get_mysql_column_metadata_rows( $driver, 'like_source' ),
			$this->get_mysql_column_metadata_rows( $driver, 'like_copy' )
		);
		$this->assertSame(
			$this->get_mysql_index_metadata_rows( $driver, 'like_source' ),
			$this->get_mysql_index_metadata_rows( $driver, 'like_copy' )
		);
		$this->assertSame(
			$this->get_mysql_check_metadata_rows( $driver, 'like_source' ),
			$this->get_mysql_check_metadata_rows( $driver, 'like_copy' )
		);

		$create_table = $driver->query( 'SHOW CREATE TABLE like_copy' )[0]->{'Create Table'};
		$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $create_table );
		$this->assertStringContainsString( 'KEY `score_key` (`score`)', $create_table );
		$this->assertStringContainsString( 'CONSTRAINT `score_positive` CHECK (score >= 0)', $create_table );

		$this->assertSame( 1, $driver->query( "INSERT INTO like_copy (id, slug, score) VALUES (1, 'copy', 5)" ) );

		try {
			$driver->query( "INSERT INTO like_copy (id, slug, score) VALUES (2, 'copy', 6)" );
			$this->fail( 'Expected copied UNIQUE KEY to be enforced.' );
		} catch ( PDOException $e ) {
			$this->assertNotSame( '', $e->getMessage() );
		}

		try {
			$driver->query( "INSERT INTO like_copy (id, slug, score) VALUES (3, 'negative', -1)" );
			$this->fail( 'Expected copied CHECK constraint to be enforced.' );
		} catch ( PDOException $e ) {
			$this->assertNotSame( '', $e->getMessage() );
		}
	}

	/**
	 * Tests PostgreSQL-backed CREATE TABLE ... LIKE syncs catalog comments without metadata tables.
	 */
	public function test_create_table_like_uses_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Catalog checks for existing metadata side tables.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed CREATE LIKE.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT
							'id' AS column_name,
							1 AS ordinal_position,
							'int' AS column_type,
							NULL AS character_set_name,
							NULL AS collation_name,
							'NO' AS is_nullable,
							NULL AS column_default,
							'' AS extra,
							'' AS column_comment
						UNION ALL
						SELECT
							'title' AS column_name,
							2 AS ordinal_position,
							'varchar(191)' AS column_type,
							'utf8mb4' AS character_set_name,
							'utf8mb4_unicode_ci' AS collation_name,
							'NO' AS is_nullable,
							'' AS column_default,
							'' AS extra,
							'Title note' AS column_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					return parent::query(
						"SELECT
							'PRIMARY' AS key_name,
							1 AS index_ordinal,
							1 AS seq_in_index,
							'id' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment
						UNION ALL
						SELECT
							'title_lookup' AS key_name,
							2 AS index_ordinal,
							1 AS seq_in_index,
							'title' AS column_name,
							'1' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'Title lookup note' AS index_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_constraint con' ) ) {
					return parent::query( 'SELECT NULL AS constraint_name WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'pg_catalog.obj_description(t.oid, \'pg_class\')' ) ) {
					return parent::query(
						"SELECT '__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=\nTemplate note' AS table_comment"
					);
				}

				if (
					0 === strpos( $sql, 'COMMENT ON TABLE ' )
					|| 0 === strpos( $sql, 'COMMENT ON COLUMN ' )
					|| 0 === strpos( $sql, 'COMMENT ON INDEX ' )
				) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TABLE like_pg_copy LIKE like_pg_source' ) );

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertStringContainsString( 'CREATE TABLE "like_pg_copy"', $sql[0] );
		$this->assertContains( 'CREATE INDEX "like_pg_copy__title_lookup" ON "like_pg_copy" ("title")', $sql );
		$all_sql = implode( "\n", $sql );
		$this->assertStringContainsString( 'COMMENT ON TABLE "public"."like_pg_copy" IS ', $all_sql );
		$this->assertStringContainsString( '__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=', $all_sql );
		$this->assertStringContainsString( 'Template note', $all_sql );
			$this->assertStringContainsString( 'COMMENT ON COLUMN "public"."like_pg_copy"."title" IS ', $all_sql );
			$this->assertStringContainsString( 'Title note', $all_sql );
		$this->assertContains( 'COMMENT ON INDEX "public"."like_pg_copy__title_lookup" IS \'Title lookup note\'', $sql );
		$this->assertStringNotContainsString( WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE, $all_sql );

		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests PostgreSQL-backed temporary CREATE TABLE ... LIKE uses catalogs without metadata tables.
	 */
	public function test_create_temporary_table_like_uses_postgresql_catalog_without_metadata_for_pgsql_connections(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured temporary-schema checks.
			 *
			 * @var array[]
			 */
			private $temporary_schema_checks = array();

			/**
			 * Catalog checks for existing metadata side tables.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog and temporary CREATE LIKE queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed temporary CREATE LIKE.' );
					}
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					$this->temporary_schema_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						'like_temp_pg_copy' === (string) ( $params[0] ?? '' )
							? "SELECT 'pg_temp_5' AS nspname"
							: 'SELECT NULL AS nspname WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT
							'id' AS column_name,
							1 AS ordinal_position,
							'int' AS column_type,
							NULL AS character_set_name,
							NULL AS collation_name,
							'NO' AS is_nullable,
							NULL AS column_default,
							'' AS extra,
							'' AS column_comment
						UNION ALL
						SELECT
							'slug' AS column_name,
							2 AS ordinal_position,
							'varchar(191)' AS column_type,
							'utf8mb4' AS character_set_name,
							'utf8mb4_unicode_ci' AS collation_name,
							'NO' AS is_nullable,
							'' AS column_default,
							'' AS extra,
							'' AS column_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					return parent::query(
						"SELECT
							'PRIMARY' AS key_name,
							1 AS index_ordinal,
							1 AS seq_in_index,
							'id' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment
						UNION ALL
						SELECT
							'slug_lookup' AS key_name,
							2 AS index_ordinal,
							1 AS seq_in_index,
							'slug' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_constraint con' ) ) {
					return parent::query( 'SELECT NULL AS constraint_name WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'pg_catalog.obj_description(t.oid, \'pg_class\')' ) ) {
					return parent::query( "SELECT '' AS table_comment" );
				}

				if ( 0 === strpos( $sql, 'COMMENT ON ' ) ) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured temporary-schema checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_temporary_schema_checks(): array {
				return $this->temporary_schema_checks;
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TEMPORARY TABLE like_temp_pg_copy LIKE like_temp_pg_source' ) );

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "like_temp_pg_copy"', $sql[0] );
		$this->assertContains( 'CREATE UNIQUE INDEX "like_temp_pg_copy__slug_lookup" ON "like_temp_pg_copy" ("slug")', $sql );
		$this->assertNotEmpty( $connection->get_temporary_schema_checks() );
		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
		$this->assertSame(
			array(),
			$pdo->query( "SELECT name FROM sqlite_master WHERE name LIKE '__wp_postgresql_mysql_%' ORDER BY name" )->fetchAll( PDO::FETCH_COLUMN )
		);
	}

	/**
	 * Tests CREATE TABLE ... LIKE uses the selected PostgreSQL catalog schema.
	 */
	public function test_create_table_like_uses_current_postgresql_catalog_schema_after_use(): void {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Catalog checks for existing metadata side tables.
			 *
			 * @var array[]
			 */
			private $metadata_table_catalog_checks = array();

			/**
			 * Execute fixture-backed catalog/comment queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
					) as $metadata_table
				) {
					if (
						false !== strpos( $sql, $metadata_table )
						&& false === strpos( $sql, 'pg_catalog.pg_class c' )
					) {
						throw new RuntimeException( 'Hidden metadata table mutation was not expected for catalog-backed CREATE LIKE.' );
					}
				}

				if ( false !== strpos( $sql, 'FROM information_schema.schemata s' ) ) {
					return parent::query(
						'plugin_schema' === (string) ( $params[1] ?? '' )
							? 'SELECT 1'
							: 'SELECT 1 WHERE 0 = 1'
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'c.relname IN' ) ) {
					$this->metadata_table_catalog_checks[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query( 'SELECT NULL AS relname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class c' ) && false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT
							'id' AS column_name,
							1 AS ordinal_position,
							'int' AS column_type,
							NULL AS character_set_name,
							NULL AS collation_name,
							'NO' AS is_nullable,
							NULL AS column_default,
							'' AS extra,
							'' AS column_comment
						UNION ALL
						SELECT
							'title' AS column_name,
							2 AS ordinal_position,
							'varchar(191)' AS column_type,
							'utf8mb4' AS character_set_name,
							'utf8mb4_unicode_ci' AS collation_name,
							'NO' AS is_nullable,
							'' AS column_default,
							'' AS extra,
							'Title note' AS column_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_class t' ) && false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					return parent::query(
						"SELECT
							'PRIMARY' AS key_name,
							1 AS index_ordinal,
							1 AS seq_in_index,
							'id' AS column_name,
							'0' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'' AS index_comment
						UNION ALL
						SELECT
							'title_lookup' AS key_name,
							2 AS index_ordinal,
							1 AS seq_in_index,
							'title' AS column_name,
							'1' AS non_unique,
							'BTREE' AS index_type,
							'A' AS collation,
							NULL AS sub_part,
							'Title lookup note' AS index_comment"
					);
				}

				if ( false !== strpos( $sql, 'FROM pg_catalog.pg_constraint con' ) ) {
					return parent::query( 'SELECT NULL AS constraint_name WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'pg_catalog.obj_description(t.oid, \'pg_class\')' ) ) {
					return parent::query( "SELECT 'Template note' AS table_comment" );
				}

				if (
					0 === strpos( $sql, 'CREATE TABLE ' )
					|| 0 === strpos( $sql, 'CREATE INDEX ' )
					|| 0 === strpos( $sql, 'COMMENT ON TABLE ' )
					|| 0 === strpos( $sql, 'COMMENT ON COLUMN ' )
					|| 0 === strpos( $sql, 'COMMENT ON INDEX ' )
				) {
					return parent::query( 'SELECT 1' );
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured metadata-table catalog checks.
			 *
			 * @return array[] Catalog checks.
			 */
			public function get_metadata_table_catalog_checks(): array {
				return $this->metadata_table_catalog_checks;
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertSame( 0, $driver->query( 'USE plugin_schema' ) );

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TABLE like_plugin_copy LIKE like_plugin_source' ) );

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertStringContainsString( 'CREATE TABLE "plugin_schema"."like_plugin_copy"', $sql[0] );
		$this->assertContains( 'CREATE INDEX "plugin_schema"."like_plugin_copy__title_lookup" ON "plugin_schema"."like_plugin_copy" ("title")', $sql );
		$this->assertContains( 'COMMENT ON TABLE "plugin_schema"."like_plugin_copy" IS \'Template note\'', $sql );
		$this->assertContains( 'COMMENT ON COLUMN "plugin_schema"."like_plugin_copy"."title" IS \'Title note\'', $sql );
		$this->assertContains( 'COMMENT ON INDEX "plugin_schema"."like_plugin_copy__title_lookup" IS \'Title lookup note\'', $sql );
		$this->assertStringNotContainsString( WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE, implode( "\n", $sql ) );
		$this->assertCount( 0, $connection->get_metadata_table_catalog_checks() );
	}

	/**
	 * Tests parenthesized CREATE TABLE ... LIKE copies source metadata.
	 */
	public function test_create_table_parenthesized_like_translates_and_copies_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query(
			"CREATE TABLE like_parenthesized_source (
				id int NOT NULL,
				slug varchar(20) NOT NULL DEFAULT 'untitled',
				PRIMARY KEY (id),
				KEY slug_key (slug)
			) COMMENT='template'"
		);

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TABLE like_parenthesized_copy (LIKE like_parenthesized_source)' ) );
		$logged_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'CREATE TABLE "like_parenthesized_copy"', $logged_sql );
		$this->assertStringNotContainsString( ' LIKE ', strtoupper( $logged_sql ) );

		$this->assertSame(
			$this->get_mysql_column_metadata_rows( $driver, 'like_parenthesized_source' ),
			$this->get_mysql_column_metadata_rows( $driver, 'like_parenthesized_copy' )
		);
		$this->assertSame(
			$this->get_mysql_index_metadata_rows( $driver, 'like_parenthesized_source' ),
			$this->get_mysql_index_metadata_rows( $driver, 'like_parenthesized_copy' )
		);
	}

	/**
	 * Tests CREATE TABLE ... LIKE IF NOT EXISTS does not replace existing MySQL metadata.
	 */
	public function test_create_table_like_if_not_exists_preserves_existing_metadata(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query(
			'CREATE TABLE like_if_existing (
				id int NOT NULL,
				name varchar(20) NOT NULL,
				PRIMARY KEY (id),
				KEY name_key (name)
			)'
		);
		$driver->query(
			'CREATE TABLE like_if_source (
				changed bigint(20) NOT NULL,
				changed_text longtext DEFAULT NULL,
				KEY changed_key (changed)
			)'
		);

		$columns_before = $this->get_mysql_column_metadata_rows( $driver, 'like_if_existing' );
		$indexes_before = $this->get_mysql_index_metadata_rows( $driver, 'like_if_existing' );

		$this->assertSame(
			0,
			$driver->query( 'CREATE TABLE IF NOT EXISTS like_if_existing LIKE like_if_source' )
		);

		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( $columns_before, $this->get_mysql_column_metadata_rows( $driver, 'like_if_existing' ) );
		$this->assertSame( $indexes_before, $this->get_mysql_index_metadata_rows( $driver, 'like_if_existing' ) );
	}

	/**
	 * Tests CREATE TEMPORARY TABLE ... LIKE stores isolated temporary metadata.
	 */
	public function test_create_temporary_table_like_copies_metadata_to_temporary_schema(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$driver->query(
			"CREATE TABLE like_temp_source (
				id int NOT NULL,
				`value` varchar(20) NOT NULL DEFAULT 'source',
				PRIMARY KEY (id),
				KEY value_key (`value`)
			)"
		);

		$this->assertGreaterThanOrEqual( 0, $driver->query( 'CREATE TEMPORARY TABLE like_temp_copy LIKE like_temp_source' ) );
		$logged_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "like_temp_copy"', $logged_sql );

		$this->assertSame( array(), $this->get_mysql_column_metadata_rows( $driver, 'like_temp_copy' ) );
		$this->assertSame(
			array_column( $this->get_mysql_column_metadata_rows( $driver, 'like_temp_source' ), 'column_name' ),
			array_column( $this->get_mysql_column_metadata_rows( $driver, 'like_temp_copy', 'temp' ), 'column_name' )
		);
		$this->assertSame(
			array_column( $this->get_mysql_index_metadata_rows( $driver, 'like_temp_source' ), 'key_name' ),
			array_column( $this->get_mysql_index_metadata_rows( $driver, 'like_temp_copy', 'temp' ), 'key_name' )
		);

		$this->assertSame( 1, $driver->query( 'INSERT INTO like_temp_copy (id) VALUES (1)' ) );
		$rows = $driver->query( 'SELECT id, value FROM like_temp_copy' );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'source', $rows[0]->value );
	}

	/**
	 * Tests CREATE TABLE accepts MySQL storage-only table options as no-ops.
	 */
	public function test_create_table_storage_options_are_supported_noops(): void {
		$driver = $this->create_driver();
		$this->install_information_schema_fixture( $driver );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query(
				'CREATE TABLE wptests_create_table_options (
					id INTEGER NOT NULL,
					value TEXT,
					PRIMARY KEY (id)
				)
				KEY_BLOCK_SIZE=8
				MAX_ROWS=10
				MIN_ROWS=1
				AVG_ROW_LENGTH=100
				CHECKSUM=1
				DELAY_KEY_WRITE=1
				PACK_KEYS=1
				STATS_PERSISTENT=0
				STATS_AUTO_RECALC=1
				STATS_SAMPLE_PAGES=10
				COMPRESSION="zlib"
				ENCRYPTION="Y"
				DATA DIRECTORY "/tmp"
				INDEX DIRECTORY "/tmp"
				CONNECTION="mysql://x"
				PASSWORD="x"
				INSERT_METHOD=NO
				TABLESPACE ts
				SECONDARY_ENGINE=mock
				AUTOEXTEND_SIZE=4M
				UNION=(t1,t2)
				ENGINE_ATTRIBUTE="{}"
				SECONDARY_ENGINE_ATTRIBUTE="{}"'
			)
		);
		$this->assertSame(
			'CREATE TABLE "wptests_create_table_options" (
  "id" integer NOT NULL,
  "value" text,
  PRIMARY KEY ("id")
)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$columns = $driver->query( 'SHOW COLUMNS FROM wptests_create_table_options' );
		$this->assertSame( array( 'id', 'value' ), array_column( $columns, 'Field' ) );
		$this->assertSame( array( 'int', 'text' ), array_column( $columns, 'Type' ) );
	}

	/**
	 * Tests unsupported CREATE TABLE ... SELECT variants fail without backend execution.
	 */
	public function test_unsupported_create_table_select_constructs_fail_closed(): void {
		$driver = $this->create_driver();

		$queries = array(
			'partition before select' => 'CREATE TABLE ctas_partitioned PARTITION BY HASH(id) PARTITIONS 2 AS SELECT 1 AS id',
		);

		foreach ( $queries as $label => $query ) {
			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported CREATE TABLE statement to throw for ' . $label . '.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported CREATE TABLE statement.', $e->getMessage(), $label );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $label );
			}
		}
	}

	/**
	 * Tests CREATE TABLE ... LIKE fails closed when the source table has no metadata.
	 */
	public function test_create_table_like_missing_source_fails_closed(): void {
		$driver = $this->create_driver();

		try {
			$driver->query( 'CREATE TABLE like_missing_copy LIKE like_missing_source' );
			$this->fail( 'Expected unsupported CREATE TABLE LIKE statement to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported CREATE TABLE statement.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests CREATE VIEW with a MySQL column list is translated and queryable.
	 */
	public function test_create_view_with_column_list_translates_and_reads_rows(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE view_source (`id` INTEGER, `name` TEXT)' );
		$driver->query( "INSERT INTO view_source (`id`, `name`) VALUES (1, 'one'), (2, 'two')" );

		$this->assertGreaterThanOrEqual(
			0,
			$driver->query( 'CREATE VIEW view_copy (`item_id`, `item_name`) AS SELECT `id`, `name` FROM `view_source` WHERE `id` > 1' )
		);
		$this->assertSame(
			'CREATE VIEW "view_copy" ("item_id", "item_name") AS SELECT "id", "name" FROM "view_source" WHERE "id" > 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT item_id, item_name FROM view_copy ORDER BY item_id' );
		$this->assertEquals(
			array(
				(object) array(
					'item_id'   => '2',
					'item_name' => 'two',
				),
			),
			$rows
		);
	}

	/**
	 * Tests CREATE OR REPLACE VIEW and ALTER VIEW emit PostgreSQL CREATE OR REPLACE VIEW.
	 */
	public function test_create_or_replace_view_and_alter_view_translate_to_create_or_replace(): void {
		$connection = new WP_PostgreSQL_Driver_Alter_Table_Fixture_Connection();
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$this->assertSame(
			0,
			$driver->query( 'CREATE OR REPLACE VIEW view_replace (`item_id`) AS SELECT 1 AS `item_id`' )
		);
		$this->assertSame(
			'CREATE OR REPLACE VIEW "view_replace" ("item_id") AS SELECT 1 AS "item_id"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$this->assertSame(
			0,
			$driver->query( 'ALTER VIEW view_replace (`item_id`) AS SELECT 2 AS `item_id`' )
		);
		$this->assertSame(
			'CREATE OR REPLACE VIEW "view_replace" ("item_id") AS SELECT 2 AS "item_id"',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

