			$this->fail( 'Expected unsupported SQL-mode expression to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported SET statement.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests ANSI_QUOTES affects PostgreSQL query translation.
	 */
	public function test_ansi_quotes_sql_mode_treats_double_quoted_text_as_identifiers(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_posts ("ID" INTEGER PRIMARY KEY, post_title TEXT NOT NULL)' );
		$driver->query( 'INSERT INTO wptests_posts ("ID", post_title) VALUES (1, \'Hello\')' );

		$literal = $driver->query( 'SELECT "post_title" AS value' );
		$this->assertSame( 'post_title', $literal[0]->value );
		$this->assertSame(
			"SELECT 'post_title' AS value",
			$this->get_last_single_postgresql_sql( $driver )
		);

		$this->assertSame( 0, $driver->query( "SET SESSION sql_mode = 'ANSI_QUOTES'" ) );
		$rows = $driver->query( 'SELECT "ID", "post_title" FROM "wptests_posts" WHERE "ID" = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->ID );
		$this->assertSame( 'Hello', $rows[0]->post_title );
		$this->assertSame(
			'SELECT "ID", "post_title" FROM "wptests_posts" WHERE "ID" = 1',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests composite SQL modes expand and affect PostgreSQL tokenization.
	 */
	public function test_composite_sql_modes_expand_and_drive_postgresql_tokenization(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( "SET SESSION sql_mode = 'ANSI'" ) );
		$this->assertSame(
			'REAL_AS_FLOAT,PIPES_AS_CONCAT,ANSI_QUOTES,IGNORE_SPACE,ONLY_FULL_GROUP_BY',
			$driver->get_sql_mode()
		);
		$this->assertTrue( $driver->is_sql_mode_active( 'ANSI_QUOTES' ) );
		$this->assertTrue( $driver->is_sql_mode_active( 'PIPES_AS_CONCAT' ) );

		$driver->query( 'CREATE TABLE "wptests_ansi_mode" ("ID" INTEGER PRIMARY KEY, "post title" TEXT NOT NULL)' );
		$driver->query( 'INSERT INTO "wptests_ansi_mode" ("ID", "post title") VALUES (1, \'Hello\')' );
		$rows = $driver->query( 'SELECT "post title" FROM "wptests_ansi_mode" WHERE "ID" = 1' );
		$this->assertSame( 'Hello', $rows[0]->{'post title'} );
		$this->assertSame(
			'SELECT "post title" FROM "wptests_ansi_mode" WHERE "ID" = 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( "SELECT 'a' || 'b' AS value" );
		$this->assertSame( 'ab', $rows[0]->value );

		$this->assertSame( 0, $driver->query( "SET SESSION sql_mode = 'TRADITIONAL'" ) );
		$this->assertSame(
			'STRICT_TRANS_TABLES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION',
			$driver->get_sql_mode()
		);
		$this->assertFalse( $driver->is_sql_mode_active( 'ANSI_QUOTES' ) );

		$rows = $driver->query( 'SELECT "post title" AS value' );
		$this->assertSame( 'post title', $rows[0]->value );
		$this->assertSame(
			"SELECT 'post title' AS value",
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests NO_BACKSLASH_ESCAPES changes PostgreSQL string literal translation.
	 */
	public function test_no_backslash_escapes_sql_mode_changes_postgresql_string_literals(): void {
		$driver    = $this->create_driver();
		$backslash = chr( 92 );
		$query     = "SELECT '{$backslash}n' AS value";

		$driver->set_sql_mode( '' );
		$rows = $driver->query( $query );
		$this->assertSame( "\n", $rows[0]->value );

		$this->assertSame( 0, $driver->query( "SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES'" ) );
		$rows = $driver->query( $query );
		$this->assertSame( $backslash . 'n', $rows[0]->value );
	}

	/**
	 * Tests NO_BACKSLASH_ESCAPES disables PostgreSQL's default LIKE backslash escape.
	 */
	public function test_no_backslash_escapes_sql_mode_changes_postgresql_like_patterns(): void {
		$driver    = $this->create_driver();
		$backslash = chr( 92 );
		$query     = "SELECT value FROM wptests_like_escape WHERE value LIKE 'abc{$backslash}_' OR value NOT LIKE 'def{$backslash}%'";

		$driver->set_sql_mode( '' );
		$this->assertSame(
			"SELECT value FROM wptests_like_escape WHERE value LIKE 'abc{$backslash}_' OR value NOT LIKE 'def{$backslash}%'",
			$this->translate_driver_query_with_private_method( $driver, 'translate_mysql_compatible_query', $query )
		);

		$driver->set_sql_mode( 'NO_BACKSLASH_ESCAPES' );
		$this->assertSame(
			"SELECT value FROM wptests_like_escape WHERE value LIKE 'abc{$backslash}_' ESCAPE '' OR value NOT LIKE 'def{$backslash}%' ESCAPE ''",
			$this->translate_driver_query_with_private_method( $driver, 'translate_mysql_compatible_query', $query )
		);

		$cast_like_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT CAST(meta_value AS DECIMAL(10,2)) LIKE '12{$backslash}_' AS matched FROM wptests_postmeta"
		);
		$this->assertStringContainsString( "LIKE '12{$backslash}_' ESCAPE '' AS matched", $cast_like_sql );
		$this->assertStringNotContainsString( "ESCAPE '' ESCAPE ''", $cast_like_sql );

		$this->assertSame(
			"SELECT value FROM wptests_like_escape WHERE value LIKE 'abc{$backslash}_' ESCAPE '!'",
			$this->translate_driver_query_with_private_method(
				$driver,
				'translate_mysql_compatible_query',
				"SELECT value FROM wptests_like_escape WHERE value LIKE 'abc{$backslash}_' ESCAPE '!'"
			)
		);
	}

	/**
	 * Tests PIPES_AS_CONCAT switches || from logical OR to concatenation.
	 */
	public function test_pipes_as_concat_sql_mode_changes_postgresql_double_pipe_translation(): void {
		$driver = $this->create_driver();

		$driver->set_sql_mode( '' );
		$rows = $driver->query( 'SELECT 0 || 1 AS value' );
		$this->assertSame( '1', (string) $rows[0]->value );
		$this->assertSame( 'SELECT 0 OR 1 AS value', $this->get_last_single_postgresql_sql( $driver ) );

		$this->assertSame( 0, $driver->query( "SET SESSION sql_mode = 'PIPES_AS_CONCAT'" ) );
		$rows = $driver->query( "SELECT 'a' || 'b' AS value" );
		$this->assertSame( 'ab', $rows[0]->value );
		$this->assertSame( "SELECT 'a' || 'b' AS value", $this->get_last_single_postgresql_sql( $driver ) );
	}

