		$this->assertStringContainsString( ', 9', $this->get_last_single_postgresql_sql( $driver ) );
	}

	/**
	 * Tests GROUP_CONCAT(expr, expr, ...) concatenates row expressions before aggregation.
	 */
	public function test_group_concat_multi_expression_rows_are_concatenated_before_aggregation(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				2 => 'two',
				1 => 'one',
				3 => 'three',
			)
		);

		$rows = $driver->query( "SELECT GROUP_CONCAT(id, ':', value ORDER BY id SEPARATOR '|') AS combined FROM group_concat_values" );

		$this->assertSame( '1:one|2:two|3:three', $rows[0]->combined );
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( "CAST(id AS text) || CAST(':' AS text) || CAST(value AS text)", $sql );
		$this->assertStringContainsString( "STRING_AGG(CAST(CAST(id AS text) || CAST(':' AS text) || CAST(value AS text) AS text), CAST('|' AS text) ORDER BY id)", $sql );
		$this->assertStringNotContainsString( 'GROUP_CONCAT', $sql );
	}

	/**
	 * Tests GROUP_CONCAT multi-expression rows preserve NULL skip semantics.
	 */
	public function test_group_concat_multi_expression_rows_skip_null_composites(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE group_concat_multi_values (
				id INTEGER PRIMARY KEY,
				prefix TEXT NOT NULL,
				suffix TEXT NULL
			)'
		);
		$driver->query(
			"INSERT INTO group_concat_multi_values (id, prefix, suffix) VALUES
				(1, 'a', '1'),
				(2, 'b', NULL),
				(3, 'c', '3')"
		);

		$rows = $driver->query( "SELECT GROUP_CONCAT(prefix, suffix ORDER BY id SEPARATOR ',') AS combined FROM group_concat_multi_values" );

		$this->assertSame( 'a1,c3', $rows[0]->combined );
	}

	/**
	 * Tests GROUP_CONCAT(DISTINCT expr) deduplicates values and keeps group_concat_max_len behavior.
	 */
	public function test_group_concat_distinct_default_separator_deduplicates_values(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				1 => 'alpha',
				2 => 'beta',
				3 => 'alpha',
				4 => 'beta',
			)
		);

		$rows  = $driver->query( 'SELECT GROUP_CONCAT(DISTINCT value) AS combined FROM group_concat_values' );
		$parts = explode( ',', $rows[0]->combined );
		sort( $parts );

		$this->assertSame( array( 'alpha', 'beta' ), $parts );
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'GROUP_CONCAT(DISTINCT CAST(value AS text))', $sql );
		$this->assertStringContainsString( ', 1024', $sql );
	}

	/**
	 * Tests GROUP_CONCAT(DISTINCT expr SEPARATOR literal) translates for PostgreSQL.
	 */
	public function test_group_concat_distinct_literal_separator_translates_for_postgresql(): void {
		$connection = new class( array( 'pdo' => new PDO( 'sqlite::memory:' ) ) ) extends WP_PostgreSQL_Connection {
			public function get_driver_name(): string {
				return 'pgsql';
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT GROUP_CONCAT(DISTINCT value SEPARATOR '|') AS combined FROM group_concat_values"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( "STRING_AGG(DISTINCT CAST(value AS text), CAST('|' AS text))", $sql );
		$this->assertStringNotContainsString( 'GROUP_CONCAT', $sql );
	}

	/**
	 * Tests GROUP_CONCAT(DISTINCT expr ORDER BY expr) translates for PostgreSQL.
	 */
	public function test_group_concat_distinct_order_by_same_expression_translates_for_postgresql(): void {
		$connection = new class( array( 'pdo' => new PDO( 'sqlite::memory:' ) ) ) extends WP_PostgreSQL_Connection {
			public function get_driver_name(): string {
				return 'pgsql';
			}
		};
		$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT GROUP_CONCAT(DISTINCT value ORDER BY value DESC SEPARATOR '|') AS combined FROM group_concat_values"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString(
			"STRING_AGG(DISTINCT CAST(value AS text), CAST('|' AS text) ORDER BY CAST(value AS text) DESC)",
			$sql
		);
		$this->assertStringNotContainsString( 'GROUP_CONCAT', $sql );
	}

	/**
	 * Tests unsupported GROUP_CONCAT() forms fail before backend execution.
	 */
	public function test_unsupported_group_concat_forms_fail_closed_before_backend_execution(): void {
		$queries = array(
			'SELECT GROUP_CONCAT(DISTINCT id, value) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(DISTINCT value ORDER BY id) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(DISTINCT value ORDER BY value, id) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(DISTINCT value SEPARATOR separator_value) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(value ORDER id) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(value SEPARATOR) AS combined FROM group_concat_values',
			'SELECT GROUP_CONCAT(value SEPARATOR "," SEPARATOR "|") AS combined FROM group_concat_values',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported GROUP_CONCAT() form to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL runtime function form.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests unsafe GROUP_CONCAT length SET forms fail before reaching PDO.
	 */
	public function test_unsupported_group_concat_max_len_set_forms_fail_closed(): void {
		$queries = array(
			'SET GLOBAL group_concat_max_len = 1000000',
			'SET GLOBAL group_concat_max_len = DEFAULT',
			'SET @@GLOBAL.group_concat_max_len = 1000000',
			'SET @@GLOBAL.group_concat_max_len = DEFAULT',
			'SET SESSION group_concat_max_len = OFF',
			'SET SESSION group_concat_max_len = 1 + 1',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SET statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SET statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests comma-separated boolean SET assignments are applied atomically.
	 */
	public function test_comma_separated_boolean_set_assignments_are_atomic(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( 'SET autocommit = ON, big_tables = OFF' ) );

		$rows = $driver->query( 'SELECT @@autocommit, @@big_tables' );
		$this->assertSame( '1', $rows[0]->{'@@autocommit'} );
		$this->assertSame( '0', $rows[0]->{'@@big_tables'} );

		try {
			$driver->query( 'SET autocommit = OFF, unsupported_setting = 1' );
			$this->fail( 'Expected unsupported SET statement to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported SET statement.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}

		$rows = $driver->query( 'SELECT @@autocommit, @@big_tables' );
		$this->assertSame( '1', $rows[0]->{'@@autocommit'} );
		$this->assertSame( '0', $rows[0]->{'@@big_tables'} );
	}

	/**
	 * Tests user variables can be set, incremented, selected, and used for restore.
	 */
	public function test_user_variables_can_be_set_incremented_selected_and_used_for_restore(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( 'SET @my_var = 1' ) );
		$rows = $driver->query( 'SELECT @my_var' );
		$this->assertSame( '1', $rows[0]->{'@my_var'} );

		$this->assertSame( 0, $driver->query( 'SET @my_var = @my_var + 1' ) );
		$rows = $driver->query( 'SELECT @my_var' );
		$this->assertSame( '2', $rows[0]->{'@my_var'} );

		$this->assertSame( 0, $driver->query( 'SET @saved_cs_client = @@character_set_client' ) );
		$this->assertSame( 0, $driver->query( 'SET character_set_client = latin1' ) );

		$rows = $driver->query( 'SELECT @@character_set_client' );
		$this->assertSame( 'latin1', $rows[0]->{'@@character_set_client'} );

		$this->assertSame( 0, $driver->query( 'SET character_set_client = @saved_cs_client' ) );
		$rows = $driver->query( 'SELECT @@character_set_client' );
		$this->assertSame( 'utf8mb4', $rows[0]->{'@@character_set_client'} );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests conditional-comment SET wrappers work for supported backup and restore forms.
	 */
	public function test_conditional_comment_set_wrappers_handle_supported_backup_and_restore(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( '/*!50503 SET NAMES utf8 */;' ) );
		$this->assertSame( 0, $driver->query( '/*!40101 SET @saved_cs_client = @@character_set_client */; ' ) );
		$this->assertSame( 0, $driver->query( '/*!50503 SET character_set_client = latin1 */;' ) );

		$rows = $driver->query( 'SELECT @@character_set_client' );
		$this->assertSame( 'latin1', $rows[0]->{'@@character_set_client'} );

		$this->assertSame( 0, $driver->query( '/*!40101 SET character_set_client = @saved_cs_client */;' ) );
		$rows = $driver->query( 'SELECT @@character_set_client' );
		$this->assertSame( 'utf8', $rows[0]->{'@@character_set_client'} );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests SHOW VARIABLES LIKE honors MySQL wildcard patterns.
	 */
	public function test_show_variables_like_matches_wildcard_patterns(): void {
		$driver = $this->create_driver();

		$rows = $driver->query( "SHOW VARIABLES LIKE 'character_set_%'" );

		$this->assertSame(
			array(
				'character_set_client',
				'character_set_connection',
				'character_set_results',
				'character_set_database',
				'character_set_server',
			),
			array_map(
				static function ( $row ) {
					return $row->Variable_name;
				},
				$rows
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests unsupported SET statements fail before reaching PDO.
	 */
	public function test_unsupported_set_statements_do_not_reach_backend(): void {
		$driver = $this->create_driver();

		foreach (
			array(
				'SET unsupported_setting = 1',
				'SET foreign_key_checks = 0, unsupported_setting = 1',
				'SET autocommit = 1 + 1',
				'SET @my_var = @my_var * 1',
				"SET @@version = '8.0.39'",
			) as $query
		) {
			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SET statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SET statement.', $e->getMessage() );
				$this->assertSame( $query, $driver->get_last_mysql_query() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}
		}
	}

	/**
	 * Install a PostgreSQL-like options table and matching MySQL column metadata.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 */
	private function install_options_table_with_mysql_metadata( WP_PostgreSQL_Driver $driver ): void {
		$driver->query(
			'CREATE TABLE wptests_options (
				option_name TEXT NOT NULL UNIQUE,
				option_value TEXT NOT NULL,
				autoload TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_options (
				option_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				option_name varchar(191) NOT NULL DEFAULT '',
				option_value longtext NOT NULL,
				autoload varchar(20) NOT NULL DEFAULT 'yes',
				PRIMARY KEY (option_id),
				UNIQUE KEY option_name (option_name)
			)"
		);
	}

	/**
	 * Install a PostgreSQL-like posts table with MySQL datetime metadata.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 */
	private function install_posts_datetime_table_with_mysql_metadata( WP_PostgreSQL_Driver $driver ): void {
		$driver->query(
			'CREATE TABLE wptests_posts (
				"ID" INTEGER PRIMARY KEY,
				post_date TEXT NOT NULL,
				post_date_gmt TEXT NOT NULL,
				post_modified TEXT NOT NULL,
				post_modified_gmt TEXT NOT NULL
			)'
		);
		$driver->store_mysql_schema_metadata(
			"CREATE TABLE wptests_posts (
				ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				post_date datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
				post_date_gmt datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
				post_modified datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
				post_modified_gmt timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
				PRIMARY KEY (ID)
			)"
		);
	}

	/**
	 * Install a DML coercion table with temporal/YEAR MySQL metadata.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 */
	private function install_strict_dml_values_table_with_mysql_metadata( WP_PostgreSQL_Driver $driver ): void {
		$driver->query(
			'CREATE TABLE wptests_strict_values (
				id INTEGER PRIMARY KEY,
				date_value TEXT,
				datetime_value TEXT,
				timestamp_value TEXT,
				year_value TEXT
			)'
		);
