	/**
	 * Creates a PostgreSQL driver backed by an injected in-memory PDO.
	 *
	 * @return WP_PostgreSQL_Driver
	 */
	private function create_driver( string $db_name = 'wptests' ): WP_PostgreSQL_Driver {
		$connection = new WP_PostgreSQL_Connection( array( 'pdo' => new PDO( 'sqlite::memory:' ) ) );
		return new WP_PostgreSQL_Driver( $connection, $db_name );
	}

	/**
	 * Create a SQLite PDO fixture that reports pgsql for catalog-branch selection.
	 *
	 * @return PDO SQLite PDO that reports the pgsql driver name.
	 */
	private function create_pgsql_reporting_sqlite_pdo(): PDO {
		return new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql while keeping SQLite execution for local tests.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
	}

	/**
	 * Creates a pgsql-reporting SQLite driver with catalog unique-key fixtures.
	 *
	 * @return array{0: WP_PostgreSQL_Driver, 1: WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection, 2: PDO}
	 */
	private function create_pgsql_catalog_unique_index_driver(): array {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured unique-index catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_index_queries = array();

			/**
			 * Execute fixture-backed catalog queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
					) as $metadata_table
				) {
					if ( false !== strpos( $sql, $metadata_table ) ) {
						throw new RuntimeException( 'Hidden MySQL metadata table access was not expected for catalog-backed unique indexes.' );
					}
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					return parent::query(
						"SELECT 'pk' AS column_name, 1 AS ordinal_position, 'integer' AS column_type, 'NO' AS is_nullable, NULL AS column_default, '' AS extra
						UNION ALL SELECT 'slug', 2, 'text', 'NO', NULL, ''
						UNION ALL SELECT 'value', 3, 'text', 'NO', NULL, ''"
					);
				}

				if ( false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					$this->catalog_index_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						"SELECT 'slug_key' AS key_name, 'slug' AS column_name, 'BTREE' AS index_type, NULL AS sub_part"
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured unique-index catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_index_queries(): array {
				return $this->catalog_index_queries;
			}
		};

		return array( new WP_PostgreSQL_Driver( $connection, 'wptests' ), $connection, $pdo );
	}

	/**
	 * Creates a pgsql-reporting SQLite driver with catalog identity and unique-key fixtures.
	 *
	 * @return array{0: WP_PostgreSQL_Driver, 1: WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection, 2: PDO}
	 */
	private function create_pgsql_catalog_identity_unique_upsert_driver(): array {
		$pdo        = new class( 'sqlite::memory:' ) extends PDO {
			/**
			 * Report pgsql for catalog-branch selection while keeping SQLite execution.
			 *
			 * @param int $attribute PDO attribute.
			 * @return mixed Attribute value.
			 */
			#[\ReturnTypeWillChange]
			public function getAttribute( $attribute ) {
				if ( PDO::ATTR_DRIVER_NAME === $attribute ) {
					return 'pgsql';
				}

				return parent::getAttribute( $attribute );
			}
		};
		$connection = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection_Pgsql_Quote_SQLite_Connection {
			/**
			 * Captured column catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_column_queries = array();

			/**
			 * Captured unique-index catalog queries.
			 *
			 * @var array[]
			 */
			private $catalog_index_queries = array();

			/**
			 * Number of sequence repair queries executed.
			 *
			 * @var int
			 */
			private $sequence_sync_query_count = 0;

			/**
			 * Execute fixture-backed catalog queries.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				foreach (
					array(
						WP_PostgreSQL_Driver::MYSQL_COLUMN_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_INDEX_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_FOREIGN_KEY_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_CHECK_METADATA_TABLE,
						WP_PostgreSQL_Driver::MYSQL_TABLE_METADATA_TABLE,
					) as $metadata_table
				) {
					if ( false !== strpos( $sql, $metadata_table ) ) {
						throw new RuntimeException( 'Hidden MySQL metadata table access was not expected for catalog-backed identity upserts.' );
					}
				}

				if ( false !== strpos( $sql, 'pg_my_temp_schema()' ) ) {
					return parent::query( 'SELECT NULL AS nspname WHERE 0 = 1' );
				}

				if ( false !== strpos( $sql, 'pg_catalog.setval' ) ) {
					++$this->sequence_sync_query_count;
					return parent::query( 'SELECT 1' );
				}

				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$this->catalog_column_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					if ( false !== strpos( $sql, 'seq_ns.nspname AS sequence_schema' ) ) {
						return parent::query(
							"SELECT
								'id' AS column_name,
								'bigint' AS data_type,
								'YES' AS is_identity,
								NULL AS column_default,
								'bigint(20)' AS mysql_column_type,
								'auto_increment' AS mysql_extra,
								'public' AS sequence_schema,
								'wp_acid_upsert_id_seq' AS sequence_name"
						);
					}

					if ( false !== strpos( $sql, 'LOWER(c.column_name) = LOWER(?)' ) ) {
						return parent::query(
							'SELECT column_type
							FROM (
								SELECT \'id\' AS column_name, \'bigint(20)\' AS column_type
								UNION ALL SELECT \'slug\', \'varchar(191)\'
								UNION ALL SELECT \'hits\', \'int(11)\'
								UNION ALL SELECT \'updated_at\', \'datetime\'
							) catalog_columns
							WHERE LOWER(column_name) = LOWER(?)',
							array( $params[2] ?? '' )
						);
					}

					return parent::query(
						"SELECT
							'id' AS column_name,
							1 AS ordinal_position,
							'bigint(20)' AS column_type,
							'NO' AS is_nullable,
							NULL AS column_default,
							'auto_increment' AS extra
						UNION ALL
						SELECT 'slug', 2, 'varchar(191)', 'NO', NULL, ''
						UNION ALL
						SELECT 'hits', 3, 'int(11)', 'NO', '0', ''
						UNION ALL
						SELECT 'updated_at', 4, 'datetime', 'NO', NULL, ''"
					);
				}

				if ( false !== strpos( $sql, 'pg_catalog.pg_index i' ) ) {
					$this->catalog_index_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);

					return parent::query(
						"SELECT 'slug' AS key_name, 'slug' AS column_name, 'BTREE' AS index_type, NULL AS sub_part"
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured column catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_column_queries(): array {
				return $this->catalog_column_queries;
			}

			/**
			 * Get captured unique-index catalog queries.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_index_queries(): array {
				return $this->catalog_index_queries;
			}

			/**
			 * Get the number of sequence repair queries executed.
			 *
			 * @return int Sequence repair query count.
			 */
			public function get_sequence_sync_query_count(): int {
				return $this->sequence_sync_query_count;
			}
		};

		return array( new WP_PostgreSQL_Driver( $connection, 'wptests' ), $connection, $pdo );
	}

	/**
	 * Creates a small table for GROUP_CONCAT behavior tests.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 * @param array<int, string>   $rows   Values keyed by integer ID.
	 */
	private function create_group_concat_values_table( WP_PostgreSQL_Driver $driver, array $rows ): void {
		$driver->query( 'CREATE TABLE group_concat_values (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );

		foreach ( $rows as $id => $value ) {
			$driver->query(
				sprintf(
					'INSERT INTO group_concat_values (id, value) VALUES (%d, %s)',
					$id,
					$driver->get_connection()->quote( $value )
				)
			);
		}
	}

	/**
	 * Creates a PostgreSQL driver with tables used by index hint translation tests.
	 *
	 * @return WP_PostgreSQL_Driver Driver under test.
	 */
	private function create_driver_with_index_hint_tables(): WP_PostgreSQL_Driver {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE t (id INTEGER, value TEXT)' );
		$driver->query( 'CREATE TABLE j (t_id INTEGER, value TEXT)' );

		return $driver;
	}

	/**
	 * Get the last single PostgreSQL SQL statement executed by a driver.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 * @return string Last PostgreSQL SQL.
	 */
	private function get_last_single_postgresql_sql( WP_PostgreSQL_Driver $driver ): string {
		$queries = $driver->get_last_postgresql_queries();

		$this->assertCount( 1, $queries );
		return $queries[0]['sql'];
	}

	/**
	 * Assert the last logged PostgreSQL SQL statements without parameters.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 * @param string[]             $sql    Expected SQL statements.
	 */
	private function assert_last_postgresql_sql_statements( WP_PostgreSQL_Driver $driver, array $sql ): void {
		$this->assertSame(
			array_map(
				static function ( string $statement ): array {
					return array(
						'sql'    => $statement,
						'params' => array(),
					);
				},
				$sql
			),
			$driver->get_last_postgresql_queries()
		);
	}

	/**
	 * Assert the last query used the materialized INSERT ... SELECT upsert flow.
	 *
	 * @param WP_PostgreSQL_Driver $driver     Driver under test.
	 * @param string               $table_name Target table name.
	 * @return string[] Logged SQL statements.
	 */
	private function assert_last_upsert_select_materialized_sql( WP_PostgreSQL_Driver $driver, string $table_name ): array {
		$queries = $driver->get_last_postgresql_queries();
		$this->assertGreaterThanOrEqual( 4, count( $queries ) );

		$sql = array_column( $queries, 'sql' );
		$this->assertRegExp( '/^DROP TABLE IF EXISTS "__wp_pg_upsert_select_[a-f0-9]{12}"$/', $sql[0] );
		$this->assertSame( $sql[0], $sql[3] );
		$this->assertRegExp( '/^CREATE TEMPORARY TABLE "__wp_pg_upsert_select_[a-f0-9]{12}" AS SELECT /', $sql[1] );
		$this->assertStringStartsWith(
			sprintf(
				'INSERT INTO "%s" ',
				$table_name
			),
			$sql[2]
		);
		$this->assertStringContainsString( ' FROM "__wp_pg_upsert_select_', $sql[2] );
		$this->assertStringContainsString( ' WHERE 1 = 1 ON CONFLICT ', $sql[2] );

		return $sql;
	}

	/**
	 * Assert the last query used the materialized REPLACE ... SELECT flow.
	 *
	 * @param WP_PostgreSQL_Driver $driver     Driver under test.
	 * @param string               $table_name Target table name.
	 * @return string[] Logged SQL statements.
	 */
	private function assert_last_replace_select_materialized_sql( WP_PostgreSQL_Driver $driver, string $table_name ): array {
		$queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 5, $queries );

		$sql = array_column( $queries, 'sql' );
		$this->assertRegExp( '/^DROP TABLE IF EXISTS "__wp_pg_replace_select_[a-f0-9]{12}"$/', $sql[0] );
		$this->assertSame( $sql[0], $sql[4] );
		$this->assertRegExp( '/^CREATE TEMPORARY TABLE "__wp_pg_replace_select_[a-f0-9]{12}" AS SELECT /', $sql[1] );
		$this->assertStringStartsWith(
			'DELETE FROM "' . $table_name . '" AS "__wp_pg_replace_target" WHERE EXISTS (SELECT 1 FROM "__wp_pg_replace_select_',
			$sql[2]
		);
		$this->assertStringStartsWith(
			'INSERT INTO "' . $table_name . '" ',
			$sql[3]
		);

		return $sql;
	}

	/**
	 * Get the first logged PostgreSQL SQL statement containing a string.
	 *
	 * @param array[] $queries Logged PostgreSQL query records.
	 * @param string  $needle  SQL fragment to find.
	 * @return string Matching SQL statement.
	 */
	private function get_logged_postgresql_sql_containing( array $queries, string $needle ): string {
		foreach ( $queries as $query ) {
			if ( false !== strpos( $query['sql'], $needle ) ) {
				return $query['sql'];
			}
		}

		$this->fail( 'Expected PostgreSQL SQL containing: ' . $needle );
	}

	/**
	 * Assert a PostgreSQL SQL string does not contain raw MySQL index hints.
	 *
	 * @param string $sql PostgreSQL SQL.
	 */
	private function assert_postgresql_sql_omits_mysql_index_hints( string $sql ): void {
		$uppercase_sql = strtoupper( $sql );
		foreach ( array( 'USE INDEX', 'USE KEY', 'FORCE INDEX', 'FORCE KEY', 'IGNORE INDEX', 'IGNORE KEY' ) as $hint ) {
			$this->assertStringNotContainsString( $hint, $uppercase_sql );
		}
	}

